import { useQuery } from "react-query";
import { mainUrl, config } from "../../../api/api";
import axios from "axios";

const useReportLeadsStatusList = ({searchState}) => 
{
    return useQuery(["reportLeadsStatusList", searchState], () => {
        return axios.get(
            `${mainUrl}/dashboard/report-leads/status-new?start_date=${
                searchState.start
            }&end_date=${
                searchState.end
            }&company_id=${searchState.companyId}&${
                searchState.userType === "bum" || searchState.userType === "hs" || searchState.userType === "store_leader"
                ? "supervisor_id=" + parseInt(searchState.userId)
                : searchState.userType === "store"
                    ? "channel_id=" + parseInt(searchState.userId)
                    : "sales_id=" + parseInt(searchState.userId)
            }&status=${searchState.status?.toUpperCase()}&perPage=100&page=${searchState.count}`,
            config
        ).then((res) => res.data)
        .catch((error) => error)
    }, {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity})
}

export default useReportLeadsStatusList


