import axios from "axios";
import moment from "moment";
import React, { useEffect, useState } from "react";
import { Link, useParams } from "react-router-dom";
import { mainUrl } from "../../api/api";
import { formatCurrency } from "../../api/format";
import FilterLeadsReport from "../FilterForm/FilterLeadsReport";
import Header from "../Header/Header";
import Loaded from "../Loaded/Loaded";

const SalesEstimation = () => {
  const { user_type, user_id, start, end } = useParams();
  const params = useParams()
  //   filter
  const [filterStartDate, setFilterStartDate] = useState(
    start === "now" ? "" : start
  );
  const [filterEndDate, setFilterEndDate] = useState(end === "now" ? "" : end);

  const [salesEstimationData, setSalesEstimationData] = useState(null);
  useEffect(() => {
    const startDate = localStorage.getItem("date_leads_start")
        
    const endDate = localStorage.getItem("date_leads_end");
    if(startDate === undefined || startDate === null){
      localStorage.setItem("date_leads_start", params.start === "now" ? "" : params.start)
      if(endDate === undefined || endDate === null){
        localStorage.setItem("date_leads_end", params.end === "now" ? "" : params.end);
      }
     
    }
  },[params])
  useEffect(() => {
    const getSalesEstimation = async () => {
      const isTypeUser = await localStorage.getItem("user_type_leads_filter");
      const isChannels = await localStorage.getItem("channels_leads_filter");
      try {
        const res = await axios.get(
          `${mainUrl}/dashboard/sales-estimation/all?start_at=${
            filterStartDate && moment(filterStartDate).format("YYYY-MM-DD")
          }&end_at=${
            filterEndDate && moment(filterEndDate).format("YYYY-MM-DD")
          }&${
            isTypeUser === "sales"
          ?"sales_id=" + parseInt(user_id ?? "")
          : isTypeUser === "store"
            ? "channel_id=" + parseInt(user_id ?? "")
            : "supervisor_id=" + parseInt(user_id ?? "")
          }`,
          {
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${localStorage.token}`,
            },
          }
        );
        const salesEstimation = [];
        for (const [key, value1] of Object.entries(res.data)) {
          let data = [];
          for (const [key, value] of Object.entries(value1)) {
            data.push(value);
          }
          salesEstimation.push({ data: data });
        }
        setSalesEstimationData(salesEstimation);
      } catch (error) {
        console.error(error);
      }
    };
    getSalesEstimation();
  }, [filterStartDate, filterEndDate, user_type, user_id]);

  const exportSalesEstimation = async () => {
    const isTypeUser =  await localStorage.getItem("user_type_leads_filter");
    const isChannels =  await localStorage.getItem("channels_leads_filter");
    axios
      .get(
        `${mainUrl}/dashboard/sales-estimation/all?start_at=${
          filterStartDate && moment(filterStartDate).format("YYYY-MM-DD")
        }&end_at=${
          filterEndDate && moment(filterEndDate).format("YYYY-MM-DD")
        }&${
          isTypeUser === "sales"
          ?"sales_id=" + parseInt(user_id ?? "")
          : isTypeUser === "store"
            ? "channel_id=" + parseInt(user_id ?? "")
            : "supervisor_id=" + parseInt(user_id ?? "")
        }&is_export=1`,
        {
          method: "GET",
          responseType: "blob", // important
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${localStorage.token}`,
          },
        }
      )
      .then((response) => {
        const url = window.URL.createObjectURL(new Blob([response.data]));
        const link = document.createElement("a");
        link.href = url;
        link.setAttribute(
          "download",
          `Report sales estimation ${moment(filterStartDate).format(
            "YYYY-MM-DD"
          )} - ${moment(filterEndDate).format("YYYY-MM-DD")}.xlsx`
        );
        document.body.appendChild(link);
        link.click();
      })
      .catch((err) => {
        console.log();
      });
  };

  const sortUp = () => {
    setSalesEstimationData(salesEstimationData.sort());
  };

  return salesEstimationData ? (
    <div>
      <Header title={`Sales Estimation`} back={true} notif={true} />

      <FilterLeadsReport
        company={false}
        channel={false}
        supervisor={false}
        setFilterStartDate={setFilterStartDate}
        setFilterEndDate={setFilterEndDate}
        download={exportSalesEstimation}
      />

      <div className="mt-4">
        <table className="data" style={{ margin: "10px 0" }}>
          <thead>
            <tr>
              <th>No</th>
              <th>Date</th>
              <th onClick={() => sortUp()}>Sales</th>
              <th>Customer Name</th>
              <th>Brand</th>
              <th>Estimated Value</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {salesEstimationData &&
              salesEstimationData.map((data, i) => {
                return (
                  <tr key={i}>
                    <td>{i + 1}.</td>
                    <td>
                      {moment(data.data[0].created_at).format("YYYY-MM-DD")}
                    </td>
                    <td>{data.data[0].sales}</td>
                    <td>{data.data[0].customer}</td>
                    <td>
                      <ul>
                        {data.data.map((d, i) => {
                          return <li key={i}>{d.brand}</li>;
                        })}
                      </ul>
                    </td>
                    <td>
                      <ul>
                        {data.data.map((d, i) => {
                          return (
                            <li key={i}>{formatCurrency(d.estimated_value)}</li>
                          );
                        })}
                      </ul>
                    </td>
                    <td>
                      <Link
                        to={`/dashboard/customers/customer_detail/${data.data[0].lead_id}/${data.data[0].customer_id}`}
                      >
                        Leads Detail
                      </Link>
                    </td>
                  </tr>
                );
              })}
          </tbody>
        </table>
      </div>
    </div>
  ) : (
    <Loaded />
  );
};

export default SalesEstimation;
