const redirectPage = (
    data,
    slugType,
    textButton,
    newFilterDate,
    dataType = "",
    seeDetailsData,
    pathName,
    chdPath = "",
    history
  ) => {
    return history.push({
      pathname: `see-details/${pathName}${chdPath !== "" ? "/" + chdPath : ""}`,
      state: {
        data: data,
        invoiceType: slugType,
        typeUser: textButton?.toLowerCase(),
        formatDate: newFilterDate,
        statusActive: slugType === seeDetailsData[2].name ? 1 : 0,
        statusActv: dataType,
      },
    });
  };
export const directToNextPage = (data,event, newFilterDate, textButton, user, history) => {
    const seeDetailsData = [
        {
          name: "deals",
          epTyp: "invoice",
          val: data.deals.value,
        },
        {
          name: "new-leads",
          epTyp: "leads",
          val: data.new_leads.value,
        },
        {
          name: "active-leads",
          epTyp: "leads",
          val: data.active_leads.value,
        },
        {
          name: "interior-design",
          epTyp: "interior-design",
          val: data.interior_design.value,
        },
        {
          name: "retail",
          epTyp: "invoice",
          val: data.retail.value,
        },
        {
          name: "quotation",
          epTyp: "invoice",
          val: data.quotation.value,
        },
        {
          name: "pipelines",
          epTyp: "brand-details",
          val: data.estimation.value,
        },
        {
          name: "follow-up",
          epTyp: "brand-details",
          val: data.estimation.value,
          chdName: ["HOW", "WARM", "COLD"],
        },
      ];
      const dataType = event.target.dataset?.statusType;
      if (user?.data?.as.toUpperCase() !== "DIRECTR") {
        for (let i = 0; i <= seeDetailsData.length - 1; i++) {
          const seeDetail = seeDetailsData[i];
          const slugType = seeDetailsData[i].name;
          if (
            slugType.toUpperCase() === dataType.toUpperCase() ||
            seeDetail?.chdName !== undefined
          ) {
            if (
              dataType.toUpperCase() === "DEALS" ||
              dataType.toUpperCase() === "QUOTATION" ||
              dataType.toUpperCase() === "RETAIL"
            ) {
              redirectPage(
                data,
                slugType,
                textButton,
                newFilterDate,
                dataType,
                seeDetailsData,
                "invoice",
                "",
                history
              );
              break;
            }
            if (dataType.toUpperCase() === "INTERIOR-DESIGN") {
              redirectPage(
                data,
                slugType,
                textButton,
                newFilterDate,
                dataType,
                seeDetailsData,
                "interior-design",
                "",
                history
              );
              break;
            }
            if (
              dataType.toUpperCase() === "NEW-LEADS" ||
              dataType.toUpperCase() === "ACTIVE-LEADS"
            ) {
              redirectPage(
                data,
                slugType,
                textButton,
                newFilterDate,
                dataType,
                seeDetailsData,
                "leads",
                "",
                history
              );
              break;
            }
            if (dataType.toUpperCase() === "PIPELINES") {
              redirectPage(
                data,
                slugType,
                textButton,
                newFilterDate,
                dataType,
                seeDetailsData,
                "pipelines",
                "",
                history
              );
              break;
            }
            if (dataType.toUpperCase() === "FOLLOW-UP") {
              redirectPage(
                data,
                slugType,
                textButton,
                newFilterDate,
                dataType,
                seeDetailsData,
                "follow-up",
                "",
                history
              );
              break;
            }
            if (
              dataType.toUpperCase() === "HOT" ||
              dataType.toUpperCase() === "WARM" ||
              dataType.toUpperCase() === "COLD"
            ) {
              redirectPage(
                data,
                slugType,
                textButton,
                newFilterDate,
                dataType,
                seeDetailsData,
                "follow-up",
                dataType,
                history
              );
              break;
            }
          }
        }
      }
}