import axios from "axios";
import React, { useEffect, useState, useContext } from "react";
import { Redirect } from "react-router-dom";
import { useParams, useHistory } from "react-router-dom";
import { mainUrl } from "../../../../api/api";
import { formatCurrency } from "../../../../api/format";
import Button from "../../../../components/Button/Button";
import Header from "../../../../components/Header/Header";
import Loaded from "../../../../components/Loaded/Loaded";
import CurrencyInput from 'react-currency-input-field';
import NotificationContext from "../../../../store/notification-context";
const ConfirmPayment = () => {
  const notificationCtx = useContext(NotificationContext);
  const history = useHistory();
  const { orderId, payment_type_id } = useParams();
  const [shippingAdds, setShippingAdds] = useState(null)
  const [orderData, setOrderData] = useState(null);
  const [paymentData, setPaymentData] = useState(null);
  const [paymentDetailActive, setPaymentDetailActive] = useState(false);
  const [redirect, setRedirect] = useState(false);
  const [amount, setAmount] = useState(0);
  const [reference, setReference] = useState("");
  useEffect(() => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
    const getOrderData = async () => {
      try {
        const res = await axios.get(
          `${mainUrl}/orders?filter[id]=${orderId}`,
          config
        );
        const isOrderData = res?.data?.data[0] ?? null
        setOrderData(res.data.data[0]);
        if(isOrderData !== null){
          setShippingAdds(isOrderData?.shipping_address?.address_line_1)
        }
      } catch (error) {
        console.error(error);
      }
    };

    const getPayment = async () => {
      try {
        const res = await axios.get(
          `${mainUrl}/payments?filter[order_id]=${orderId}`,
          config
        );
        setPaymentData(res.data.data[0]);
      } catch (error) {
        console.error(error);
      }
    };
    getOrderData();
    getPayment();
  }, [orderId]);

  const handleSubmit = async () => {
    
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };

    const data = {
      amount: parseInt(amount),
      reference: reference,
      payment_type_id: parseInt(payment_type_id),
      order_id: parseInt(orderId),
      shipping_address: shippingAdds ?? ""
    };

  
      axios.post(`${mainUrl}/payments`, data, config).then((res) => {
      
        setAmount("");
        setReference("");
        localStorage.setItem("payment", JSON.stringify(res?.data?.data))
        history.push({
          pathname:`/dashboard/product/bukti-payment/${res?.data?.data?.id ?? 12}`,
          state:{
            type:"isType"
          }
        })
      }).catch((err) => {
        localStorage.removeItem("payment");
        notificationCtx.showNotification({
          title: "Error!",
          message:err?.response?.data?.message ?? "Something went wrong!",
          status: "error",
        });
      })
     
      
      // setRedirect(true);
 
  };
  return orderData ? (
    <div className="confirm-payment" id="confirm-payment">
      {redirect ? <Redirect to="/dashboard" /> : ""}
      <Header title="Confirm Payment" back={true} />
      <div>
        <h5>Order Detail</h5>
        <table>
          <thead>
            <tr>
              <th>No</th>
              <th>Product Name</th>
              <th>Qty</th>
              <th className="text-end">Price</th>
            </tr>
          </thead>
          <tbody>
            {orderData.order_details &&
              orderData.order_details.map((item, i) => {
                return (
                  <tr key={i}>
                    <td>{i + 1}</td>
                    <td>{item.product_unit.name}</td>
                    <td>{item.quantity}</td>
                    <td className="text-end">
                      {formatCurrency(item.unit_price)}
                    </td>
                  </tr>
                );
              })}
            <tr style={{ borderTop: "2px solid #000" }}>
              <td></td>
              <td></td>
              <td>Price</td>
              <td className="text-end">
                {formatCurrency(orderData.original_price)}
              </td>
            </tr>
            <tr>
              <td></td>
              <td></td>
              <td>Discount</td>
              <td className="text-end">
                - {formatCurrency(orderData.total_discount)}
              </td>
            </tr>
            <tr>
              <td></td>
              <td></td>
              <td>Packing</td>
              <td className="text-end">
                {formatCurrency(orderData.packing_fee)}
              </td>
            </tr>
            <tr>
              <td></td>
              <td></td>
              <td>Shipping</td>
              <td className="text-end">
                {formatCurrency(orderData.shipping_fee)}
              </td>
            </tr>
            <tr>
              <td></td>
              <td></td>
              <td>Additional Discount</td>
              <td className="text-end">
                - {formatCurrency(orderData.additional_discount)}
              </td>
            </tr>
            <tr
              style={{
                borderTop: "2px solid #000",
              }}
            >
              <td></td>
              <td></td>
              <td>Sub Total</td>
              <td className="text-end">
                -{" "}
                {orderData.total_price
                  ? formatCurrency(orderData.total_price)
                  : formatCurrency(orderData.original_price)}
              </td>
            </tr>
          </tbody>
        </table>

        <h5>Payment Info</h5>
        <table>
          <thead>
            <tr>
              <th>Payment Info</th>
              <th></th>
              <th></th>
              <th></th>
            </tr>
          </thead>
          <tbody>
            <tr>
              <td>Payment Status</td>
              <td></td>
              <td></td>
              <td className="text-end">{orderData.payment_status}</td>
            </tr>
            <tr>
              <td>Total Paid</td>
              <td></td>
              <td></td>
              <td className="text-end">
                {formatCurrency(orderData.amount_paid)}
              </td>
            </tr>
            <tr>
              <td>Total Unpaid</td>
              <td></td>
              <td></td>
              <td className="text-end">
                {formatCurrency(orderData.total_price - orderData.amount_paid)}
              </td>
            </tr>
            {}
            <tr>
              <td></td>
              <td></td>
              <td></td>
              <td
                className="text-end"
                onClick={() => setPaymentDetailActive(!paymentDetailActive)}
              >
                See Payments Detail
              </td>
            </tr>
            {paymentDetailActive && (
              <tr>
                <td>ID</td>
                <td></td>
                <td></td>
                <td className="text-end">
                  {paymentData ? paymentData.id : "-"}
                </td>
              </tr>
            )}
            {paymentDetailActive && (
              <tr>
                <td>Amount:</td>
                <td></td>
                <td></td>
                <td className="text-end">
                  {paymentData ? paymentData.amount : "-"}
                </td>
              </tr>
            )}
            {paymentDetailActive && (
              <tr>
                <td>Payment Type:</td>
                <td></td>
                <td></td>
                <td className="text-end">
                  {paymentData ? paymentData.payment_type.name : "-"}
                </td>
              </tr>
            )}
            {paymentDetailActive && (
              <tr>
                <td>Reference:</td>
                <td></td>
                <td></td>
                <td className="text-end">
                  {paymentData ? paymentData.status : "-"}
                </td>
              </tr>
            )}
          </tbody>
        </table>
      </div>

      <div className="notes mt-3">
        <h6>
          Amount<span>*</span>
          (Rp)
        </h6>
        <div className="mt-2 d-flex">
        <CurrencyInput
          className="form-control"
          id="input-example"
          name="input-name"
          prefix="RP "
          defaultValue={amount}
          decimalsLimit={3}
          onValueChange={(value, name, values) => setAmount(value)}
        />
          {/* <input
            className="form-control"
            type="number"
            placeholder="0"
            value={formatNumber(amount)}
            onChange={(e) => {
              console.log(e.target.value, "check value y a")
              if(!isNaN(e.target.value) || e.target.value === ""){
                setAmount(e.target.value)
              }
              return
            }}
            aria-label="default input example"
          /> */}
        </div>
      </div>
      <div className="notes mt-3">
        <h6>Shipping address</h6>
        <div className="mt-2">
          <textarea
          readOnly
            value={shippingAdds ?? ""}
            className="form-control"
            type="text"
            placeholder="Input your reference here"
            onChange={(e) => setReference(e.target.value)}
            aria-label="default input example"
          />
        </div>
      </div>
      <div className="notes mt-3">
        <h6>Reference (optional)</h6>
        <div className="mt-2">
          <textarea
            className="form-control"
            type="text"
            placeholder="Input your reference here"
            value={reference}
            onChange={(e) => setReference(e.target.value)}
            aria-label="default input example"
          />
        </div>
      </div>

      <div className="mt-3" onClick={() => handleSubmit()}>
        <Button title="Pay" btnStyle="primary-btn" btnWidth="100%" icon="" />
      </div>
    </div>
  ) : (
    <Loaded />
  );
};

export default ConfirmPayment;
