import { useEffect, useState, useContext } from "react";
import { useHistory } from "react-router-dom/cjs/react-router-dom.min"
import { formatCurrency } from "../../../../api/format";
import NotificationContext from "../../../../store/notification-context";
const NotaMasuk = () => {
    const history = useHistory();
    const [data, setData] = useState(null)
    const notificationCtx = useContext(NotificationContext);
    useEffect(() => {
        const isData = localStorage.getItem("payment")
        if (isData !== null || isData !== undefined) {
            setData(JSON.parse(isData));
            return notificationCtx.showNotification({
                title: "Success!",
                message: "Successfully Payment!",
                status: "success",
            });
        }
        notificationCtx.showNotification({
            title: "Error!",
            message:"Something went wrong!",
            status: "error",
          });
    }, [])
    return (
        <>
            <div className="container">
                <div style={{ width: "60%", margin: "auto", border: "1px solid black", background: "white" }}>
                    <div className="header" style={{ textAlign: "center", borderBottom: "1px solid black", padding: "20px 0 30px 0" }}>
                        <h4>KWITANSI</h4>
                    </div>
                    <div style={{ width: "95%", margin: "auto" }}>
                        <dl class="row">
                            <dt class="col-sm-3">Ditambahkan oleh:</dt>
                            <dd class="col-sm-9">{data?.added_by?.name ?? "-"}</dd>

                            <dt class="col-sm-3">Uang sebesar:</dt>
                            <dd class="col-sm-9">
                                {formatCurrency(data?.amount ?? "0", true)}
                            </dd>

                            {/* <dt class="col-sm-3">Untuk pembayaran:</dt>
                            <dd class="col-sm-9">CATTELAN TABLE GIANO|ø160x75h|base|metal|GFM18 bronze embossed|- top|wood|NC walnut canaletto.</dd> */}

                            <dt class="col-sm-3 text-truncate">Tipe pembayaran:</dt>
                            <dd class="col-sm-9">{data?.payment_type?.name ?? "-"}</dd>

                            <dt class="col-sm-3">Status:</dt>
                            <dd class="col-sm-9">
                                {data?.status ?? "-"}
                            </dd>
                        </dl>
                    </div>
                    <div style={{ width: "95%", margin: "50px auto 0 auto", display: "flex", flexDirection: "row", justifyContent: "space-between" }}>
                        <div style={{ fontSize: "12px" }}>
                            <dl class="row">
                                <dt class="col-sm-3">Harga:</dt>
                                <dd class="col-sm-9">RP. 11.000.000</dd>

                                <dt class="col-sm-3">Diskon:</dt>
                                <dd class="col-sm-9">
                                    RP. -1.000.000
                                </dd>
                                <dt class="col-sm-3">Total:</dt>
                                <dd class="col-sm-9">
                                    RP. 10.000.000
                                </dd>
                            </dl>
                        </div>
                        <div style={{ fontSize: "12px", textAlign: "center" }}>
                            <h4 style={{ fontSize: "15px" }}>Diterima oleh:</h4>
                            <h5 style={{ fontSize: "12px" }}>Sales Mike</h5>
                        </div>
                    </div>
                </div>
            </div>
        </>
    )
}

export default NotaMasuk