import React, {useCallback, useMemo} from 'react';

import AsyncSelect from 'react-select/async';
import kecamatanList from "../../api/data_kecamatan.json";


const SelectorKecamatan = ({
    values,
    onChange,
    isMulti = false,
    filterCity=null
  }) => {
    const loadOptions = (search, callback) => {
         setTimeout(() => {
            const filterdData = kecamatanList.filter((i) =>
                i.kecamatan.toLowerCase().includes(search.toLowerCase()) && i.kabkot_id == filterCity
              ).map((i) => ({value: i.kecamatan, label:i.kecamatan}))
              return callback(filterdData.slice(0, 10))
        }, 500)
      }
 
    const options = kecamatanList?.filter((kec) => kec.kabkot_id === filterCity)?.map((data) => ({
      value: data.kecamatan,
      label: data.kecamatan,
    })).slice(0,10);
 
    return (
      <>
        <AsyncSelect
        isDisabled={!filterCity ? true : false}
          isMulti={isMulti}
          onChange={onChange}
          defaultOptions={options}
          cacheOptions
          loadOptions={loadOptions}
          placeholder="Search Kecamatan..."
          defaultValue={
            (values === "" || values?.length === 0) ? ""
            : {
                  value: kecamatanList?.find(
                    (data) =>
                      data.kecamatan.toLowerCase() == values.toLowerCase()
                  )?.kecamatan ?? "",
                  label: kecamatanList?.find(
                    (data) =>
                      data.kecamatan.toLowerCase() == values.toLowerCase()
                  )?.kecamatan ?? "",
                }
             
          }
        />
      </>
    );
  };
  
  export default SelectorKecamatan;
  