import React, { useEffect } from "react";
// import { mainUrl } from "../../../api/api";
// import { connect, useDispatch, useMemo } from "react-redux";
// import Axios from "axios";
// import moment from "moment";
import { useHistory } from "react-router-dom";
// import LoadedComponent from "../../../../components/Loaded/LoadedComponent";
import LoadingTable from "../../../../components/Loaded/LoadingTable";
// import * as XLSX from "xlsx";
import { formatCurrency } from "../../../../api/format";

import { useReportDeals, useActiveLeads, useEstimations, useNewLeads, useQuotation, useTotalLeads, useReportLeadStatus } from "../api/useReport";




const TableSeeDetail = ({searchState, isUser, index, setDataExport}) => {
    const user = isUser;
  
    const history = useHistory();
    
    const {data:reportDeals, isLoading: loadingDeals, error:errorDeals} = useReportDeals({searchState, user});
    const {data:reportActiveLeads, isLoading:loadingActiveLeads, error:errorActiveLeads} = useActiveLeads({searchState, user});
    const {data:reportEstimations, isLoading:loadingEstimations, error:errorEstimations} = useEstimations({searchState, user});
    const {data:reportNewLeads, isLoading:loadingNewLeads, error:errorNewLeads} = useNewLeads({searchState, user});
    const {data:reportQuotations, isLoading:loadingQuotations, error:errorQuotations} = useQuotation({searchState, user});
    const {data:reportTotalLeads, isLoading:loadingTotalLeads, error:errorTotalLeads} = useTotalLeads({searchState, user});
    const {data:reportLeadStatus, isLoading:loadingLeadStatus, error:errorLeadStatus} = useReportLeadStatus({searchState, user});
  
    useEffect(() => {
      if(!errorDeals && !errorActiveLeads && !errorEstimations && !errorNewLeads && !errorQuotations && !errorTotalLeads && !errorLeadStatus && !loadingQuotations && !loadingTotalLeads && !loadingNewLeads && !loadingLeadStatus && !loadingDeals && !loadingActiveLeads && !loadingEstimations && !loadingNewLeads ){
      
        const exportData = {
          name: user?.name,
          deals: formatCurrency(reportDeals?.deals?.value, true).replace(
            /([A-Za-z])\w+/g,
            ""
          ),
          newLeads: reportNewLeads?.new_leads?.value ?? 0,
          interiorDesign: formatCurrency(reportDeals?.interior_design?.value, true).replace(
            /([A-Za-z])\w+/g,
            ""
          ),
          retails: formatCurrency(reportDeals?.retail?.value, true).replace(
            /([A-Za-z])\w+/g,
            ""
          ),
          activeLeads: reportActiveLeads?.active_leads?.value,
          quotation: formatCurrency(reportQuotations?.quotation?.value, true).replace(
            /([A-Za-z])\w+/g,
            ""
          ),
          pipelines:formatCurrency(reportEstimations?.estimation?.value, true).replace(
            /([A-Za-z])\w+/g,
            ""
          ),
          exhibition: formatCurrency(reportDeals?.exhibition?.value, true).replace(
            /([A-Za-z])\w+/g,
            ""
          ),
          followUp: reportTotalLeads?.total_leads?.value,
          hot: reportLeadStatus?.follow_up?.hot_activities,
          warm: reportLeadStatus?.follow_up?.warm_activities,
          drop: reportLeadStatus?.follow_up?.drop_leads,
          cold: reportLeadStatus?.follow_up?.cold_activities

        }
        setDataExport((prev) => {
          if(prev === null){
            return [exportData]
          }
     
          return [...prev, exportData]
          
        })
      }
      // setDataExport((prev) => [...prev, {
      //   no: 1
      // }])
    }, [setDataExport, errorDeals, errorActiveLeads, errorEstimations, errorNewLeads, errorQuotations, errorTotalLeads, errorLeadStatus, loadingQuotations, loadingTotalLeads, loadingLeadStatus, loadingDeals, loadingActiveLeads, loadingEstimations, loadingNewLeads, reportDeals, reportActiveLeads, reportEstimations, reportNewLeads, reportQuotations, reportTotalLeads, reportLeadStatus, user])


      if(errorDeals || errorActiveLeads || errorEstimations || errorNewLeads || errorQuotations || errorTotalLeads || errorLeadStatus){
          return <h4>Terjadi kesalahan error</h4>
        }
        // return <LoadingTable />
    return (
        < >
  
 
                  <tr>
                    <td>{index + 1}.</td>
                    <td
                      className="sticky"
                      style={{ position: "sticky", left: "0", background: index % 2 === 0 ? "#f8f9fa" : "#eaeaea"}}
                      
                    >
                      {user?.name}
                    </td>
               
                    <td style={{ cursor: "pointer" }} data-status-type="deals"
                      onClick={() => history.push({
                        pathname: "/dashboard/see-details/invoice",
                        state:{
                          data:user,
                          formatDate:searchState,
                          invoiceType:"deals",
                          typeUser: searchState.userType
                        }

                      })}
                    >
                      {loadingDeals ? <LoadingTable /> : formatCurrency(reportDeals?.deals?.value, true).replace(
                        /([A-Za-z])\w+/g,
                        ""
                      )}
                    </td>
                    <td
                      style={{ cursor: "pointer" }}
                      data-status-type="new-leads"
                      onClick={() => history.push({
                        pathname: "/dashboard/see-details/leads",
                        state:{
                          data:user,
                          formatDate:searchState,
                          typeUser: searchState.userType,
                          statusActive:0
                        }

                      })}
                    >
                      {loadingNewLeads ? <LoadingTable /> : reportNewLeads?.new_leads?.value}
                    </td>
                    <td
                      style={{ cursor: "pointer" }}
                      data-status-type="interior-design"
                      onClick={() => history.push({
                        pathname: "/dashboard/see-details/interior-design",
                        state:{
                          data:user,
                          formatDate:searchState,
                          typeUser: searchState.userType
                        }

                      })}
                    >
                      {loadingDeals ? <LoadingTable /> : formatCurrency(reportDeals?.interior_design?.value, true).replace(
                        /([A-Za-z])\w+/g,
                        ""
                      )}
                    </td>
                    <td style={{ cursor: "pointer" }} data-status-type="retail"
                      onClick={() => history.push({
                        pathname: "/dashboard/see-details/invoice",
                        state:{
                          data:user,
                          formatDate:searchState,
                          invoiceType:"retail",
                          typeUser: searchState.userType
                        }

                      })}
                    >
                      {loadingDeals ? <LoadingTable /> : formatCurrency(reportDeals?.retail?.value, true).replace(
                        /([A-Za-z])\w+/g,
                        ""
                      )}
                    </td>
                    <td
                      style={{ cursor: "pointer" }}
                      data-status-type="active-leads"
                      onClick={() => history.push({
                        pathname: "/dashboard/see-details/leads",
                        state:{
                          data:user,
                          formatDate:searchState,
                          typeUser: searchState.userType,
                          statusActive:1
                        }

                      })}
                    >
                      {loadingActiveLeads ? <LoadingTable /> : reportActiveLeads?.active_leads?.value}
                    </td>
                    <td
                      style={{ cursor: "pointer" }}
                      data-status-type="quotation"
                      onClick={() => history.push({
                        pathname: "/dashboard/see-details/invoice",
                        state:{
                          data:user,
                          formatDate:searchState,
                          invoiceType:"quotation",
                          typeUser: searchState.userType
                        }

                      })}
                    >
                      {loadingQuotations ?<LoadingTable /> : formatCurrency(reportQuotations?.quotation?.value, true).replace(
                        /([A-Za-z])\w+/g,
                        ""
                      )}
                    </td>
                    <td
                      style={{ cursor: "pointer" }}
                      data-status-type="pipelines"
                      onClick={() => history.push({
                        pathname: "/dashboard/see-details/pipelines",
                        state:{
                          data:user,
                          formatDate:searchState,
                          typeUser: searchState.userType
                        }

                      })}
                    >
                      {loadingEstimations ?<LoadingTable /> : formatCurrency(reportEstimations?.estimation?.value, true).replace(
                        /([A-Za-z])\w+/g,
                        ""
                      )}
                    </td>
                    
                    <td style={{ cursor: "pointer" }} data-status-type="retail">
                      {loadingDeals ?<LoadingTable /> : formatCurrency(reportDeals?.exhibition?.value, true).replace(
                        /([A-Za-z])\w+/g,
                        ""
                      )}
                    </td>
                    <td style={{ cursor: "pointer" }} data-status-type="follow-up"onClick={() => history.push(`/dashboard/follow-up-activities/status/${user?.id}${searchState.start !== "" ? "/" + searchState.start : ""}${searchState.end !== "" ? "/" + searchState.end : ""}`)}>{loadingTotalLeads ?<LoadingTable /> : reportTotalLeads?.total_leads?.value}</td>
                    <td style={{ cursor: "pointer" }} data-status-type="HOT"
                    onClick={() => history.push({
                      pathname: "/dashboard/see-details/follow-up/HOT",
                      state:{
                        data:user,
                        formatDate:searchState,
                        typeUser: searchState.userType,
                        statusActv:"HOT"
                      }

                    })}>
                      {loadingLeadStatus ?<LoadingTable /> : reportLeadStatus?.follow_up?.hot_activities}
                    </td>
                    <td style={{ cursor: "pointer" }} data-status-type="WARM"
                      onClick={() => history.push({
                        pathname: "/dashboard/see-details/follow-up/WARM",
                        state:{
                          data:user,
                          formatDate:searchState,
                          typeUser: searchState.userType,
                          statusActv:"WARM"
                        }
  
                      })}
                    >
                      {loadingLeadStatus ?<LoadingTable /> : reportLeadStatus?.follow_up?.warm_activities}
                    </td>
                    <td style={{ cursor: "pointer" }} data-status-type="COLD"
                      onClick={() => history.push({
                        pathname: "/dashboard/see-details/follow-up/COLD",
                        state:{
                          data:user,
                          formatDate:searchState,
                          typeUser: searchState.userType,
                          statusActv:"COLD"
                        }
  
                      })}
                    >
                      {loadingLeadStatus ?<LoadingTable /> : reportLeadStatus?.follow_up?.cold_activities}
                    </td>
                    <td style={{ cursor: "pointer" }} data-status-type="COLD"
                      onClick={() => history.push({
                        pathname: "/dashboard/see-details/follow-up/COLD",
                        state:{
                          data:user,
                          formatDate:searchState,
                          typeUser: searchState.userType,
                          statusActv:"COLD"
                        }
  
                      })}
                    >
                      {loadingLeadStatus ?<LoadingTable /> : reportLeadStatus?.follow_up?.drop_leads}
                    </td>
                  </tr>
             
          </>
    )
}

export default TableSeeDetail