import React from "react";
import { formatCurrency } from "../../../../api/format";
import IsBar from "../IsBar";
const CardReport = ({
  title,
  compare = null,
  target = null,
  value = null,
  isDataUser,
  type,
  showBar,
  isValue,
  showArrow,
}) => {
  // const [matches, setMatches] = useState(
  //   window.matchMedia("(max-width: 1440px)").matches
  // );

  // useEffect(() => {
  //   window
  //     .matchMedia("(max-width: 1440px)")
  //     .addEventListener("change", (e) => setMatches(e.matches));
  // },[]);

  const colorValue = {
    deals: "#17949D",
    new: "#179D63",
    interior: "rgb(247, 173, 151)",
    retail: "rgb(245, 144, 123)",
    active: "rgb(79, 214, 155)",
    quotation: "rgb(23, 81, 157)",
    pipelines: "rgb(63, 130, 217)",
    exhibition: "rgb(247, 173, 151)",
  };
  return (
    <div
      className="report-card col-md-3 "
      style={{
        paddingLeft: "0",
        background: "white",
        borderRadius: "20px",
        boxShadow: "1px 1px 15px rgb(0,0,0,0.2)",
        width:"100%"
      }}
    >
      <div
        className="report-card-wrapper p-3"
        style={{
          height: "8rem",
          cursor:
            isDataUser?.as?.toUpperCase() === "SALES" ? "pointer" : "auto",
        }}
      >
        <h5
          className="mb-2 dashboard-report-title"
          style={{
            color:
              type === "deals" || type === "new-leads"
                ? "rgb(0,0,0,0.2)"
                : "black",
          }}
        >
          {title}
        </h5>
        <div className="">
          <h4
            className="m-0 dashboard-report-value"
            style={{
              color: colorValue[type?.split("-")[0]],
              position: "relative",
              
            }}
          >
            {type === "deals" ||
            type === "interior-design" ||
            type === "retail" ||
            type === "quotation" ||
            type === "pipelines" ||
            type === "exhibition"
              ? formatCurrency(value, true)
              : value}

            {showArrow ? (
              value < compare ? (
                <span
                  style={{
                    width: "0",
                    height: "0",
                    borderLeft: "5px solid transparent",
                    borderRight: "5px solid transparent",
                    marginLeft: "10px",
                    display: "inline-block",
                    position: "absolute",
                    top: "50%",
                    transform: "translateY(-50%)",
                    right: "0",
                    borderTop: "10px solid red",
                  }}
                ></span>
              ) : (
                <span
                  style={{
                    width: "0",
                    height: "0",
                    borderLeft: "5px solid transparent",
                    borderRight: "5px solid transparent",
                    marginLeft: "10px",
                    display: "inline-block",
                    position: "absolute",
                    top: "50%",
                    transform: "translateY(-50%)",
                    right: "0",
                    borderBottom: "10px solid green",
                  }}
                ></span>
              )
            ) : null}
          </h4>
        </div>
        {showBar && (
          <IsBar
            target={target}
            value={value}
            colorPercent={
              title?.toUpperCase() === "DEALS" ? "#17949D" : "#179D63"
            }
          />
        )}
        {type === "deals" || type === "new-leads" ? (
          <p className="dashboard-report-target">Target: {isValue?.toLocaleString("id-ID")}</p>
        ) : null}
        {type === "interior-design" ||
        type === "retail" ||
        type === "exhibition" ? (
          <p className="dashboard-report-target">Total Transaction: {isValue}</p>
        ) : null}
      </div>
    </div>
  );
};

export default CardReport;
