import axios from "axios";
import moment from "moment";
import React, { useEffect, useState } from "react";
import { mainUrl } from "../../api/api";
import Button from "../Button/Button";
import LoadedComponent from "../Loaded/LoadedComponent";
import Popup from "../Popup/Popup";
import UpdateCustomerPopup from "../Popup/Popup Component/UpdateCustomerPopup";
import UpdateLead from "../Popup/Popup Components/UpdateLeads/UpdateLead";
import "./CustomerCard.css";

const CustomerCard = (props) => {
  const { leads_id } = props;
  const [refreshCustomer, setRefreshCustomer] = useState(false);
  const [customer, setCustomer] = useState(null);
  const [customerAddress, setCustomerAddress] = useState(null);
  const [updateCustomer, setUpdateCustomer] = useState(false);
  const [upgradeLead, setUpgradeLead] = useState(false);
  const [isType, setIsType] = useState("PROSPECT");
  
  useEffect(() => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
    const getCustomer = async () => {
      try {
        const res = await axios.get(`${mainUrl}/leads/${leads_id}`, config);
        setCustomer(res.data.data);
      } catch (error) {
        console.error(error);
      }
    };

    getCustomer();
  }, [leads_id, refreshCustomer]);

  useEffect(() => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };

    const getCustomerAddress = async () => {
      try {
        const res = await axios.get(
          `${mainUrl}/addresses/${
            customer.customer.default_address_id
              ? customer.customer.default_address_id
              : ""
          }`,
          config
        );
        setCustomerAddress(res.data.data);
      } catch (error) {
        console.error(error);
      }
    };
    if (customer) {
      getCustomerAddress();
    }
  }, [customer]);
  return customer && customerAddress ? (
    <div id="customer-card" className="customer-card">
      <Popup popup={updateCustomer} setPopup={setUpdateCustomer}>
        <UpdateCustomerPopup
          customer={customer}
          address={customerAddress}
          refreshCustomer={refreshCustomer}
          setRefreshCustomer={setRefreshCustomer}
        />
      </Popup>
      <Popup popup={upgradeLead} setPopup={setUpgradeLead}>
        <UpdateLead customer={customer} isType={isType}/>
      </Popup>
      <div className="d-flex justify-content-between align-items-center">
        <div className="d-flex align-items-center">
          <div className="customer-img d-flex justify-content-center align-items-center">
            <div>
              <h2>{customer.customer.first_name[0].toUpperCase()}{customer.customer.last_name ? customer.customer.last_name[0].toUpperCase() : "" }</h2>
            </div>
          </div>
          <div className="">
            <h2>{`${customer.customer.first_name.toLowerCase().split(' ').map(word => word.charAt(0).toUpperCase(0) + word.substring((1))).join(' ')} ${
              customer.customer.last_name ? customer.customer.last_name.toLowerCase().split(' ').map(word => word.charAt(0).toUpperCase(0) + word.substring((1))).join(' ') : ""
            }`}</h2>
          </div>
        </div>
        <img
          src="/Asset/Edit.png"
          alt="edit"
          style={{ width: "24px", height: "24px" }}
          onClick={() => setUpdateCustomer(!updateCustomer)}
        />
      </div>
      <div className="customer-desc row mt-4">
        <div className="col-5">
          <h4>Basic Information</h4>
          <div className="row">
            <div className="col-5">
              <p>Name</p>
              <p>Phone Number</p>
              <p>Email</p>
              <p>Priority</p>
              <p>Date of Birth</p>
            </div>
            <div className="col-7">
              <p>{`${customer.customer.first_name.toLowerCase().split(' ').map(word => word.charAt(0).toUpperCase(0) + word.substring((1))).join(' ')} ${
                customer.customer.last_name ? customer.customer.last_name.toLowerCase().split(' ').map(word => word.charAt(0).toUpperCase(0) + word.substring((1))).join(' ') : ""
              }`}</p>
              <p>{`${customer.customer.phone}`}</p>
              <p>{`${customer.customer.email}`}</p>
              <p>{`${customer.status}`}</p>
              <p>
                {customer.customer.date_of_birth
                  ? moment(customer.customer.date_of_birth).format(
                      "DD MMM YYYY"
                    )
                  : "-"}
              </p>
            </div>
          </div>
        </div>
        <div className="col-5">
          <h4>Address Information</h4>
          <div className="row">
            <div className="col-5">
              <p>Address Line 1</p>
              <p>Sub Distric</p>
              <p>City/Distric</p>
              <p>Province</p>
              <p>ZIP Code</p>
            </div>
            <div className="col-7">
              <p>{`${
                customerAddress.address_line_1
                  ? customerAddress.address_line_1
                  : "-"
              }`}</p>
              <p>-</p>
              <p>{`${customerAddress.city ? customerAddress.city : "-"}`}</p>
              <p>{`${
                customerAddress.province ? customerAddress.province : "-"
              }`}</p>
              <p>{`${
                customerAddress.postcode ? customerAddress.postcode : "-"
              }`}</p>
            </div>
          </div>
        </div>
        <div className="col-2"></div>
      </div>
      {customer.type === "LEADS" && (
        <div onClick={() => {
          setUpgradeLead(!upgradeLead);
          setIsType("PROSPECT")
          }}>
          <Button
            title="Upgrade Prospect"
            btnStyle="primary-btn"
            btnWidth={"100%"}
          />
        </div>
      )}
      {customer.type === "LEADS" || customer.type === "PROSPECT" ? (
        <div onClick={() => {
          setIsType("DROP")
          setUpgradeLead(!upgradeLead)
          
          }} className="mt-2">
          <Button title="Drop Lead" btnStyle="btn-danger" btnWidth={"100%"} />
        </div>
      ) : (
        ""
      )}
    </div>
  ) : (
    <LoadedComponent />
  );
};

export default CustomerCard;
