import React from 'react';
import Button from '../../../../components/Button/Button';
import {useState} from "react"
const InvoiceDetailHead = ({ searchState, setOnTouch, setSearchState, setLoadmoreOnTouch, dataUsers, setIsFilter}) => {
    const [selectUserIsActive, setSelectUserIsActive] = useState(false)
    const handleEventChange = (e) => {
        setSearchState((prev) => {
            return {
                ...prev,
                searchType: e.target.value
            }
        })
    }
    const handleChangeSearch = (e) => {
       
        setSearchState((prev) => {
            return {
                ...prev,
                searchValue: e.target.value
            }
        })
    }
    const handleChangeDate = (e) => {
        setSearchState((prev) => {
            return {
                ...prev,
                [e.target.name]: e.target.value
            }
        })
    }
    return(
        <>
            <div className='container-filters' >
                <div className='filter d-flex' style={{gap:"20px", marginBottom:"20px"}} >
                    <input type="text" id="search-table" className="form-control" onChange={handleChangeSearch}  placeholder={`Type ${searchState.searchType?.split("_")?.join(" ")} here...`} style={{width:"20rem"}}value={searchState.searchValue} />
                    <select
                        style={{width:"15rem"}}
                        className="form-select"
                        name="search-type"
                        onChange={handleEventChange}
                    >
                        <option value="customer">Customer</option>
                        <option value="sales">Sales</option>
                        <option value="invoice_number">Invoice Number</option>
                        <option value="channel">Channel</option>
                    </select>
                    <select
                        value={searchState.userType}
                        style={{width:"15rem",marginLeft:"20px", marginRight:"20px"}}
                        className="form-select"
                        name="search-value"
                        onChange={(e) => {
                            setSearchState((prev) => ({...prev, userType: e.target.value}));
                            setLoadmoreOnTouch((prev) => {
                                return {
                                    ...prev,
                                    onTouch: true,
                                    page: 1
                                }
                            })
                        }}
                    >
                        <option value="bum">Bum</option>
                        <option value="hs">Head Sales</option>
                        <option value="store_leader">Store Leader</option>
                        <option value="sales">Sales</option>
                    </select>
                    <div style={{position:"relative"}}>
                    <div style={{border:"1px solid #ced4da", background:"white", borderRadius:"5px", padding:"8px 10px", width:"20rem", cursor:"pointer", fontSize:"13px", display:"flex", alignItems:"center", justifyContent:"space-between"}}>
                        <div onClick={() => {
                            setSelectUserIsActive((prev) => !prev)
                            
                        }} style={{display:"flex", alignItems:"center", justifyContent:"space-between", width:"100%"}}>
                            <span>{searchState.name_user !== "" ? searchState.name_user : "Select User"}</span>
                            <img
                                src="/Asset/Sidebar/arrow down.png"
                                alt="arrow"
                                className="arrow-bar"
                                style={{ width: "14px", height: "14px"}}
                            />
                        </div>
                        {selectUserIsActive && (<div style={{overflowY:"scroll",position:"absolute", background:"white", border: "1px solid #ced4da", borderRadius:"5px", bottom:"-30.4rem",height:"30rem", padding:"5px 10px", left:"0", width:"100%", whiteSpace:"nowrap"}}>
                            <ul style={{listStyle:"none", padding:"0", margin:"0", whiteSpace:"normal"}} class="list-group list-group-flush" >
                                {
                                    dataUsers.currentUser && dataUsers?.currentUser?.map((user) => {
                                        return <li key={user.id} style={{borderBottom:"1px solid #ced4da", marginBottom:"20px"}} onClick={() => {
                                            setSearchState((prev) => ({...prev, id_user: user.id, name_user: user.name}));
                                            setSelectUserIsActive(false)
                                        }}>{user.name}</li>
                                    })
                                }
                            </ul>
                            <span onClick={(e) => e.target.textContent === "Load More"  && setLoadmoreOnTouch((prev) => ({...prev, page: prev.page + 1, onTouch: true}))} style={{color:"#17949d", textAlign:"center", fontWeight:"bold", width:"max-content", display:"block", margin:"auto", padding:"20px"}}>{dataUsers?.hasNextPage !== null ? "Load More" : "No More Users"}</span>
                        </div>)}
                    </div>
                    </div>
                    
                   
                </div>
                <div style={{display:"flex", gap:"20px"}}>
                <div style={{display:"flex", alignItems: "center"}}>
                        <input
                            type="date"
                            id="start"
                            name="startDate"
                            className="form-control"
                            placeholder="Start Month"
                            onChange={handleChangeDate}
                            value={searchState.startDate}
                        />
                        <div className="input-group-addon"style={{margin: "0 10px"}}>to</div>
                        <input
                            type="date"
                            id="end"
                            name="endDate"
                            className="form-control"
                            placeholder="End Month"
                            onChange={handleChangeDate}
                            style={{margin:"0"}}
                            value={searchState.endDate}
                        />
                    </div>
                <Button onClick={(e) => {
                        setIsFilter((prev) => ({...prev, nameofUserType:searchState?.name_user, active:true}))
                        setOnTouch(true)
                    }}icon="" title="Filter" style={{width:"11rem!important", marginTop:"30px"}} btnStyle={"primary-btn"} />
                    <Button onClick={(e) => {
                        setIsFilter({
                            nameofUserType:"",
                            active: false
                        })
                        setIsFilter(false)
                        setOnTouch(true)
                        setLoadmoreOnTouch((prev) => {
                            return {
                                ...prev,
                                onTouch:true,
                                page:1
                            }
                        })
                        setSearchState({
                            startDate: "",
                            endDate: "",
                            searchType:"customer",
                            searchValue: "",
                            userType: "bum",
                            id_user: null,
                            name_user:""
                        })
                    }}icon="" title="Reset Filter" style={{width:"11rem!important", marginTop:"30px"}} btnStyle={"primary-btn"} />
                    </div>
            </div>
        </>
    )
}

export default InvoiceDetailHead