
import { REPORT_LEADS_BRAND_ID, REPORT_LEADS_CURRENT_CHANNEL, REPORT_LEADS_START_END_DATE, REPORT_LEADS_COMPANY_ID, REPORT_LEADS_CHANNEL_ID, REPORT_LEADS_USER_TYPE } from "./types";

export const reduxChangeUserType = (userType) => (dispatch) => {
    dispatch({
        type: REPORT_LEADS_USER_TYPE,
        value: userType
    })
}
export const reduxChangeChannel = (channelId) => (dispatch) => {
    dispatch({
        type: REPORT_LEADS_CHANNEL_ID,
        value: channelId
    })
}

export const reduxChangeBrand = (brandId) => (dispatch) => {
    dispatch({
        type: REPORT_LEADS_BRAND_ID,
        value: brandId
    })
}

export const reduxChangeStartEndDate = (startEndDate) => (dispatch) => {
    dispatch({
        type: REPORT_LEADS_START_END_DATE,
        value:startEndDate
    })
}

export const reduxChangeCompany = (companyId) => (dispatch) => {
    dispatch({
        type: REPORT_LEADS_COMPANY_ID,
        value: companyId
    })
}

export const reduxChangeCurrentChannel = (currenctChannel) => (dispatch) => {
    dispatch({
        type: REPORT_LEADS_CURRENT_CHANNEL,
        value: currenctChannel
    })
}