import "./loadingTable.css";

import React from "react";

const LoadingTable = () => {
    return (
        <>
        <div class="tableWrapper">
            <table class="table">
                <tbody>
                    <tr>
                        <td class="loading">
                        <div class="bar"></div>
                        </td>
                        
                    </tr>
                </tbody>
            </table>
        </div>
        </>
    )
}

export default LoadingTable