import React from "react";
import axios from "axios";
import { mainUrl } from "../../api/api";
import Button from "../Button/Button";

const Quotation = (props) => {
  const { orderId } = props;
  const handleQuotation = async () => {
    const config = {
      headers: {
        Accept: "application/json, text-plain, */*",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };

    axios(
      `${mainUrl}/orders/export-quotation?type=quotation&order_id=${orderId}`,
      {
        method: "GET",
        responseType: "blob", //Force to receive data in a Blob Format
        headers: config.headers,
      }
    )
      .then((response) => {
        console.log(response, "check quotation")
         const blob = new Blob([response.data], { type: 'application/pdf' });
  const url = window.URL.createObjectURL(blob);

  // Membuka PDF di tab baru
  window.open(url);
        //Create a Blob from the PDF Stream
        // var binaryString = window.atob(response.data);
        // var binaryLen = binaryString.length;
        // var bytes = new Uint8Array(binaryLen);
        // for (var i = 0; i < binaryLen; i++) {
        //   var ascii = binaryString.charCodeAt(i);
        //   bytes[i] = ascii;
        // }
        // return bytes;
      })
      .catch((error) => {
        console.error(error);
      });
  };
  return (
    <div className="mt-2 mb-3">
      <div onClick={() => handleQuotation()}>
        <Button
          title={"Quotation"}
          btnStyle={"primary-btn"}
          btnWidth={"100%"}
        />
      </div>
    </div>
  );
};

export default Quotation;
