import { useQuery } from "react-query";
import axios from "axios";
import { mainUrl, config } from "../../api/api";
const useGetAddresses = ({cus_id, isEnabled = false}) => {
    return useQuery(["addresCustomer", cus_id], () => {
        return axios.get(`${mainUrl}/addresses?filter[customer_id]=${cus_id}`, config)
                .then((res) => res.data)
                .catch((error) => error)
    }, {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime:Infinity, enabled:isEnabled})
}


export default useGetAddresses;


