import moment from "moment";
import React, { useState } from "react";
import { useParams, useHistory } from "react-router-dom";
import { isValidate } from "../../../lib/Validate";
import LoadingTableAllData from "../../Loaded/LoadingTableAllData";
import Header from "./ReportLeadsHead";
// import Button from "../../Button/Button";
import useReportLeadsStatusHotList from "../apiReportLeads/useReportLeadStatusHotList";
import ReportLeadsHeader from "./ReportLeadsHeader";
import { connect } from "react-redux";
const ReportLeadsStatusHot = ({ReportLeadFilterRedux: {channelId, companyId, brandId, currentChannel, startEndDate, userType}}) => {
  const params = useParams();
  const history = useHistory();
  const historyState = history?.location?.state
  const { user_id, detail_type } = params;
  const [searchState, setSearchState] = useState({
        start: startEndDate.start,
        end: startEndDate.end,
        channelId: channelId === null ? "" : channelId,
        companyId: companyId === null ? "" : companyId,
        brandId: brandId === null ? "" : brandId,
        userType: userType, 
        currentUserType: "",
        userId: user_id,
        status: detail_type,
        count: 1
    });
 
    const { data:reportDataStatusHot, error, isLoading } = useReportLeadsStatusHotList({searchState});
  if(isLoading){
    return <div className="">
                <Header
                  icon=""
                  title={`Report Leads - ${detail_type?.toUpperCase()}`}
                  back={true}
                  user={false}
                />
              <ReportLeadsHeader 
                  searchState={searchState}
                  setSearchState={setSearchState}
                  type="company"
              />
              <LoadingTableAllData />        
          </div>
  }

  if(error){
    return <h4>Terjadi kesalahan pada server</h4>
  }

  return (
    <div>
      <Header
        icon=""
        title={`Report Leads - ${detail_type?.toUpperCase()}`}
        back={true}
        user={false}
      />

        <ReportLeadsHeader 
            searchState={searchState}
            setSearchState={setSearchState}
            user={historyState?.user ?? null}
            channel={false}
            company={false}
            type="type"
        />
      <div style={{ overflow: "scroll" }}>
          <table className="" style={{ margin: "10px 0" }}>
            <thead>
              <tr>
                <th>No.</th>
                <th>Date</th>
                <th>Leads</th>
                <th>Customer</th>
                <th>Sales</th>
                <th>Channel</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {reportDataStatusHot &&
                reportDataStatusHot?.map((activity, idx) => {
                  return (
                    <tr key={activity.id}>
                      
                      <td>{idx + 1}</td>
                      <td>
                        {!isValidate(activity?.lead_activities[0]?.follow_up_datetime)
                          ? moment(activity?.lead_activities[0]?.follow_up_datetime)?.format(
                              "MM/DD/YYYY"
                            )
                          : ""}
                      </td>
                      <td>{!isValidate(activity?.label) ? activity?.label : ""}</td>
                      <td>
                        {!isValidate(activity.customer)
                          ? `${activity.customer.first_name} ${
                              activity.customer.last_name || ""
                            }`
                          : ""}
                      </td>
                       <td>
                        {!isValidate(activity.user.name)
                          ? activity.user.name
                          : ""}
                      </td> 
                        <td>
                        {!isValidate(activity.channel.name)
                          ? activity.channel.name
                          : ""}
                      </td>
                      <td>
                        <div
                          onClick={() => history.push(`/dashboard/customers/customer_detail/${activity.id}/${activity.customer.id}`)}
                          className="activity-detail-btn"
                        >
                          <img
                            src="/Asset/Action Icon/eye.png"
                            style={{ marginRight: "5px" }}
                            alt="eye"
                          />
                          See Detail
                        </div>
                      </td>
                    </tr>
                  );
                })}
            </tbody>
          </table>
            {/* <div style={{display:"flex", gap:"20px", marginTop:"50px", alignItems:"center"}}>
                <div style={{display: reportDataStatusHot?.links?.prev === null ? "none" : "block"}}>
                    <Button
                        onClick={() => setSearchState((prev) => ({
                            ...prev,
                            count: prev.count === 1 ? 1 : prev.count - 1
                        }))}
                        icon=""
                        title={"Prev"}
                        style={{ width: "11rem!important"}}
                        btnStyle={"primary-btn"}
                    />
                </div>
                
                <div style={{display: reportDataStatusHot?.links?.next === null ? "none" : "block"}}>
                <Button
                        onClick={() => {setSearchState((prev) => ({
                            ...prev,
                            count: prev.count + 1
                        }))}}
                        icon=""
                        title={"Next"}
                        style={{ width: "11rem!important", display: reportDataStatusHot?.links?.next === null ? "none" : "block"}}
                        btnStyle={"primary-btn"}
                    />
                </div>
            </div> */}
        </div>
    </div>
  );
};
const mapStateToProps = (state) => ({
    auth: state.auth,
    target: state.target,
    prosesData: state.prosesData,
    ReportLeadFilterRedux: state.ReportLeadFilterRedux,
  });
export default connect(mapStateToProps)(ReportLeadsStatusHot);
