import { useQuery } from "react-query";
import { mainUrl, config } from "../../../api/api";
import axios from "axios";

const useReportLeadList = ({searchState}) => 
{
    return useQuery(["reportLeadListest", searchState], () => {
        return axios.get(
            `${mainUrl}/dashboard/new-report-leads-optimized?start_date=${
                searchState.start === "now" ? "" : searchState.start
            }&end_date=${
                searchState.end === "now" ? "" : searchState.end
            }&company_id=${searchState.companyId}&channel_id=${
                searchState.channelId
            }&product_brand_id=${searchState.brandId}&user_type=${searchState.userType}`,
            config
        ).then((res) => res.data.original)
        .catch((error) => error)
    }, {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity})
}

export default useReportLeadList