
import React, { useEffect, useState, useMemo } from "react";
import { connect, useDispatch } from "react-redux";
import { mainUrl, mainUrlVTwo } from "../../../api/api";
import axios from "axios";
import { loadChannels, loadUsersList } from "../../../redux/action/target";
import Skill from "./Skill";
import { useHistory } from "react-router-dom";
import { dataNewReports, dataSeeDetails, isFilterDate,filterIdCrud, isChannelId  } from "../../../redux/action/idUser";
import CardReport from "./componentsReport/cardsReport";
import ComporationPopUp from "../../../components/Popup/Popup Component/ComporationPopUp";
import Popup from "../../../components/Popup/Popup";
import LoadingDashboard from "../../../components/Loaded/LoadingDashboard";
import FiltersReport from "./componentsReport/filterReport"
import { useReportDeals, useActiveLeads, useEstimations, useNewLeads, useQuotation, useTotalLeads, useReportLeadStatus } from "./api/useReportDashboard";
import IsBar from "./IsBar";
const DashboardReport = ({ auth: { user, loading }, target: { channels, usersList }, prosesData: {dataFilterDate, idChannels, idCompany}, buttonRole, valueClick, setHideButton, config}, props) => {
    const history = useHistory();
    const userData = props.userData;
    const dispatch = useDispatch();
    const [comparationPopup, setComparationPopup] = useState(false);
    const [searchState, setSearchState] = useState({
        userType: "",
        companyId: "",
        searchValue:"",
        start: dataFilterDate.start === undefined ? "" : dataFilterDate.start,
        end: dataFilterDate.end === undefined ? "" : dataFilterDate.end,
        userFilter:null,
        channelId: idChannels === undefined || idChannels === null ? "" : idChannels,
        onTouch:false
    });
    const [temporaryState, setTemporaryState] = useState({
        userType: "",
        companyId: "",
        searchValue:"",
        start: dataFilterDate.start === undefined ? "" : dataFilterDate.start,
        end: dataFilterDate.end === undefined ? "" : dataFilterDate.end,
        userFilter:null,
        channelId: idChannels === undefined || idChannels === null ? "" : idChannels
    })
    const {data:reportDeals, isLoading: loadingDeals, error:errorDeals} = useReportDeals({temporaryState, user, config});
    const {data:reportActiveLeads, isLoading:loadingActiveLeads, error:errorActiveLeads} = useActiveLeads({temporaryState, user, config});
    const {data:reportEstimations, isLoading:loadingEstimations, error:errorEstimations} = useEstimations({temporaryState, user, config});
    const {data:reportNewLeads, isLoading:loadingNewLeads, error:errorNewLeads} = useNewLeads({temporaryState, user, config});
    const {data:reportQuotations, isLoading:loadingQuotations, error:errorQuotations} = useQuotation({temporaryState, user, config});
    const {data:reportTotalLeads, isLoading:loadingTotalLeads, error:errorTotalLeads} = useTotalLeads({temporaryState, user, config});
    const {data:reportLeadStatus, isLoading:loadingLeadStatus, error:errorLeadStatus} = useReportLeadStatus({temporaryState, user, config});
    
    
    const newReports = useMemo(() => {
        return {
            deals:reportDeals?.deals,
            active_leads:reportActiveLeads?.active_leads,
            estimation:reportEstimations?.estimation,
            new_leads:reportNewLeads?.new_leads,
            quotation:reportQuotations?.quotation,
            follow_up: {
                total_activities:{
                    value: reportTotalLeads?.total_leads?.value,
                    compare: reportTotalLeads?.total_leads?.compare,
                    target_activities: reportTotalLeads?.total_leads?.target_leads
                },
                cold_activities:reportLeadStatus?.follow_up?.cold_activities,
                hot_activities:reportLeadStatus?.follow_up?.hot_activities,
                warm_activities:reportLeadStatus?.follow_up?.warm_activities
            },
            retail:reportDeals?.retail,
            exhibition: reportDeals?.exhibition,
            interior_design: reportDeals?.interior_design,
            original_date: reportDeals?.original_date,
            compare_date: reportDeals?.compare_date
        }
    }, [reportDeals,reportActiveLeads, reportEstimations, reportNewLeads, reportQuotations, reportTotalLeads, reportLeadStatus]);

    const pickColor = (value) => {
        if (value === "HOT") {
          return "#E53935";
        } else if (value === "WARM") {
          return "#FFD13D";
        } else if (value === "COLD") {
          return "#0553B7";
        } else if (value === "CLOSE") {
          return "#313132";
        }
    };
    useEffect(() => {
        if(searchState.onTouch){
            setTemporaryState((prev) => {
                return {
                    ...prev,
                    userType: searchState.userType,
                    companyId: searchState.companyId,
                    searchValue:searchState.searchValue,
                    start: searchState.start,
                    end: searchState.end,
                    userFilter: searchState.userFilter,
                    channelId: searchState.channelId
                }
            })
            setSearchState((prev) => ({
                ...prev,
                onTouch:false
            }))
        }
    }, [searchState, dispatch]);


    // Untuk channels agar bisa tampil
    useEffect(() => {
        localStorage.removeItem("channel_dashboard");
        user && localStorage.setItem("company_id", user?.data?.company?.id);
        dispatch(loadChannels(temporaryState.companyId));
        dispatch(isFilterDate(temporaryState));
        dispatch(isChannelId(temporaryState.channelId))
        dispatch(filterIdCrud(temporaryState.companyId === "" ? 1 : temporaryState.companyId));
        if (userData) {
          dispatch(
            loadUsersList(
              temporaryState.channelId,
              userData.data.supervisor_id,
              userData.data.company.id
            )
          );
        } else {
          dispatch(loadUsersList());
        }
      }, [dispatch, user, temporaryState, userData])
    
      useEffect(() => {
        const config = {
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${localStorage.token}`,
            },
          };
        const getSeeDetails = async () => {
          try{
            const res = await axios.get(`${mainUrlVTwo}/new-reports/details?user_type=store_leader`, config);
            dispatch(dataSeeDetails(res))
          }catch(error){  
            console.log(error.response, "check error")
          }
        } 
  
        valueClick.toUpperCase() === buttonRole[1] && getSeeDetails()
      }, [buttonRole, valueClick, dispatch]);

      useEffect(() => {
        if(!loadingDeals && !loadingActiveLeads && !loadingEstimations && !loadingNewLeads && !loadingQuotations && !loadingTotalLeads && !loadingLeadStatus){
            setHideButton(false);
            dispatch(dataNewReports({data:newReports}))
        }
      }, [loadingDeals, loadingActiveLeads, loadingEstimations, loadingNewLeads, loadingQuotations, loadingTotalLeads, loadingLeadStatus, dispatch, newReports, setHideButton])
      
   if(errorDeals || errorActiveLeads || errorEstimations || errorNewLeads || errorQuotations || errorTotalLeads || errorLeadStatus){
    return <h4>Terjadi Kesalahan.</h4>
   } 
    return (
        <>
            
            <div className="report" id="report" style={{position:"relative"}}>
                {channels && <FiltersReport 
                     searchState={searchState}
                     setSearchState={setSearchState}
                     channels={channels}
                     user={user}
                     isTypeUser={user?.data?.as}
                />}
                <div style={{gap:"10px", justifyContent:"space-between", marginTop:"30px", display:"grid"}} className="dashboard-report-responsive">
                {
                    loadingDeals 
                    ? <LoadingDashboard />
                    : (<div style={{cursor:"pointer"}}onClick={() => user?.data?.as?.toUpperCase() === "SALES" && history.push({
                            pathname: "/dashboard/see-details/invoice",
                            state:{
                                data:user,
                                formatDate:searchState,
                                invoiceType:"deals",
                                typeUser: searchState.userType
                            }

                        })
                      }>
                        <CardReport 
                            title="Deals" 
                            compare={reportDeals?.deals?.compare} 
                            target={reportDeals?.deals?.target_deals} 
                            value={reportDeals?.deals?.value}
                            isDataUser={user?.data ?? null} 
                            type="deals" 
                            showBar={true} 
                            isValue={reportDeals?.deals?.target_deals} 
                            showArrow={true}
                        
                        />
                        </div>
                    )
                }
                {
                    loadingNewLeads 
                    ? <LoadingDashboard />
                    : (<div style={{cursor:"pointer"}} onClick={() => user?.data?.as?.toUpperCase() === "SALES" && history.push({
                            pathname: "/dashboard/see-details/leads",
                            state:{
                                data:user,
                                formatDate:searchState,
                                typeUser: searchState.userType,
                                statusActive:0
                            }
                        })
                      }>
                        <CardReport 
                            title="New Leads" 
                            compare={reportNewLeads?.new_leads?.compare} 
                            target={reportNewLeads?.new_leads?.target_leads} 
                            value={reportNewLeads?.new_leads?.value}
                            isDataUser={user?.data ?? null} 
                            type="new-leads" 
                            showBar={true} 
                            isValue={reportNewLeads?.new_leads?.target_leads} 
                            showArrow={true}
                        
                        />
                        </div>
                    )
                }
                {
                    loadingDeals 
                    ? <LoadingDashboard />
                    : (<div 
                        style={{ cursor: "pointer" }}
                        onClick={() => user?.data?.as?.toUpperCase() === "SALES" && history.push({
                        pathname: "/dashboard/see-details/interior-design",
                        state:{
                            data:user,
                            formatDate:searchState,
                            typeUser: searchState.userType
                        }

                        })
                    }>
                        <CardReport 
                            title="Interior Design" 
                            compare={null} 
                            target={null} 
                            value={reportDeals?.interior_design?.value}
                            isDataUser={user?.data ?? null} 
                            type="interior-design" 
                            showBar={false} 
                            isValue={reportDeals?.interior_design?.total_transaction} 
                            showArrow={false}
                        
                        />
                        </div>
                    )
                }
                {
                    loadingDeals 
                    ? <LoadingDashboard />
                    : (<div
                        style={{ cursor: "pointer" }}
                        onClick={() => user?.data?.as?.toLowerCase() === "SALES" && history.push({
                            pathname: "/dashboard/see-details/invoice",
                            state:{
                            data:user,
                                formatDate:searchState,
                                invoiceType:"retail",
                                typeUser: searchState.userType
                            }

                        })
                    }
                    >
                        <CardReport 
                            title="Retail" 
                            compare={null} 
                            target={null} 
                            value={reportDeals?.retail?.value}
                            isDataUser={user?.data ?? null} 
                            type="retail" 
                            showBar={false} 
                            isValue={reportDeals?.retail?.total_transaction} 
                            showArrow={false}
                        
                        />
                        </div>
                    )
                }
                </div>

                <div style={{gap:"10px", justifyContent:"space-between", marginTop:"50px", cursor:"pointer", display:"grid"} }
                    className="dashboard-report-responsive"
                    onClick={() => user?.data?.as?.toUpperCase() === "SALES" && history.push({
                      pathname: "/dashboard/see-details/leads",
                      state:{
                        data:user,
                        formatDate:searchState,
                        typeUser: searchState.userType,
                        statusActive:1
                      }

                    })
                }
                >
                {
                    loadingActiveLeads 
                    ? <LoadingDashboard />
                    : (<div>
                        <CardReport 
                        title="Active Leads" 
                        compare={null} 
                        target={null} 
                        value={reportActiveLeads?.active_leads?.value}
                        isDataUser={user?.data ?? null} 
                        type="active-leads" 
                        showBar={false} 
                        isValue={null} 
                        showArrow={false}
                    
                    />
                    </div>
                    )
                }
                {
                    loadingQuotations 
                    ? <LoadingDashboard />
                    : (<div
                        style={{ cursor: "pointer" }}
                        onClick={() => user?.data?.as?.toUpperCase() === "SALES" && history.push({
                            pathname: "/dashboard/see-details/invoice",
                            state:{
                                data:user,
                                formatDate:searchState,
                                invoiceType:"quotation",
                                typeUser: searchState.userType
                            }

                        })
                    }
                    >
                        <CardReport 
                        title="Quotation" 
                        compare={reportQuotations?.quotation === undefined || reportQuotations?.quotation === null ? 0 : reportQuotations?.quotation.compare} 
                        target={null} 
                        value={reportQuotations?.quotation?.value}
                        isDataUser={user?.data ?? null} 
                        type="quotation" 
                        showBar={false} 
                        isValue={null} 
                        showArrow={true}
                    
                    />
                    </div>
                    )
                }
                {
                    loadingEstimations 
                    ? <LoadingDashboard />
                    : (<div
                        style={{ cursor: "pointer" }}
                        onClick={() => history.push({
                            pathname: "/dashboard/see-details/pipelines",
                            state:{
                                data:user,
                                formatDate:searchState,
                                typeUser: searchState.userType
                            }

                        })
                    }
                    >
                        <CardReport 
                            title="Pipelines" 
                            compare={reportEstimations?.estimation?.compare} 
                            target={null} 
                            value={reportEstimations?.estimation?.value}
                            isDataUser={user?.data ?? null} 
                            type="pipelines" 
                            showBar={false} 
                            isValue={null} 
                            showArrow={true}
                        
                        />
                        </div>
                    )
                }
                {
                    loadingDeals 
                    ? <LoadingDashboard />
                    : (<div>
                        <CardReport 
                            title="Exhibition" 
                            compare={null} 
                            target={null} 
                            value={reportDeals?.exhibition?.value}
                            isDataUser={user?.data ?? null} 
                            type="exhibition" 
                            showBar={false} 
                            isValue={reportDeals?.exhibition?.total_transaction} 
                            showArrow={false}
                        
                        />
                        </div>
                    )
                }
                </div>
                <div style={{marginTop:"30px"}}>
                    {loadingLeadStatus || loadingTotalLeads ?
                        <LoadingDashboard />
                    :(<div>
                        <div className="row-remove">
                            <div className="col-md-6-remove">
                                <div className="follow-up">
                                    <div className="skills-content p-3 row" data-aos="fade-up">
                                        <div className='total-follow-up col-lg-5' data-aos='fade-up' style={{cursor:"pointer"}}>
                                            <h3 className="mb-3">Total Follow Ups</h3>
                                            <h4 style={{color: "#17949D", position: "relative", width: "8rem"}}>{reportTotalLeads?.total_leads?.value} {parseInt(reportTotalLeads?.total_leads?.value) < parseInt(reportTotalLeads?.total_leads?.compare) ? (<span style={{width:"0", height:"0", borderLeft: "5px solid transparent", borderRight: "5px solid transparent", marginLeft: "10px", display: "inline-block", position: "absolute", top:"50%", transform: "translateY(-50%)", right:"0", borderTop:"10px solid red" }}></span>) : (<span style={{width:"0", height:"0", borderLeft: "5px solid transparent", borderRight: "5px solid transparent", marginLeft: "10px", display: "inline-block", position: "absolute", top:"50%", transform: "translateY(-50%)", right:"0", borderBottom:"10px solid green" }}></span>)}</h4>
                                            <IsBar 
                                                value={reportTotalLeads?.total_leads?.value}
                                                target={reportTotalLeads?.total_leads?.target_leads}
                                                colorPercent={"#17949D"}
                                            />
                                            <p>Target: {reportTotalLeads?.total_leads?.target_leads}</p>
                                        </div>
                                        <div className="follow-up-remove col-lg-7">
                                            <div className="skills-content" data-aos="fade-up">
                                                <h3 className='mb-3'>Lead Status</h3>
                                                <div style={{ cursor:"pointer"}} onClick={() => history.push(`/dashboard/follow-up-activities/${"COLD"}/${user?.data?.id}${searchState.start !== "" ? "/" + searchState.start : ""}${searchState.end !== "" ? "/" + searchState.end : ""}`)} >
                                                    <Skill
                                                    title={"Cold"}
                                                    progress={
                                                        (reportLeadStatus?.follow_up?.cold_activities / reportTotalLeads?.total_leads?.value) * 100
                                                    }
                                                    color={pickColor("COLD")}
                                                    value={reportLeadStatus?.follow_up?.cold_activities}
                                                    />
                                                </div>
                                    
                                    
                                                <div style={{ cursor:"pointer"}} onClick={() => history.push(`/dashboard/follow-up-activities/${"HOT"}/${user?.data?.id}${searchState.start !== "" ? "/" + searchState.start : ""}${searchState.end !== "" ? "/" + searchState.end : ""}`)} >
                                                    <Skill
                                                    title={"Hot"}
                                                    progress={
                                                        (reportLeadStatus?.follow_up?.hot_activities / reportTotalLeads?.total_leads?.value) * 100
                                                    }
                                                    color={pickColor("HOT")}
                                                    value={reportLeadStatus?.follow_up?.hot_activities}
                                                    />
                                                </div>
                                    
                                                <div style={{ cursor:"pointer"}} onClick={() => history.push(`/dashboard/follow-up-activities/${"WARM"}/${user?.data?.id}${searchState.start !== "" ? "/" + searchState.start : ""}${searchState.end !== "" ? "/" + searchState.end : ""}`)} >
                                                    <Skill
                                                    title={"Warm"}
                                                    progress={
                                                        (reportLeadStatus?.follow_up?.warm_activities / reportTotalLeads?.total_leads?.value) * 100
                                                    }
                                                    color={pickColor("WARM")}
                                                    value={reportLeadStatus?.follow_up?.warm_activities}
                                                    />
                                                </div>
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>
                    </div>)}
                </div>
                <Popup popup={comparationPopup} setPopup={setComparationPopup}>
                    <ComporationPopUp isData={
                        {
                            deals:reportDeals?.deals,
                            active_leads:reportActiveLeads?.active_leads,
                            estimation:reportEstimations?.estimation,
                            new_leads:reportNewLeads?.new_leads,
                            quotation:reportQuotations?.quotation,
                            follow_up: {
                                total_activities:{
                                    value: reportTotalLeads?.total_leads?.value,
                                    compare: reportTotalLeads?.total_leads?.compare,
                                    target_activities: reportTotalLeads?.total_leads?.target_leads
                                },
                                cold_activities:reportLeadStatus?.follow_up?.cold_activities,
                                hot_activities:reportLeadStatus?.follow_up?.hot_activities,
                                warm_activities:reportLeadStatus?.follow_up?.warm_activities
                            },
                            retail:reportDeals?.retail,
                            exhibition: reportDeals?.exhibition,
                            interior_design: reportDeals?.interior_design,
                            original_date: reportDeals?.original_date,
                            compare_date: reportDeals?.compare_date
                        }
                    } isType="BRAND" isUser={user} isReport="pipelines"/>
                </Popup>
            </div>
        </>
    )
};


const mapStateToProps = (state) => ({
    auth: state.auth,
    target: state.target,
    prosesData: state.prosesData
  });
  

export default connect(mapStateToProps)(DashboardReport)

