import axios from "axios";
import moment from "moment";
import React, { useEffect, useState } from "react";
import { Link, useParams } from "react-router-dom";
import { mainUrl } from "../../api/api";
import FilterLeadsReport from "../FilterForm/FilterLeadsReport";
import Header from "../Header/Header";
import LoadedComponent from "../Loaded/LoadedComponent";

const DropReport = () => {
  const params = useParams();
  const today = new Date();
  const { user_type, user_id, start, end } = params;
  const [dropData, setDropData] = useState();
  const [isLoading, setIsLoading] = useState();

  const [filterCompany, setFilterCompany] = useState();
  // const [filterChannels, setFilterChannels] = useState();

  // const [filterSupervisior, setFilterSupervisor] = useState();
  const [filterStartDate, setFilterStartDate] = useState(
    start !== "now" ? start : ""
  );
  const [filterEndDate, setFilterEndDate] = useState(end !== "now" ? end : "");
  useEffect(() => {
    const startDate = localStorage.getItem("date_leads_start")
        
    const endDate = localStorage.getItem("date_leads_end");

    if(startDate === undefined || startDate === null){
      localStorage.setItem("date_leads_start", params.start)
      if(endDate === undefined || endDate === null){
        localStorage.setItem("date_leads_end", params.end);
      }
     
    }
  },[params])
  useEffect(() => {
    
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };

    const getReportDrop = async () => {
      setIsLoading(true);
      const isTypeUser = await localStorage.getItem("user_type_leads_filter");
      const isChannels = await localStorage.getItem("channels_leads_filter");
      const isEndDate = localStorage.getItem("date_leads_end");
      const isStartDate = localStorage.getItem("date_leads_start");
      const checkStart = isStartDate !== null && isStartDate !== undefined && isStartDate !== "now" ? isStartDate : filterStartDate
      const checkEnd = isEndDate !== null && isEndDate !== undefined && isEndDate !== "now" ? isEndDate : filterEndDate
      try {
        const res = await axios.get(
          `${mainUrl}/dashboard/report-leads/drop?start_date=${
            checkStart
          }&end_date=${
            checkEnd
          }&company_id=${filterCompany ? filterCompany : ""}&${
            isTypeUser === "sales"
          ?"sales_id=" + parseInt(user_id ?? "")
          : isTypeUser === "store"
            ? "channel_id=" + parseInt(user_id ?? "")
            : "supervisor_id=" + parseInt(user_id ?? "")
          }`,
          config
        );
     
        setDropData(res.data);
        setIsLoading(false);
      } catch (error) {
        console.error(error);
        setIsLoading(false);
      }
    };

    getReportDrop();
  }, [user_type, user_id, start, end, filterStartDate, filterEndDate, filterCompany]);

  const exportReportDrop = async () => {
    const isTypeUser = await localStorage.getItem("user_type_leads_filter");
    const isChannels = await localStorage.getItem("channels_leads_filter");
    axios
      .get(
        `${mainUrl}/dashboard/report-leads/drop?start_date=${
          filterStartDate ? moment(filterStartDate).format("YYYY-MM-DD") : ""
        }&end_date=${
          filterEndDate ? moment(filterEndDate).format("YYYY-MM-DD") : ""
        }&company_id=${filterCompany ? filterCompany : ""}&${
          isTypeUser === "sales"
          ?"sales_id=" + parseInt(user_id ?? "")
          : isTypeUser === "store"
            ? "channel_id=" + parseInt(user_id ?? "")
            : "supervisor_id=" + parseInt(user_id ?? "")
        }&is_export=1`,
        {
          method: "GET",
          responseType: "blob", // important
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${localStorage.token}`,
          },
        }
      )
      .then((response) => {
        const url = window.URL.createObjectURL(new Blob([response.data]));
        const link = document.createElement("a");
        link.href = url;
        link.setAttribute(
          "download",
          `Report Drop ${
            filterStartDate
              ? moment(filterStartDate).format("YYYY-MM-DD")
              : moment(today).format("MM YYYY")
          }.xlsx`
        );
        document.body.appendChild(link);
        link.click();
      })
      .catch((err) => {
        console.log();
      });
  };

  return (
    <div>
      <Header icon="" title={`Report Leads - Drop`} back={true} user={false} />
      <FilterLeadsReport
        company={false}
        channel={false}
        supervisor={false}
        download={exportReportDrop}
        setFilterStartDate={setFilterStartDate}
        setFilterEndDate={setFilterEndDate}
      />
      {isLoading ? (
        <LoadedComponent />
      ) : (
        <div>
          <table>
            <thead>
              <tr>
                <th>No.</th>
                <th>Sales</th>
                <th>Customer</th>
                <th>Channel</th>
                <th>Action</th>
              </tr>
            </thead>
            <tbody>
              {dropData &&
                dropData.map((data, idx) => {
                  console.log(data.sales);
                  return (
                    <tr key={idx}>
                      <td>{idx + 1}</td>
                      <td>{data.sales ? data.sales.name : ""}</td>
                      <td>
                        {data.customer.first_name} {data.customer.last_name}
                      </td>
                      <td>{data.channel.name}</td>
                      <td>
                        <Link
                          to={`/dashboard/customers/customer_detail/${data.id}/${data.customer_id}`}
                        >
                          Lead Detail
                        </Link>
                      </td>
                    </tr>
                  );
                })}
            </tbody>
          </table>
        </div>
      )}
    </div>
  );
};

export default DropReport;
