import { mainUrl, mainUrlVTwo } from "../../../../api/api"
import Axios from "axios"
// import { config } from "../../../../api/api";
import { useQuery } from "react-query";
import moment from "moment";
// export const config = {
//     headers: {
//       "Content-Type": "application/json",
//       Authorization: `Bearer ${localStorage.token}`,
//     },
//   };
// temporaryState
export const useReportDeals = ({user, temporaryState, config}) => {

    return useQuery([`reportDeals${user?.data?.id}`, {temporaryState, user}], () => {
        return Axios.get(`${mainUrlVTwo}/new-reports/sub/deals?company_id=${temporaryState.companyId ?? ""}&channel_id=${temporaryState.channelId ?? ""}&user_id=${user?.data?.id}&start_date=${temporaryState.start ?? ""}&end_date=${temporaryState.end ?? ""}&user_type=${temporaryState.userType === "store" ? "store" : ""}`, config)
        .then((data) => {
            return data.data
            }).catch((error) => error)
    }, {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity})
    
   
}

export const useActiveLeads = ({user, temporaryState, config}) => {
    const startDate = moment(new Date()).subtract(2, 'months').startOf('month').format('YYYY-MM-DD')
    return useQuery([`reportActiveLeads${user?.data?.id}`, {temporaryState, user}], () => {
        return Axios.get(`${mainUrlVTwo}/new-reports/sub/active-leads?company_id=${temporaryState.companyId ?? ""}&channel_id=${temporaryState.channelId ?? ""}&user_id=${user?.data?.id}&start_date=${temporaryState.start === "" ? startDate : temporaryState.start}&end_date=${temporaryState.end === "" ? moment(new Date()).format("YYYY-MM-DD") : temporaryState.end}&user_type=${temporaryState.userType === "store" ? "store" : ""}`, config)
        .then((data) => {
            return data.data
            }).catch((error) => error)
    }, {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity})
    
}

