import React, { useEffect, useState } from "react";
import Button from "../../../components/Button/Button";
import Slider from "react-slick";
import { Link } from "react-router-dom";
import axios from "axios";
import { mainUrl } from "../../../api/api";
import { useParams } from "react-router-dom";
import { connect, useDispatch } from "react-redux";
import { temporaryCartLoad } from "../../../redux/action/product";
import NewArrivals from "../../../components/Product-Components/NewArrivals";
import Stocks from "./Stocks";
import CartPopup from "../../../components/Popup/Popup Component/CartPopup";
import Popup from "../../../components/Popup/Popup";
import { loadActiveCarts } from "../../../redux/action/product";
const ProductDetail = ({ product: { temporaryCart, carts } }) => {
  const { model_id } = useParams();
  const dispatch = useDispatch();
  const [productDetail, setProductDetail] = useState(null);
  const [productUnit, setProductUnit] = useState(null);
  const [cart, setCart] = useState();
  const [leadPopup, setLeadPopup] = useState(false)
  useEffect(() => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };

    const getProductDetail = async () => {
      try {
        const res = await axios.get(`${mainUrl}/models/${model_id}`, config);
        setProductDetail(res.data.data);
      } catch (error) {
        console.error(error);
      }
    };

    getProductDetail();
  }, [model_id]);
  useEffect(() => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
    const getProductUnit = async () => {
      try {
        const res = await axios.get(
          `${mainUrl}/product-units/${temporaryCart[0].id}`,
          config
        );
        setProductUnit(res.data.data);
      } catch (error) {
        console.error(error);
      }
    };
    if (temporaryCart.length) {
      getProductUnit();
      setCart(temporaryCart);
      dispatch(temporaryCartLoad());
    }
  }, [temporaryCart]);
  console.log(productDetail, "checking yah")
  const addCart = async () => {
    
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
    const items = cart ? cart : carts && carts.data.items;
    carts.data.items.length > 0 &&
      cart &&
      carts.data.items
        .filter((item) => item.id !== cart.id)
        .map((data) => {
          items.push(data);
        });
    const data = { items: items };
    try {
      const res = await axios.put(`${mainUrl}/carts`, data, config);
      if(res.status === 200){
        window.location.assign("/dashboard/product/cart")
      }
    } catch (error) {}
  };

  const settingsImg = {
    customPaging: function (i) {
      return (
        <div>
          <img
            src={productDetail.images[0].url}
            style={{ width: "100%" }}
            alt={productDetail.images[0].url}
          />
        </div>
      );
    },
    dots: true,
    dotsClass: "slick-dots slick-thumb",
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
  };
  return (
    productDetail && (
      <div className="product-detail" id="product-detail">
        <Popup popup={leadPopup} setPopup={() => setLeadPopup()}>
          <CartPopup />
        </Popup>
        <div className="product-detail-content row">
          <div className="col-md-5 product-img">
            <Slider {...settingsImg}>
              <div>
                <img
                  src={productDetail.images[0].url}
                  alt="productDetail"
                  style={{
                    width: "100%",
                  }}
                />
              </div>
              <div>
                <img
                  src={productDetail.images[0].url}
                  alt="productDetail"
                  style={{ width: "100%" }}
                />
              </div>
              <div>
                <img
                  src={productDetail.images[0].url}
                  alt="productDetail"
                  style={{ width: "100%" }}
                />
              </div>
              <div>
                <img
                  src={productDetail.images[0].url}
                  alt="productDetail"
                  style={{ width: "100%" }}
                />
              </div>
            </Slider>
            <div className="mt-3">
              <Link to={`/dashboard/product/product_option/${model_id}`}>
                <Button
                  title="Select Option"
                  btnStyle="primary-btn"
                  icon=""
                  btnWidth="100%"
                />
              </Link>
            </div>
          </div>
          <div className="desc col-md-7">
            <h4>{productDetail.name}</h4>
            {productUnit ? (
              <>
                <ul>
                  <li>{productUnit.name}</li>
                  <li>{productUnit.covering.name}</li>
                  <li>{productUnit.colour.name}</li>
                </ul>
                <h5>Rp. {productUnit.price}</h5>
              </>
            ) : (
              <h5>
                {productDetail.price_min} s/d {productDetail.price_max}
              </h5>
            )}

            <p>{productDetail.description}</p>
            <div className="d-flex">
              {/* <Link
                className="me-2"
                onClick={() => addCart()}
                to="/dashboard/product/cart"
              > */}
              <div onClick={() => addCart()} style={{marginRight:"10px"}}>
                <Button btnStyle="primary-btn" title="Add To Cart" icon="" />
                </div>
              {/* </Link> */}
              <div>
                <Button btnStyle="outline-btn" title="Checkout" icon="" onClick={() => {
                
                      // setLeadPopup(!leadPopup);
                      // dispatch(loadActiveCarts([productDetail]));
                  
                }}/>
              </div>
            </div>
          </div>
        </div>
        <div style={{marginTop:"30px"}}>
          <Stocks idProduct={productDetail.id ?? 0}/>
        </div>
        <NewArrivals />
      </div>
    )
  );
};

const mapStateToProps = (state) => ({
  product: state.product,
});

export default connect(mapStateToProps)(ProductDetail);
