import React, { useEffect, useState, useMemo } from "react";
import { isFilterDate } from "../../../redux/action/idUser";
import { useHistory, useParams } from "react-router-dom";
import LoadedComponent from "../../../components/Loaded/LoadedComponent";
import HeadDashboardSeeDetail from "./DashboardSeeDetail/HeadDashboardSeeDetail";
import TableSeeDetail from "./DashboardSeeDetail/TableSeeDetail";
import { useDispatch } from "react-redux";
import XLSX from "xlsx-js-style"
import { connect } from "react-redux";
import { useUserList, useUserListInt } from "./api/useUsersList";
import { dataFromPaginateds } from "./api/dataFromPaginateds";
import { mainUrlVTwo, config } from "../../../api/api";
import axios from "axios";
import { PDFDocument } from "pdf-lib";
import { useExportDetail } from "./api/useExportDetail";
import { formatCurrency } from "../../../api/format";
import moment from "moment";
const DashboardSeeDetail = ({auth: {user}, prosesData: {dataFilterDate, idChannels, idCompany}}) => {
  const [isLoadingExport, setIsLoadingExport] = useState(false);
  const [filterName, setFilterName] = useState("")
  const [isPagination, setIsPagination] = useState(1);
  const history = useHistory()
  const {userType} = useParams();
  const dispatch = useDispatch();
  const [dataExport, setDataExport] = useState(null)
  const [searchState, setSearchState] = useState({
    userType: userType === "director" 
    ? "head_sales" 
    : userType === "hs" 
      ? "bum" 
      : userType === "bum" 
        ? "store_leader" 
        : userType === "store_leader" 
          ? "sales" 
          : "",
    companyId: "",
    searchValue:"",
    start: dataFilterDate.start === undefined ? "" : dataFilterDate.start,
    end: dataFilterDate.end === undefined ? "" : dataFilterDate.end,
    userFilter:null,
    channelId: idChannels === undefined || idChannels === null ? "" : idChannels,
    onTouch: false
  });
  
  const [filterOnTouch, setFilterOnTouch] = useState({
    userType: userType === "director" 
              ? "head_sales" 
              : userType === "hs" 
                ? "bum" 
                : userType === "bum" 
                  ? "store_leader" 
                  : userType === "store_leader" 
                    ? "sales" 
                    : "",
    companyId: "",
    searchValue:"",
    start: dataFilterDate.start === undefined ? "" : dataFilterDate.start,
    end: dataFilterDate.end === undefined ? "" : dataFilterDate.end,
    userFilter:null,
    channelId: idChannels === undefined || idChannels === null ? "" : idChannels
  });

  const roleButton = useMemo(() => (
    {
      director: ["Head Sales", "Bum", "Store Leader", "Store", "Sales"],
      hs: ["Bum", "Store Leader", "Store" ,"Sales"],
      bum: ["Store Leader", "Store", "Sales"],
      store_leader:["Store", "Sales"],
      store: ["Sales"]
    }
  ), []);
  const {data: userInf, fetchNextPage, isLoading:loadingUser, error, isFetching} = useUserListInt({filterOnTouch, isPage: isPagination, filterName});
  
  // const {data:dataUserList, } = useUserList({filterOnTouch, isPage: isPagination, filterName});
  const spliceUsers = useMemo(() => {
    const isUserlist = dataFromPaginateds(userInf);
    return isUserlist
  }, [userInf]);
  useMemo(() => {
    if(searchState.onTouch){
      dispatch(isFilterDate(searchState))
    }
    searchState.onTouch && setFilterOnTouch((prev) => ({
      ...prev,
      userType: searchState.userType,
      companyId: searchState.companyId,
      searchValue: searchState.searchValue,
      start: searchState.start,
      end: searchState.end,
      userFilter:null,
    }));

    
  }, [searchState, dispatch]);

  useEffect(() => {
    
    if(user?.data?.as?.split(" ")?.join("_")?.toLowerCase() !== userType && user !== undefined){
      history.push(`/dashboard/dashboard-see-detail/${user?.data?.id}/${user?.data?.as?.split(" ")?.join("_")?.toLowerCase()}`)
    }
  }, [userType, history, user]);
  
  useEffect(() => {
    searchState.onTouch && setSearchState((prev) => ({
      ...prev,
      onTouch:false
    }))
  }, [searchState]);

  const stylingXlsx = ({color, worksheet, cellRef}) => {
    worksheet[cellRef].s = {
      ...worksheet[cellRef].s,
      font: {
        sz: 14
      },
      fill:{
        type: 'pattern',
        pattern: 'solid',
        fgColor: { rgb: color }
      },
      border: {
        top: {style: "thin", color: {auto: 1}},
        right: {style: "thin", color: {auto: 1}},
        bottom: {style: "thin", color: {auto: 1}},
        left: {style: "thin", color: {auto: 1}}
      }
    }
  }
  const handleExportButton = async () => {
    // moment(new Date()).format("YYYY-MM-DD");
    const paramsQuotation = (searchState.start !== "" || searchState.end !== "") ? "" : `&quotation_start_date=2020-01-01&quotation_end_date=${moment(new Date()).format("YYYY-MM-DD")}`
    setIsLoadingExport(true)
    const resultExp = await axios.get(`${mainUrlVTwo}/new-reports/export-dashboard-detail?is_my_report=0&company_id=${searchState.companyId ?? ""}&channel_id=${searchState.channelId ?? ""}&user_id=${user?.data?.id}&start_date=${searchState?.start ?? ""}&end_date=${searchState?.end ?? ""}&user_type=${searchState?.userType}${paramsQuotation}`, config).then((res) => res).catch((err) => err);
    
        const rows = resultExp?.data?.trim()?.split('\n')?.map(row => row?.split(','));
        const parseJson = rows?.map((isData) => isData?.map((isRes, indx) => {
          const isParse = JSON.parse(isRes);
          const toNumb = parseFloat(isParse);
          if(isParse === ""){
            return 0
          }
          
          if(isNaN(toNumb)){
            return isParse;
          }
          if(indx === 1 || indx === 4 || indx === 6 || indx === 7 || indx === 8){
            const toFormat = formatCurrency(toNumb, true)?.replace(
              /([A-Za-z])\w+/g,
              ""
            )
            if(toFormat < 1){
              return 0
            }
            return `RP. ${formatCurrency(toNumb, true)?.replace(
              /([A-Za-z])\w+/g,
              ""
            )}`;
          }
          return toNumb;
        }));
        const workbook = XLSX.utils.book_new();
        const worksheet = XLSX.utils.aoa_to_sheet(parseJson);
        // XLSX.utils.book_append_sheet(workbook, worksheet, "sheet_name_here");
        // XLSX.writeFile(workbook, `reports.xlsx`);
        const range = XLSX.utils.decode_range(worksheet["!ref"] ?? "");
        const rowCount = range.e.r;
        const columnCount = range.e.c;
        var wscols = [
          {wch:10},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
          {wch:25},
        ];
      
        worksheet['!cols'] = wscols;
        for (let row = 0; row <= rowCount; row++) {
            for (let col = 0; col <= columnCount; col++) {
              const cellRef = XLSX.utils.encode_cell({ r: row, c: col });
              // Add center alignment to every cell
              worksheet[cellRef].s = {
                alignment: { horizontal: "center" },
              };
              if(row === 0){
                worksheet[cellRef].s = {
                  ...worksheet[cellRef].s,
                  font: {
                    bold: true,
                    sz: 16,
                    color: {rgb: "00000"}
                  },
                  
                }
              }
              if(row !== 0){
                if(col === 0 || col === 1){
                  stylingXlsx({
                    worksheet,
                    cellRef,
                    color:"ffffffff"
                  })
                }
                if(col > 1 && col < 6){
                  stylingXlsx({
                    worksheet,
                    cellRef,
                    color:"ff4ca6c1"
                  })
                }
                if(col > 8){
                  stylingXlsx({
                    worksheet,
                    cellRef,
                    color:"ffacdd6e"
                  })
                }
                if(col === 8){
                  stylingXlsx({
                    worksheet,
                    cellRef,
                    color:"ff94d244"
                  })
                }
                if(col === 6 || col === 7){
                  stylingXlsx({
                    worksheet,
                    cellRef,
                    color:"ff5fc1de"
                  })
                }
              }
            }
          }
       

        XLSX.utils.book_append_sheet(workbook, worksheet, "sheet_name_here");
        XLSX.writeFile(workbook, `reports.xlsx`);
        setIsLoadingExport(false)
    
  }
  // if(loadingUser){
  //   return <LoadedComponent/>
  // }
  if(error){
    return <h4>Terjadi kesalahan</h4>
  }
  return (
    <div className="container">
    {isLoadingExport && <div style={{position:"absolute", top:0, left:0, background:"rgb(0,0,0,0.2)", width:"100%", height:"100vh",zIndex:"999"}}>
      <div style={{marginTop:"300px"}}>
        <LoadedComponent />
      </div>
    </div>}
      <HeadDashboardSeeDetail 
          setSearchState={setSearchState} searchState={searchState} suggestUsers={[]} setFilterName={setFilterName} filterName={filterName}
        />
        {loadingUser && <LoadedComponent />}
        {!loadingUser && <>
        <div style={{display:"flex", gap:"30px", justifyContent:"space-around", margin: "40px 0"}}>
          {roleButton[user?.data?.as?.toLowerCase()?.split(" ")?.join("_")]?.map((role, idx) => {
            return (
              <React.Fragment key={idx}>
                
                <button 
                  onClick={() => {
                    setIsPagination(1)
                    setDataExport(null)
                    setSearchState((prev) => ({...prev, userType: role?.split(" ")?.join("_")?.toLowerCase() === "head_sales" ? "head_sales" : role?.split(" ")?.join("_")?.toLowerCase(), onTouch: true}))
                  }}
                  style={{
                    outline: "none",
                    background: role?.split(" ")?.join("_")?.toLowerCase() === searchState.userType ? "#20b5c0" : role?.split(" ")?.join("_")?.toLowerCase() === "head_sales" && searchState.userType === "hs" ? "#20b5c0" : "#17949d",
                    padding: "10px 30px",
                    borderRadius: "5px",
                    color:"white",
                    border:"0",
                  }}
                >
                  {role}
                </button>
              </React.Fragment>
            )
          })}
          
        </div>
        {/* <TableSeeDetail searchState={searchState} users={spliceUsers} dataUsers={dataUserList}/> */}
        {<button style={{border:"0", outline:"0", padding:"10px 20px", borderRadius:"5px", background:"#17949d", color:"white"}} onClick={handleExportButton}>Export</button>}
        <table
          className="data d-block"
          style={{ margin: "10px 0", overflowX: "scroll", width: "auto", position:"relative" }}
        >
          <thead>
            <tr>
              <th>No</th>
              {/* <th className='sticky' style={{position:"sticky", left:"0"}}>Name</th> */}
              <th>Name</th>
              <th>Deals</th>
              <th>New Leads</th>
              <th>Interior Design</th>
              <th>Retails</th>
              <th>Active Leads</th>
              <th>Quotation</th>
              <th>Pipelines</th>
              <th>Exhibition</th>
              <th>Follow Up</th>
              <th>Hot</th>
              <th>Warm</th>
              <th>Cold</th>
              <th>Drop</th>
            </tr>
          </thead>
          <tbody onClick={() => {}}>
            {
              searchState.searchValue !== "" && searchState.userFilter !== null && searchState.userFilter?.length !== 0 && searchState?.userFilter?.map((user,i) => {
                return (
                  <React.Fragment key={i}>
                    <TableSeeDetail searchState={filterOnTouch} isUser={user} dataUsers={[]} index={i} setDataExport={setDataExport}/>
                  </React.Fragment>)
              })
            }
            {
              searchState.searchValue === "" || searchState.userFilter === null || searchState.userFilter?.length === 0 ? spliceUsers?.map((user,i) => {
                return (
                  <React.Fragment key={i}>
                    <TableSeeDetail searchState={filterOnTouch} isUser={user} dataUsers={[]} index={i} setDataExport={setDataExport}/>
                  </React.Fragment>)
              })
              : null
            }
          </tbody>
        </table>
        <div style={{display:"flex", gap:"10px"}}>
        {isPagination > 1 && <button 
            onClick={() => setIsPagination((prev) => prev-1)}
            style={{
              outline: "none",
              background:"#17949d",
              padding: "10px 30px",
              borderRadius: "5px",
              color:"white",
              border:"0",
            }}
          >
            Prev
          </button>}
          
          {userInf?.pages[(userInf?.pages?.length ?? 1) - 1]?.links?.next && <button 
            onClick={fetchNextPage}
            disabled={isFetching ? true : false}
            style={{
              outline: "none",
              background:"#17949d",
              padding: "10px 30px",
              borderRadius: "5px",
              color:"white",
              border:"0",
            }}
          >
            {!isFetching ? "See More" : "Loading..."}
          </button>}
        </div>
        </>}
    </div>
    
  )
}


const mapStateToProps = (state) => ({
  auth: state.auth,
  target: state.target,
  prosesData: state.prosesData
});

export default connect(mapStateToProps)(DashboardSeeDetail)