import axios from "axios";
import moment from "moment";
import React, { useEffect, useState } from "react";
import { useParams } from "react-router-dom";
import { mainUrl, config } from "../../../../api/api";
import Activity from "../../../../components/ActivityDetail/Activity";
import Header from "../../../../components/Header/Header";
// import Loaded from "../../../../components/Loaded/Loaded";
import { useQuery } from "react-query";
import Button from "../../../../components/Button/Button";
import LoadedComponent from "../../../../components/Loaded/LoadedComponent";
import { useMemo } from "react";
const ActivitiesFollowUpDetail = () => {
  const { status, id, start, end, company_id, channels_id } = useParams();
  const activitesStatus = useMemo(() => ["HOT", "WARM", "COLD"],[])
  // const [activitiesData, setActivitiesData] = useState(null);
  const [activityDetail, setActivityDetail] = useState(false);
  const [customerActivity, setCustomerActivity] = useState(null);
  const [orderId, setOrderId] = useState(null);
  const [mount, setMount] = useState(1)
  const [searchState, setSearchState] = useState({
    start: start ?? "",
    end: end ?? "",
    user_id:id ?? localStorage.getItem("user_id_log"),
    user_type: localStorage.getItem("user_type_log")?.toLocaleLowerCase() ?? "",
    company_id: company_id ?? "",
    channels_id: channels_id ?? "",
    activityStatus: activitesStatus.includes(status) ? status : ""
  });
  
  useEffect(() => {
    setSearchState((prev) => {
      return {
        ...prev,
        start: start !== undefined ? start : "",
        end:end !== undefined ? end : "",
        user_id: id ?? localStorage.getItem("user_id_log"),
        company_id: company_id !== undefined ? company_id : "",
        channels_id: channels_id !== undefined ? channels_id : ""
      }
    })
  }, [status, id, start, end, company_id, channels_id])
  const getFollowUpDetail = (searchState, mount) => {
    return axios.get(`${mainUrl}/leads/list?company_id=${searchState?.channels_id ?? ""}&channel_id=${""}&id=${searchState?.user_id ?? ""}&start_date=${searchState?.start ?? ""}&end_date=${searchState?.end ?? ""}&user_type=${searchState?.user_type ?? ""}&page=${mount}&activity_status=${searchState?.activityStatus ?? ""}`, config)
    .then((res) => res.data)
    .catch((error) => error)
  }

  const {data: followupDetail, isLoading} = useQuery(["followupDetail", searchState, mount], () => getFollowUpDetail(searchState, mount));
  // console.log(followupDetail, "check data follow up", status, id, start, end, company_id, channels_id );

  // useEffect(() => {
  //   const config = {
  //     headers: {
  //       "Content-Type": "application/json",
  //       Authorization: `Bearer ${localStorage.token}`,
  //     },
  //   };
  //   const getActivities = async () => {
  //     try {
  //       const res = await axios.get(
  //         `${mainUrl}/activities?filter[company_id]=${company_id}&filter[status]=${status}&filter[follow_up_datetime_before]=${moment(
  //           month
  //         )
  //           .endOf("month")
  //           .format("YYYY-MM-DD")}&filter[follow_up_datetime_after]=${moment(
  //           month
  //         )
  //           .startOf("month")
  //           .format("YYYY-MM-DD")}`,
  //         config
  //       );
  //       setActivitiesData(res.data.data);
  //     } catch (error) {
  //       console.error(error);
  //     }
  //   };
  //   getActivities();
  // }, [company_id, status, month]);
  const handleClickDetail = async (activity) => {
    try {
      const res = await axios.get(
        `${mainUrl}/activities?filter[id]=${activity?.id ?? ""}`,
        {
          headers: {
            "Content-Type": "application/json",
            Authorization: `Bearer ${localStorage.token}`,
          },
        }
      );
      setCustomerActivity(res?.data?.data[0]);
      // console.log(res.data);
    } catch (error) {
      console.error(error);
    }
    setActivityDetail(!activityDetail);
    setOrderId(activity.order ? activity.order.id  : null);
    // console.log(activity.activity);
  };
  // const handleClickDetail = (activity) => {
  //   setActivityDetail(!activityDetail);
  //   setCustomerActivity(activity);
  //   setOrderId(activity.id ?? undefined);
  // };
  if(isLoading){
    return <LoadedComponent />
  }
  return (<><div>
      <Header title={`Activities - ${status ?? ""}`} back={true} notif={true} />
      <div className="filter-form d-flex justify-content-between">
        {/* <div>
          <input
            type="text"
            id="search-sales"
            name="search-sales"
            className="form-control"
            placeholder="Search customer name/inv number"
            style={{ height: "41px", width: "327px" }}
          />
        </div> */}
        <div style={{display:"flex", gap:"20px"}}>
          <div>
            <span>Start:</span>
            <input
            type="date"
            id="start"
            name="start"
            value={searchState.start}
            className="form-control"
            placeholder="Start Month"
            style={{ height: "41px" }}
            onChange={(e) => setSearchState((prev) => ({...prev, start:e.target.value}))}
          />
          </div>
          <div>
            <span>End:</span>
            <input
            type="date"
            id="end"
            name="end"
            value={searchState.end}
            className="form-control"
            placeholder="Start Month"
            style={{ height: "41px" }}
            onChange={(e) => setSearchState((prev) => ({...prev, end:e.target.value}))}
          />
          </div>
        </div>
      </div>
      <div className="mt-4">
        <table className="data" style={{ margin: "10px 0" }}>
          <thead>
            <tr>
              <th>No</th>
              <th>Date</th>
              <th>Name</th>
              {/* <th>Follow Up</th> */}
              <th>Store Location</th>
              {/* <th>Feedback</th> */}
              <th>Email</th>
              <th>Sales</th>
              <th>Status</th>
              <th>Action</th>
            </tr>
          </thead>
          <tbody>
            {followupDetail?.data?.map((activity, i) => {
              return (
                <tr key={i}>
                  <td>{followupDetail?.meta?.from + i}</td>
                  <td>
                    {moment(activity?.created_at)?.format("MM/DD/YYYY")}
                  </td>
                  <td>{activity?.customer?.first_name}</td>
                  {/* <td>{activity?.follow_up_method}</td> */}
                  <td>{activity?.channel?.name}</td>
                  {/* <td>{activity?.feedback}</td> */}
                  <td>{activity?.customer?.email}</td>
                  <td>{activity?.user?.name}</td>
                  <td>{activity?.status}</td>
                  <td>
                    <div
                      onClick={() => handleClickDetail(activity)}
                      className="activity-detail-btn"
                    >
                      <img
                        src="/Asset/Action Icon/eye.png"
                        style={{ marginRight: "5px" }}
                        alt="eye"
                      />
                      See Detail
                    </div>
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
        <div style={{display:"flex", gap:"20px", marginTop:"50px", alignItems:"center"}}>
          <div style={{display: followupDetail.links.prev === null ? "none" : "block"}}>
        <Button
                onClick={(e) => setMount((prev) => prev-1)}
                icon=""
                title={"Prev"}
                style={{ width: "11rem!important"}}
                btnStyle={"primary-btn"}
              />
              </div>
              
              <div style={{display: followupDetail.links.next === null ? "none" : "block"}}>
               <Button
                onClick={(e) => {setMount((prev) => prev+1)}}
                icon=""
                title={"Next"}
                style={{ width: "11rem!important", display: followupDetail.links.next === null ? "none" : "block"}}
                btnStyle={"primary-btn"}
              />
              </div>
        </div>
      </div>
      {customerActivity ? (
        <Activity
          activityDetail={activityDetail}
          setActivityDetail={setActivityDetail}
          customerActivity={customerActivity}
          orderId={orderId}
        />
      ) : (
        ""
      )}
    </div></>)
  
};

export default ActivitiesFollowUpDetail;
