import axios from "axios";
import React, { useEffect } from "react";
import { connect } from "react-redux";
import { mainUrl } from "../../../api/api";
import Button from "../../Button/Button";
import "../../FilterForm/FilterLeadsReport.scss";
// /Users/hippo/moves-web/moves-web/src/components/FilterForm/FilterLeadsReport.scss
import "react-date-range/dist/styles.css"; // main css file
import "react-date-range/dist/theme/default.css"; // theme css file
import { roleUserType } from "../../FilterForm/RoleUserType";
import { useDispatch } from "react-redux";
import { reduxChangeBrand, reduxChangeChannel, reduxChangeCompany, reduxChangeCurrentChannel, reduxChangeUserType, reduxChangeStartEndDate } from "../../../redux/action/reportLeads";
const ReportLeadsHeader = ({
  target: { channels },
  searchState,
  setSearchState,
  type,
  channel = true,
  company = true,
  isFetch = false,
  user
}) => {
  const dispatch = useDispatch()
  const isUser = user?.data?.as?.toLowerCase()?.split(" ")?.join("_");
  
  useEffect(() => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
    const getSupervisors = async () => {
      try {
        const res = await axios.get(
          `${mainUrl}/users?filter[type]=SUPERVISOR&filter[descendant_of]=10&perPage=50`,
          config
        );
        setSearchState((prev) => ({
            ...prev,
            supervisorsList:res.data
        }))
      } catch (error) {
        console.error(error);
      }
    };

    const getBrands = async () => {
      try {
        const res = await axios.get(`${mainUrl}/brands`, config);
        setSearchState((prev) => ({
            ...prev,
            brandsList:res.data.data
        }))
      } catch (error) {
        console.error(error);
      }
    };

    isFetch && getBrands();

    isFetch && getSupervisors();
  }, [setSearchState, isFetch]);

  return (
    <>
    <div
      className="filter-leads-report d-flex "
      id="filter-leads-report"
      style={{gap:"20px", marginBottom:"20px"}}
    >
      <div className="report-filter-form d-flex" style={{gap:"10px"}}>
        {company && (
          <select
            className="form-select"
            name="companys"
            value={searchState.companyId}
            onChange={(e) => {
              dispatch(reduxChangeCompany(e.target.value))
              return setSearchState((prev) => ({
                ...prev,
                companyId: e.target.value
              }))
            }}
          >
            <option value="">Select Company</option>
            <option value={1}>Melandas</option>
            <option value={2}>Dio Living</option>
          </select>
        )}
        {channel && (
          <select
            className="form-select"
            name="channels"
            value={searchState.channelId}
            onChange={(e) => {
                dispatch(reduxChangeChannel(e.target.value))
                setSearchState((prev) => ({
                    ...prev,
                    channelId: e.target.value
                }))
            }}
          >
            <option value="">Select Channel</option>
            {channels &&
              channels?.data?.map((channel) => {
                return (
                  <option value={channel.id} key={channel.id}>
                    {channel.name}
                  </option>
                );
              })}
          </select>
        )}
        {(
          <select
            className="form-select"
            name="user"
            onChange={(e) => {
              dispatch(reduxChangeUserType(e.target.value))
              setSearchState((prev) => ({
                ...prev,
                userType: e.target.value
            }))
          }}
            value={searchState.userType}
          >
            <option value="">Select User</option>
            {isUser && roleUserType[isUser]?.map((data) => {
              return (
                <option value={data?.key}>{data?.role}</option>
              )
            }) }
          </select>
        )}
        {/* {supervisor && (
          <select
            className="form-select"
            name="supervisors"
            onChange={(e) => setFilterSupervisor(parseInt(e.target.value))}
          >
            <option value="">Select Supervisor</option>
            {supervisors &&
              supervisors.data.map((supervisor) => {
                return (
                  <option value={supervisor.id} key={supervisor.id}>
                    {supervisor.name}
                  </option>
                );
              })}
          </select>
        )} */}
        {/* {brand && (
          <select
            className="form-select"
            name="supervisors"
            onChange={(e) => setFilterBrand(parseInt(e.target.value))}
          >
            <option value="">Select Brands</option>
            {brands &&
              brands.map((brand) => {
                return (
                  <option value={brand.id} key={brand.id}>
                    {brand.name}
                  </option>
                );
              })}
          </select>
        )} */}
       
        <div className="d-flex align-items-center ms-1">
          <label>Start: </label>
          <input
            type="date"
            id="start"
            name="start"
            className="form-control"
            value={searchState.start}
            onChange={(e) => {
                dispatch(reduxChangeStartEndDate({start:e.target.value, end:searchState.end}))
                setSearchState((prev) => ({
                    ...prev,
                    start: e.target.value
                }))
            }}
          />
        </div>
        <div className="d-flex align-items-center ms-1 me-3">
          <label>End: </label>
          <input
            type="date"
            id="end"
            name="end"
            className="form-control"
            value={searchState.end}
            onChange={(e) => {
              dispatch(reduxChangeStartEndDate({start:searchState.start, end:e.target.value}))
                setSearchState((prev) => ({
                    ...prev,
                    end: e.target.value
                }))
            }}
          />
        </div>
      </div>
      {/* {download && (
        <div>
          <div onClick={() => download()} style={{ width: "fit-content" }}>
            <Button icon="" title="Export excel" btnStyle={"outline-btn"} />
          </div>
        </div>
      )} */}
      <Button onClick={() => {
       
        localStorage.removeItem("date_leads_start")
        localStorage.removeItem("date_leads_end")
        window.location.reload()
      }}
      icon=""
            title="Reset Filter"
            style={{ width: "11rem!important" }}
            btnStyle={"primary-btn"}
      ></Button>
    </div>
   
    </>
  );
};

const mapStateToProps = (state) => ({
  target: state.target,
});

export default connect(mapStateToProps)(ReportLeadsHeader);
