import React from 'react';
import Button from '../../components/Button/Button';
import { connect } from 'react-redux';
const MyFilters = ({prosesData: {dataFilterDate}, showSearch = true, showDate = true, showSelect = true, searchValue, setNewFilterDate, setStatusActivity, setSearchValue, setIsLoading, setFilterButton}) => {
    const handleChangeStatus = (e) => {
        setIsLoading(true)
        setStatusActivity(e.target.value)
    }
    const handleChangeSearch = (e) => {
        setSearchValue(e.target.value)
    }
    const handleChangeDate = (e) => {
        setNewFilterDate(prev => {
            return{
                ...prev,
                [e.target.name]: e.target.value
            }
        })
    }
    console.log(dataFilterDate, "check filter datenya yah")
    return(
        <>
            <div className='container-filters'>
                <div className='filter d-flex' style={{gap:"20px"}}>
                    <div className="col-auto" style={{gap:"20px", display: !showSearch && "none"}}>
                        <div>
                            <input type="text" id="search-table" className="form-control" onChange={handleChangeSearch}  placeholder='Search' value={searchValue} />
                        </div>
                    </div>
                    <select
                        style={{display: !showSelect && "none"}}
                        className="form-select"
                        name="channels"
                        onChange={handleChangeStatus}
                        >
                        <option value="">Select Status</option>
                        <option value="cold">COLD</option>
                        <option value="warm">WARM</option>
                        <option value="hot">HOT</option>
                        <option value="none">No Activity</option>
                    </select>
                    <div style={{display: !showDate ? "none" : "flex", alignItems: "center"}}>
                        <input
                        disabled
                            type="date"
                            id="start"
                            name="start"
                            className="form-control"
                            placeholder="Start Month"
                            onChange={handleChangeDate}
                            value={dataFilterDate.start === undefined ? "" :dataFilterDate.start}
                        />
                        <div className="input-group-addon"style={{margin: "0 10px"}}>to</div>
                        <input
                        disabled
                            type="date"
                            id="end"
                            name="end"
                            className="form-control"
                            placeholder="End Month"
                            onChange={handleChangeDate}
                            style={{margin:"0"}}
                            value={dataFilterDate.end === undefined ? "" : dataFilterDate.end}
                        />
                    </div>
                    <Button onClick={(e) => {
                        setIsLoading(true);
                        setFilterButton(true)
                    }}icon="" title="Filter" style={{width:"11rem!important", marginTop:"30px"}} btnStyle={"primary-btn"} />
                </div>
            </div>
        </>
    )
}
const mapStateToProps = (state) => ({
    auth: state.auth,
    target: state.target,
    prosesData: state.prosesData
  });
export default connect(mapStateToProps)(MyFilters)