import { ID_COMPANY, DATA_NEW_REPORTS, DATA_SEE_DETAILS, DATA_FILTER_DATE, ID_CHANNELS } from "./types"

export const filterIdCrud = (id) => (dispatch) => {
    dispatch({
        type: ID_COMPANY,
        value: id
    })
}

export const dataNewReports = (data) => (dispatch) => {
    dispatch({
        type: DATA_NEW_REPORTS,
        value: data
    })
}

export const dataSeeDetails = (data) => (dispatch) => {
    dispatch({
        type: DATA_SEE_DETAILS,
        value: data
    })
}

export const isFilterDate = (data) => (dispatch) => {
    dispatch({
        type: DATA_FILTER_DATE,
        value: data
    })
}

export const isChannelId = (data) => (dispatch) => {
    dispatch({
        type: ID_CHANNELS,
        value: data
    })
}