import React, {useCallback, useMemo} from 'react';

import AsyncSelect from 'react-select/async';
import kabkotList from "../../api/data_kabkot.json";

const SelectorKabkot = ({
    values,
    onChange,
    isMulti = false,
    filterCity=null
  }) => {
   
    const loadOptions = (search, callback) => {
         setTimeout(() => {
            const filterdData = kabkotList.filter((i) =>
                i.kabupaten_kota.toLowerCase().includes(search.toLowerCase() && i.provinsi_id == filterCity)
              ).map((i) => ({value: i.kabupaten_kota, label:i.kabupaten_kota}))
              return callback(filterdData.slice(0, 10))
        }, 500)
      }
 
    const options = kabkotList?.filter((i) => i.provinsi_id == filterCity).map((data) => ({
      value: data.kabupaten_kota,
      label: data.kabupaten_kota,
    })).slice(0,10);
 
    return (
      <>
        <AsyncSelect
        isDisabled={!filterCity ? true : false}
          isMulti={isMulti}
          onChange={onChange}
          defaultOptions={options}
          cacheOptions
          loadOptions={loadOptions}
          placeholder="Search Kabupaten Kota..."
          defaultValue={
            (values === "") ? ""
            : {
                  value: kabkotList?.find(
                    (data) =>
                      data.kabupaten_kota.toLowerCase() == values.toLowerCase()
                  )?.kabupaten_kota ?? "",
                  label: kabkotList?.find(
                    (data) =>
                      data.kabupaten_kota.toLowerCase() == values.toLowerCase()
                  )?.kabupaten_kota ?? "",
                }
             
          }
        />
      </>
    );
  };
  
  export default SelectorKabkot;
  