import { useQuery } from "react-query";
import { mainUrl, config } from "../../../api/api";
import axios from "axios";

const useReportLeadDetailList = ({searchState}) => 
{
    return useQuery(["reportLeadDetail", searchState], () => {
        return axios.get(
            `${mainUrl}/dashboard/report-leads/detail-quotation?start_date=${
                searchState.start
            }&end_date=${
                searchState.end
            }&company_id=${searchState.companyId}&${
                searchState.userType === "bum" || searchState.userType === "hs" || searchState.userType === "store_leader"
                ? "supervisor_id=" + searchState.userId
                : searchState.userType === "store"
                    ? "channel_id=" + searchState.userId
                    : "sales_id=" + searchState.userId
            }&type=${searchState?.status === "hot" ? "quotation" : "deal"}&perPage=100&page=${searchState.count}`,
            config
        ).then((res) => res.data)
        .catch((error) => error)
    }, {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity})
}

export default useReportLeadDetailList


