import React, { useEffect, useState } from "react";
import { mainUrl, mainUrlVTwo } from "../../../api/api";
import { connect } from "react-redux";
import Axios from "axios";
import Button from "../../../components/Button/Button";
import { useHistory } from "react-router-dom";
import LoadedComponent from "../../../components/Loaded/LoadedComponent";
import HeadFilter from "./compSeeDetails/headFilter";
import TableReport from "./compSeeDetails/table";
// Func SeeDetails
import { DataReportSeeDetails } from "./funcSeeDetails/reportSeeDetails";
import { checkUserType } from "./funcSeeDetails/checkUserType";

const SeeDetails = (
  { auth: { user }, target: { channels, usersList },prosesData: {dataFilterDate} },
  props
) => {
  // const buttonFilterDir = ["HS", "Bum", "Store", "Store Leader", "Sales"];
  
  const showButton = {
    director: ["Bum", "Hs", "Store Leader", "Sales"],
    bum: ["Store Leader", "Sales"],
    store_leader: ["Sales"],
    hs: ["Bum", "Store Leader", "Sales"],
  };

  const history = useHistory();
  const stateHistory = history.location.state;
  console.log(dataFilterDate, "check dataFilterDate di ssee detailed", stateHistory?.filterDate?.start)
  const [dataDetails, setDataDetails] = useState([]);
  const [textButton, setTextButton] = useState(undefined);
  const [filterButton, setFilterButton] = useState(false);
  const [filterBum, setFilterBum] = useState(null);
  const [filBum, setFilBum] = useState("");
  const [newFilterDate, setNewFilterDate] = useState({
    start: stateHistory?.filterDate?.start,
    end: stateHistory?.filterDate?.end,
  });
  const [searchValue, setSearchValue] = useState("");
  const [dataSearch, setDataSearch] = useState([]);
  const [isLoad, setIsLoad] = useState(true);
  const [users, setUsers] = useState([]);
  const [countMore, setCountMore] = useState({
    min: 0,
    search:false,
    max: 5,
    isLoaded: false,
  });
  const [mountUser, setMountUser] = useState(true)
  const [countRender, setCountRender] = useState(1)
  const config = {
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${localStorage.token}`,
    },
  };
  
  useEffect(() => {
    const getDataDetails = async () => {
      if (mountUser) {
        const { isUserType, valueFilterBum } = checkUserType(user, filBum, textButton);
      
        const usersAPI = `${mainUrlVTwo}/new-reports/details/users?start_date=${newFilterDate.start}&end_date=${newFilterDate.end}&user_type=${isUserType?.split(" ")?.join("_")}`;
        Axios.get(usersAPI, config)
        .then(res => {
          setMountUser(false);
          if(res.data.details === undefined){
            setUsers([])
          }
          if(res.data.details !== undefined){
            setUsers(res.data.details);
          }
          setIsLoad(false)
          setCountRender(0);
          
        })
        .catch(error => console.log(error.response, "check error response"))
      }
    };
    textButton !== undefined && getDataDetails();
  }, [textButton, filterButton, mountUser]);

  useEffect(() => {
    const getDataReport = async () => {
        let dataArr = []
        let minLoop = countMore.min
        let maxLoop = countMore.max
        const coundtIndx = minLoop === 0 ? 0 : dataDetails.length;
        for(let indx = coundtIndx; indx < maxLoop; indx++){
          if(users[indx] !== undefined){
          const resFunc = await DataReportSeeDetails(users, indx, newFilterDate, stateHistory, config);
          
          dataArr.push(resFunc)
          }
        }
        if(minLoop === 0){
          setDataDetails(dataArr)
        }else{
          setDataDetails(prev => prev.concat(dataArr))
        }
        
        setCountRender((prev) => prev + 1)
        setCountMore(prev => {
          return {
            ...prev,
            isLoaded: false,
          }
        })
        setIsLoad(false)
    }
    countRender === 0 && getDataReport()
  }, [countRender])
  // useEffect(() => {
  //   const reportData = async () => {
  //     if(countRender === 0 && countMore !== undefined && users.length !== 0){
  //       let dataArr = []
  //       let minLoop = countMore.min
  //       let maxLoop = countMore.max
  //       const coundtIndx = minLoop === 0 ? 0 : dataDetails.length 
  //       for(let indx = coundtIndx; indx < maxLoop; indx++){
  //         if(users[indx] !== undefined){
  //         const resFunc = await DataReportSeeDetails(users, indx, newFilterDate, stateHistory, config);
  //         console.log('check result dari button user type')
  //         dataArr.push(resFunc)
         
  //         }
  //       }
  //       setDataDetails(prev => prev.concat(dataArr))
  //       setCountRender(countRender + 1)
      
  //       setIsLoad(false)
  //     }
  //   }
  //   reportData()
  // }, [countRender, users, countMore])
    useEffect(() => {
      let srcArr = []
      
      if(searchValue === ""){
        srcArr = []
      }else{
        srcArr = users?.filter(user => {
          if(user.name.toUpperCase().indexOf(searchValue.toUpperCase()) >= 0){
            return user
          }
        })
      }
      setDataSearch(srcArr)
    }, [searchValue, users]);

  //   useEffect(() => {
  //     const fetchingBum = async () => {
  //       const res = await Axios.get(
  //         `${mainUrl}/new-reports/details?start_date=${newFilterDate.start}&end_date=${newFilterDate.end}&user_type=bum`,
  //         config
  //       );
  //       if (res.status === 200) {
  //         setFilterBum(res.data);
  //       }
  //     };
  //     user !== undefined && textButton.toUpperCase() === "SALES" && fetchingBum();
  //   }, [textButton, user]);

  useEffect(() => {
   
    if(user !== undefined) {
      
      const buttonRole = showButton[user?.data?.as?.toLowerCase()?.split(" ")?.join("_")];
     
      buttonRole !== undefined && setTextButton(buttonRole[0]);
    }
  }, [user]);
  
  const handleLoadMore = (e) => {
    if(e.target.textContent.toUpperCase() === "DEFAULT"){
      setSearchValue("")
      setCountRender(0);
      setIsLoad(true)
      setDataDetails([])
      setCountMore({
        min: 0,
        search:false,
        max: 5,
        isLoaded:false,
      })
    }
    if(e.target.textContent.toUpperCase() !== "DEFAULT"){
      setCountRender(0);
      setCountMore({
        min: countMore.min + 5,
        max: countMore.max + 10,
        isLoaded:true,
      })
    }
  }
  console.log(dataDetails, "Check data details yah", isLoad)
  return (
    <>
      <div className="container">
        <HeadFilter dataDetails={dataDetails} setDataDetails={setDataDetails} newFilterDate={newFilterDate} stateHistory={stateHistory} config={config} setTextButton={setTextButton} setMountUser={setMountUser} setIsLoad={setIsLoad} setSearchValue={setSearchValue} setCountMore={setCountMore} setNewFilterDate={setNewFilterDate} setFilBum={setFilBum} dataSearch={dataSearch} textButton={textButton} searchValue={searchValue} filterBum={filterBum} user={user} setFilterButton={setFilterButton} showButton={showButton} isLoad={isLoad} countMore={countMore}setCountRender={setCountRender}/>

        {dataDetails?.length !== 0 && !isLoad ? (
          <React.Fragment>
          <table
            className="data d-block"
            style={{ margin: "10px 0", overflowX: "scroll", with: "100%" }}
          >
            <TableReport dataDetails={dataDetails} newFilterDate={newFilterDate} user={user} textButton={textButton} history={history}/>
          </table>
          {
            countMore.isLoaded === false 
            ? countMore.max >= users.length
              ? null
              :(<button onClick={handleLoadMore} style={{margin:"auto",display:"flex",color:"#0d6efd",fontWeight:"bold",border:"0",background:"rgb(0,0,0,0)"}}>{countMore?.search ? "Default" : "Load More"}</button>) 
            
            :(<LoadedComponent />)
          }
          
          </React.Fragment>
        ) : searchValue !== "" && users?.length === 0 && !isLoad ?  (
          <h1>Hasil Tidak Ditemukan</h1>
        ) : (
          <LoadedComponent />
        )}

        {!isLoad && (
          <Button
            onClick={(e) => history.goBack()}
            icon=""
            title="Back"
            style={{ width: "11rem!important" }}
            btnStyle={"primary-btn"}
          />
        )}
      </div>
    </>
  );
};
const mapStateToProps = (state) => ({
  auth: state.auth,
  target: state.target,
  prosesData: state.prosesData
});
export default connect(mapStateToProps)(SeeDetails);