import { useQuery, useInfiniteQuery } from "react-query";
import axios from "axios";
import { mainUrl,config } from "./api";
const useCustomerActivitiesList = ({searchState}) => {
    return useInfiniteQuery(["customerActivities", searchState], ({pageParam = 1}) => {
        return axios.get(`${mainUrl}/customers/${searchState.customerId}/activities?page=${pageParam}`, config)
                .then((res) => res.data)
                .catch((error) => error)
    }, {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime:Infinity, getNextPageParam: (lastPage, pages) => {
        return lastPage.links?.next ? lastPage.meta?.current_page + 1 : false
    }})
}


export default useCustomerActivitiesList;


