import { mainUrl, mainUrlVTwo } from "../../../../api/api"
import axios from "axios"
import { config } from "../../../../api/api";
import { useQuery, useInfiniteQuery } from "react-query";
export const FetchUserList = async ({searchState}) => {
    return axios.get(`${mainUrlVTwo}/new-reports/details/users?start_date=${searchState.start ?? ""}&end_date=${searchState.end ?? ""}&user_type=${searchState.userType ?? "bum"}`, config)
    .then((res) => {
        return res.data.details
    })
    .catch(error => error)
}
export const useUserList = ({filterOnTouch, isPage = 1, filterName}) => {
    return useQuery(["userList", {filterOnTouch, isPage, filterName}], () => {
        return axios.get(`${mainUrlVTwo}/new-reports/details/users?start_date=${filterOnTouch?.start}&end_date=${filterOnTouch?.end}&user_type=${filterOnTouch?.userType}&channel_id=${filterOnTouch?.channelId}&page=${isPage}&name=${filterName}&per_page=15`, config)
        .then((data) => {
            return data.data
        })
        .catch((error) => error)
    }, {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity})
}

export const useUserListInt = ({filterOnTouch, isPage = 1, filterName}) => {
    return useInfiniteQuery(["userListInft", {filterOnTouch, isPage, filterName}], ({pageParam = 1}) => {
        return axios.get(`${mainUrlVTwo}/new-reports/details/users?start_date=${filterOnTouch?.start}&end_date=${filterOnTouch?.end}&user_type=${filterOnTouch?.userType}&channel_id=${filterOnTouch?.channelId}&page=${pageParam}&name=${filterName}&per_page=15`, config)
        .then((data) => {
            return data.data
        })
        .catch((error) => error)
    }, {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity, getNextPageParam:(lastPage) => {
        return lastPage?.links?.next === null ? lastPage?.meta?.current_page : lastPage?.meta?.current_page + 1
    }})
}