import React, {useEffect, useState} from 'react';
import { useHistory, useParams } from 'react-router-dom';
import { mainUrl, mainUrlVTwo } from '../../../../api/api';
import { connect } from 'react-redux';
import Axios from 'axios';
import moment from 'moment';
import Button from '../../../../components/Button/Button';
import LoadedComponent from '../../../../components/Loaded/LoadedComponent';
import Activity from '../../../../components/ActivityDetail/Activity';
import { MyFilters } from '../../../../componentsReuse';
import ActivityDetails from '../../../../components/ActivityDetail/ActivityDetails';
import { formatCurrency } from '../../../../api/format';
import XLSX from "xlsx-js-style";
const InvoiceSeeDetails = ({auth: {user}, prosesData: {dataFilterDate, idChannels, idCompany}}) => {
   
    const params = useParams()
    const history = useHistory();
    const stateHistory = history?.location?.state;
    const [valueButton, setValueButton] = useState("")
    const [isData, setIsData] = useState([]);
    const [dataSearch, setDataSearch] = useState([]);
    const [isLoading, setIsLoading] = useState(true);
    const [searchValue, setSearchValue] = useState("");
    const [invType, setInvType] = useState(history?.location?.state?.invoiceType.toLowerCase())
    const [paymentType, setPaymentType] = useState("");
    const [searchType, setSearchType] = useState("sales");
    const [filterButton, setFilterButton] = useState(false)
    const [newFilterDate, setNewFilterDate] = useState({
        start: stateHistory?.formatDate.start,
        end: stateHistory?.formatDate.end
    })
    // Activiy Detail
    const [activityDetail, setActivityDetail] = useState(false);
    const [customerActivity, setCustomerActivity] = useState([]);
    const [orderId, setOrderId] = useState(null);
    const buttonType = ["Quotation", "Settlement", "Deals", "Partial", "Down Payment", "Cancelled"];

    const loopDataExp = (dataDetails) => {
    

        let objExp = {};
        const arrExp = [];
        dataDetails.forEach((isData, indx) => {
            const isDate = new Date(isData.created_at)
            const formatDate = moment(isDate).format("YYYY-MM-DD");
          objExp["Date"] = formatDate
          objExp["Invoice Number"] = isData?.invoice_number;
          objExp["Customer"] = isData?.customer;
          objExp["Sales Name"] = isData?.sales
          objExp["Channel Name"] = isData?.channel
          objExp["Quotation"] = formatCurrency(isData.total_price, true).replace(/([A-Za-z])\w+/g, '')
    
    
          arrExp.push(objExp);
          objExp = {};
        });
        return arrExp
    }
    const textButtonInvoice = (stateHistory, invoiceType) => {
        let isInvType = invoiceType.find((type) => type.toUpperCase() === "QUOTATION").toLowerCase()
        if(stateHistory !== undefined && stateHistory !== null && stateHistory !== ""){
            if(invType === ""){
                const invoiceTypUpperCase = stateHistory?.invoiceType.toUpperCase();
                const resFindType = invoiceType.find((type) => type.toUpperCase() === invoiceTypUpperCase)
                isInvType = resFindType.toLowerCase()
            }else {
                isInvType = invType
            }
        } else {
            if(invType !== ""){
                isInvType = invType
            }
        }
        return isInvType
    }
    const stylingXlsx = ({color, worksheet, cellRef}) => {
        worksheet[cellRef].s = {
          ...worksheet[cellRef].s,
          font: {
            sz: 14
          },
          fill:{
            type: 'pattern',
            pattern: 'solid',
            fgColor: { rgb: color }
          },
          border: {
            top: {style: "thin", color: {auto: 1}},
            right: {style: "thin", color: {auto: 1}},
            bottom: {style: "thin", color: {auto: 1}},
            left: {style: "thin", color: {auto: 1}}
          }
        }
      }
    const handleExportButton = async () => {
        // const resArrDataExp = loopDataExp(isData)
        const resArrDataExp = isData.map((data, i) => {
            const isDate = new Date(data.created_at)
            const formatDate = moment(isDate).format("YYYY-MM-DD");
            return {
                "No":i + 1,
                "Date": formatDate,
                "Customer": data?.customer,
                "Sales Name": data?.sales,
                "Channel Name": data?.channel,
                "Invoice Number": data?.invoice_number,
                [invType]: formatCurrency(data.total_price, true).replace(/([A-Za-z])\w+/g, '')
            }
        });
        const wb = XLSX.utils.book_new();
        const worksheet = XLSX.utils.json_to_sheet(resArrDataExp);
        const range = XLSX.utils.decode_range(worksheet["!ref"] ?? "");
        const rowCount = range.e.r;
        const columnCount = range.e.c;
        var worksheetcols = [
          {wch:10},
          {wch:30},
          {wch:30},
          {wch:30},
          {wch:30},
          {wch:30},
          {wch:30},
        ];
      
        worksheet['!cols'] = worksheetcols;
        for (let row = 0; row <= rowCount; row++) {
            for (let col = 0; col <= columnCount; col++) {
              const cellRef = XLSX.utils.encode_cell({ r: row, c: col });
              // Add center alignment to every cell
              worksheet[cellRef].s = {
                alignment: { horizontal: "center" },
              };
              if(row === 0){
                worksheet[cellRef].s = {
                  ...worksheet[cellRef].s,
                  font: {
                    bold: true,
                    sz: 16,
                    color: {rgb: "00000"}
                  },
                  
                }
              }
              if(row !== 0){
                if(col === 0 || col === 1){
                  stylingXlsx({
                    worksheet,
                    cellRef,
                    color:"ffffffff"
                  })
                }
                if(col > 1 && col < 5){
                  stylingXlsx({
                    worksheet,
                    cellRef,
                    color:"ff4ca6c1"
                  })
                }
          
                if(col === 5 || col === 6){
                  stylingXlsx({
                    worksheet,
                    cellRef,
                    color:"ff94d244"
                  })
                }
              }
            }
          }

        XLSX.utils.book_append_sheet(wb, worksheet, `invoice-${invType}`);
        XLSX.writeFile(wb, `invoice-${invType}.xlsx`);
    };
    useEffect(() => {
        
        
        const config = {
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${localStorage.token}`,
            },
        };
        const getDataInvoice = async () => {
            
            
            const typeInvoice = valueButton === "" ? stateHistory?.invoiceType?.toLowerCase() : valueButton?.toLowerCase();
            
            const typePayment = typeInvoice === "deals" || typeInvoice === "down_payment" || typeInvoice === "partial" || typeInvoice === "cancelled" ? typeInvoice : "";
            const defaultFilterDateStart = typeInvoice === "quotation" ? newFilterDate.start === "" ? "2020-01-01" : newFilterDate.start : newFilterDate.start;
            const defaultFilterDateEnd = typeInvoice === "quotation" ? newFilterDate.end === "" ? moment(new Date()).format("YYYY-MM-DD") : newFilterDate.end : newFilterDate.end;
            Axios.get(`${mainUrlVTwo}/new-reports/invoice?id=${stateHistory?.data?.id}&user_type=${stateHistory?.typeUser}&start_date=${defaultFilterDateStart}&end_date=${defaultFilterDateEnd}&invoice_type=${typeInvoice === "partial" || typeInvoice === "down_payment" ? "deals" : typeInvoice}&payment_type=${typeInvoice === "settlement" ? "settlement" : typePayment}&search_type=${searchType}`, config)
            .then(data => {
                
                setIsLoading(false)
                setIsData(data.data.data);
            })
            .catch(error => console.log(error.response))
        } 
        
        isLoading && getDataInvoice()
    }, [invType, paymentType, searchType, filterButton, isLoading]);

    useEffect(() => {
        if(isData?.length === 0){
            setDataSearch(isData)
        }
        const filterDataSearch = () => {
            let newRes = isData?.filter((datas,i) => {
                if(datas[searchType]?.toUpperCase().indexOf(searchValue.toUpperCase()) >= 0){
                    return datas
                }
            })
            setDataSearch(newRes)
        }
        !isLoading && isData.length !== 0 && filterDataSearch()
    }, [searchValue, isData, isLoading])
    const handleChangeSearch = (e) => {
        
        setSearchValue(e.target.value)
    }
    const handleClickEvent = (e) => {
        setIsLoading(true)
        setValueButton(e.target.textContent.split(" ").join("_").toLowerCase());
        const isTextContent= e.target.textContent.split(" ").join("_").toLowerCase();
        if(isTextContent === "partial" || isTextContent === "down_payment" || isTextContent === "cancelled"){
            setPaymentType(isTextContent)
        }else {
            setInvType(isTextContent)
            setPaymentType("")
        }
        
    }
    const handleEventChange = (e) => {
        setIsLoading(true)
        setSearchType(e.target.value);
    }
    const handleClickActivity = async (event, data) => {
        const config = {
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${localStorage.token}`,
            },
        };
        Axios.get(`${mainUrl}/activities?filter[id]=${data.activity_id}`, config)
            .then(data => {
                setCustomerActivity(data.data.data);
                setActivityDetail(!activityDetail);
                setOrderId(data.data.data[0].order.id);
            })
            .catch(error => console.log(error.response))
    }  
   
    return (
        <>
            <div className='container'>
                <div className='filter'>
                    <div class="col-auto d-flex" style={{gap:"20px", display:"flex", flexDirection:"column"}}>
                        <div style={{display:"flex"}}>
                            <input type="text" id="search-table" class="form-control" onChange={handleChangeSearch} style={{width:"30%"}} placeholder='Search' value={searchValue} />
                            <select
                                style={{width:"15rem",marginLeft:"20px", marginRight:"20px"}}
                                className="form-select"
                                name="search-type"
                                value={searchType}
                                onChange={handleEventChange}
                                >
                                <option value="customer">Customer</option>
                                <option value="sales">Sales</option>
                                <option value="invoice_number">Invoice Number</option>
                                <option value="channel">Channel</option>
                            </select>
                            
                            <MyFilters setNewFilterDate={setNewFilterDate} showSearch={false} showSelect={false} setIsLoading={setIsLoading} setFilterButton={setFilterButton}/>
                        </div>
                        <div className='btn-filter d-flex justify-content-around' style={{padding: "10px 0", flexWrap:"wrap"}}>
                            {
                                buttonType.map((data, i) => {
                                    return(
                                        <div onClick={handleClickEvent} style={{ position:"relative", cursor: "pointer", margin: "20px", display: stateHistory?.invoiceType === 'retail' ? "none" : "block"}} key={i}>
                                            <span style={{color: "black", fontWeight:"bold"}}>{data}</span>
                                            <div style={{position: "absolute", bottom: "-10px", width: "100%", height: "4px", backgroundColor: "#17949d", display: paymentType === "" && data.toUpperCase() === invType.toUpperCase() ? "block" : data.split(" ").join("_").toLowerCase() === paymentType ? "block" : "none"}}></div>
                                        </div>
                                    )
                                })
                            }
                        </div>
                        <div>
                            <button style={{border:"0", outline:"0", padding:"10px 20px", borderRadius:"5px", background:"#17949d", color:"white"}} onClick={handleExportButton}>Export</button>
                        </div>
                    </div>
                </div>
                {dataSearch.length !== 0 && !isLoading ? (<table className="data" style={{ margin: "10px 0", overflowX: "scroll", width:"100%" }}>
                        <thead>
                            <tr>
                                <th>Date</th>
                                <th>Invoice Number</th>
                                <th>Customer</th>
                                <th>Sales Name</th>
                                <th>Channel Name</th>
                                <th>Quotation<br/><span style={{fontSize:"10px", color:"white", background: "rgb(0,0,0,0)"}}>* Tidak termasuk PPN</span></th>
                                <th>Action</th>
                            </tr>
                        </thead>
                        <tbody>
                            {dataSearch.map((data, i) => {
                                const isDate = new Date(data.created_at)
                                const formatDate = moment(isDate).format("YYYY-MM-DD");
                            return (
                                <tr key={i}>
                                    <td>{formatDate}</td>
                                    <td>{data.invoice_number}</td>
                                    <td>
                                        {data.customer}
                                    </td> 
                                    <td>{data.sales}</td>
                                    <td>{data.channel}</td>
                                    <td>
                                        {formatCurrency(data.total_price, true).replace(/([A-Za-z])\w+/g, '')}
                                    </td>
                                    <td>
                                        <div
                                        onClick={(e) => handleClickActivity(e,data)}
                                        className="activity-detail-btn"
                                        >
                                        <img
                                            src="/Asset/Action Icon/eye.png"
                                            style={{ marginRight: "5px" }}
                                            alt="eye"
                                        />
                                        See Detail
                                        </div>
                                    </td>
                                </tr>
                            );
                            })}
                        </tbody>
                </table>) : dataSearch.length === 0 && !isLoading ? (<h4 style={{textAlign:"center"}}>Hasil Tidak Ditemukan</h4>) : <LoadedComponent />}
                {!isLoading && <Button onClick={(e) => history.push(`${user?.data?.as.toUpperCase() === "SALES" ? "/dashboard" : history.goBack()}`)}icon="" title="Back" style={{width:"11rem!important", marginTop:"30px"}} btnStyle={"primary-btn"} />}
                {customerActivity.length !== 0 && <Activity
                    activityDetail={activityDetail}
                    setActivityDetail={setActivityDetail}
                    customerActivity={customerActivity[0]}
                    orderId={orderId}
                />}
            </div>
        </>
    )
}
const mapStateToProps = (state) => ({
    auth: state.auth,
    prosesData: state.prosesData
})
export default connect(mapStateToProps)(InvoiceSeeDetails);