import axios from "axios";
import React, { useEffect, useState } from "react";
import { Link } from "react-router-dom";
import { useParams } from "react-router-dom";
import { mainUrl } from "../../../api/api";
import Header from "../../../components/Header/Header";
import Loaded from "../../../components/Loaded/Loaded";
import { formatCurrency } from "../../../api/format";
const ProductByBrand = () => {
  const { brand_name, brand_id } = useParams();
  const [models, setModels] = useState(null);
  const [perPage, setPerPage] = useState(12);
  const [search, setSearch] = useState("");
  const [dataSearch, setDataSearch] = useState([]);
  const [allModels, setAllModels] = useState([]);
  const [isLoad, setIsLoad] = useState(true)
  const config = {
    headers: {
      "Content-Type": "application/json",
      Authorization: `Bearer ${localStorage.token}`,
    },
  };
  useEffect(() => {
    
    const getModels = async () => {
      try {
        const res = await axios.get(
          `${mainUrl}/models?filter[product_brand_id]=${brand_id}&perPage=${perPage}`,
          config
        );
        setModels(res.data.data);
      } catch (error) {
        console.error(error);
      }
    };
    getModels();
  }, [perPage, brand_id]);
  useEffect(() => {
    const getAllModels = () => {
      axios.get(
        `${mainUrl}/models?filter[product_brand_id]=${brand_id}&perPage=${100}`,
        config
      )
      .then(res => {
        setIsLoad(false)
        setAllModels(res.data.data)
      })
      .catch(error => console.log(error.response, "error"))
    }
    isLoad && getAllModels()

    const runFilter = async () => {
    let resFilter = await allModels.filter(data => {
        let indexOfData = data.name.toUpperCase().indexOf(search.toUpperCase());
        if(indexOfData >= 0){
          return data
        }
      })
      setDataSearch(resFilter)
    }
    search !== "" && runFilter()
  }, [brand_id, isLoad, search])
  const handleEventSearch = (e) => {
    setSearch(e.target.value);
  }
  return models ? (
    <div className="product-by-brand" id="product-by-brand">
      <Header title={brand_name} back={true} />
      <input
          className="form-control me-3"
          type="text"
          placeholder="Search Product"
          aria-label="default input example"
          value={search}
          style={{ marginBottom: "20px" }}
          onChange={handleEventSearch}
        ></input>

        {search !== "" 
        ?(<div className="row">
          {
            dataSearch.length !== 0 ? dataSearch.map(isData => {
              return (
                <div className="col-md-2 product-card">
                  <Link to={`/dashboard/product/product_detail/${isData.id}`}>
                    <img
                      src={isData.images[0].url}
                      alt="product"
                      style={{ width: "100%", borderRadius: "8px" }}
                    />
                    <h3>{isData.name}</h3>
                    <p>{
                    isData.price_min ? formatCurrency(isData?.price_min, true) : ""
                    } / {
                      isData.price_max ? formatCurrency(isData?.price_max, true) : ""
                    }</p>
                    
                  </Link>
              </div>
              )
            })
            :<h4>Hasil Tidak Ditemukan</h4>
          }
        </div>)
      :(<div className="row">
        {models.map((model) => {
          return (
            <div className="col-md-2 product-card">
              <Link to={`/dashboard/product/product_detail/${model.id}`}>
                <img
                  src={model.images[0].url}
                  alt="product"
                  style={{ width: "100%", borderRadius: "8px" }}
                />
                <h3>{model.name}</h3>
                {/* <p>Rp 1.000.000 s/d Rp 2.000.000</p> */}
                <p>{
                  model.price_min ? formatCurrency(model?.price_min, true) : ""
                } / {
                  model.price_max ? formatCurrency(model?.price_max, true) : ""
                }</p>
              </Link>
            </div>
          );
        })}
        {models.length >= perPage && (
          <div>
            <div
              onClick={() => setPerPage(perPage + 12)}
              style={{ cursor: "pointer", color: "blue" }}
            >
              More...
            </div>
          </div>
        )}
      </div>)}
    </div>
  ) : (
    <Loaded />
  );
};

export default ProductByBrand;
