
import { getDataReport } from '../../../../api/reportApi';
export const DataReportSeeDetails = async (users, indx, newFilterDate, stateHistory, config) => {
    const ttlReport = ["deals","active_leads","estimations","new_leads","quotations","total_leads","lead_status",
            ];
            
    const resultReport = await Promise.all(ttlReport.map(async (d) => {
        let res = await getDataReport(
            d.split("_").join("-"),
            stateHistory?.idCompany,
            "",
            users[indx].id,
            newFilterDate.start,
            newFilterDate.end,
            config
        );
        return res
    }));
            
    const resReduce = resultReport.reduce((acc,cur) => {        
        Object.keys(cur).forEach((dsx,idx) => {
            if(dsx === "follow_up"){
                Object.keys(cur[dsx]).forEach((dfx,ifx) => {
                    acc[dsx][dfx] = cur[dsx][dfx]
                })
            }else{
                acc[dsx] = cur[dsx]
            }
        })
        return acc;     
    }, {follow_up:{},name:users[indx].name,id:users[indx].id});
    console.log(resReduce, "check res reduce")
    return resReduce;
           
}