import React, {useCallback, useMemo} from 'react';

import AsyncSelect from 'react-select/async';
import provinsiList from "../../api/data_provinsi.json";

const SelectorProvinsi = ({
    values,
    onChange,
    isMulti = false,
  }) => {
    const loadOptions = (search, callback) => {
         setTimeout(() => {
            const filterdData = provinsiList.filter((i) =>
                i.provinsi.toLowerCase().includes(search.toLowerCase())
              ).map((i) => ({value: i.provinsi, label:i.provinsi}))
              return callback(filterdData.slice(0, 10))
        }, 500)
      }
 
    const options = provinsiList?.map((data) => ({
      value: data.provinsi,
      label: data.provinsi,
    })).slice(0,100);
 
    return (
      <>
        <AsyncSelect
          isMulti={isMulti}
          onChange={onChange}
          defaultOptions={options}
          cacheOptions
          loadOptions={loadOptions}
          placeholder="Search Provinsi..."
          defaultValue={
            (values === "" || values?.length === 0) ? ""
            : {
                  value: provinsiList?.find(
                    (data) =>
                      data.provinsi.toLowerCase() == values.toLowerCase()
                  )?.provinsi ?? "",
                  label: provinsiList?.find(
                    (data) =>
                      data.provinsi.toLowerCase() == values.toLowerCase()
                  )?.provinsi ?? "",
                }
             
          }
        />
      </>
    );
  };
  
  export default SelectorProvinsi;
  