import React, { useState, useEffect } from 'react';
import Axios from 'axios';
import { connect } from 'react-redux';
import { mainUrl } from '../../../../../api/api';
import { useHistory } from 'react-router-dom';
import Button from '../../../../../components/Button/Button';
import LoadedComponent from '../../../../../components/Loaded/LoadedComponent';
import moment from 'moment';
import { formatCurrency } from '../../../../../api/format';
const DetailInterior = ({auth: user}) => {
    const [isData, setIsData] = useState([])
    const [isLoading, setIsLoading] = useState(true);
    const [isError, setIsError] = useState(null);
    const [filterButton, setFilterButton] = useState(false)
    const history = useHistory();
    const stateHistory = history?.location?.state;
    const [newFilterDate, setNewFilterDate] = useState({
        start:stateHistory?.formatDate?.start,
        end:stateHistory?.formatDate?.end
    });
    const config = {
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${localStorage.token}`,
        },
    };
    useEffect(() => {
        const stateHistory = history?.location?.state;
        if(stateHistory === undefined || stateHistory === "" || stateHistory === null){
            return history('/dashboard')
        }
        const getDataDetailInterior = () => {
            Axios.get(`${mainUrl}/new-reports/interior-designs/details?user_type=${stateHistory?.userType}&start_date=${newFilterDate.start}&end_date=${newFilterDate.end}&interior_design_id=${stateHistory?.data.id}`, config)
            .then(res => {
                if(res.status === 200){
                    setIsLoading(false);
                    setFilterButton(false);
                    return setIsData(res.data);
                }
            }).catch(error => setIsError(error.response))
        }

        getDataDetailInterior()
    }, [filterButton, history]);
    const handleChangeDate = (e) => {
        setNewFilterDate(prev => {
            return{
              ...prev,
              [e.target.name]: e.target.value
            }
        })
    }
    return (
        <>
             <div className='container'>
                <div className='filter d-flex' style={{gap:"20px"}}>
                    {/* <div className="col-auto" style={{gap:"20px"}}>
                        <div >
                            <input type="text" id="search-table" className="form-control" onChange={handleChangeSearch}  placeholder='Search' value={searchValue} />
                        </div>
                    </div> */}
                    <div style={{display: "flex", alignItems: "center"}}>
                        <input
                            type="date"
                            id="start"
                            name="start"
                            className="form-control"
                            placeholder="Start Month"
                            onChange={handleChangeDate}
                        />
                        <div className="input-group-addon"style={{margin: "0 10px"}}>to</div>
                        <input
                            type="date"
                            id="end"
                            name="end"
                            className="form-control"
                            placeholder="End Month"
                            onChange={handleChangeDate}
                            style={{margin:"0"}}
                        />
                    </div>
                    <Button onClick={(e) => {
                        setFilterButton(true);
                        setIsLoading(true);
                    }}icon="" title="Filter" style={{width:"11rem!important", marginTop:"30px"}} btnStyle={"primary-btn"} />
                </div>

                {isData.length !== 0 && !isLoading ? (<table className="data" style={{ margin: "10px 0", overflowX: "scroll", width:"100%" }}>
                        <thead>
                            <tr>
                                <th>No Invoice</th>
                                <th>Tanggal</th>
                                <th>Harga</th>
                                <th>Nama Channel</th>
                                <th>Nama</th>
                            </tr>
                        </thead>
                        <tbody>
                            {isData.map((data, i) => {
                                const getDate = new Date(data.created_at);
                                const isResDate = moment(getDate).format("YYYY-MM-DD")
                            return (
                                <tr key={i}>
                                    <td>{data.invoice_number}</td>
                                    <td>{isResDate}</td>
                                    <td>{formatCurrency(data.total_price, true).replace(/([A-Za-z])\w+/g, '')}</td>
                                    <td>{data.channel}</td>
                                    <td>{data.sales}</td>
                                </tr>
                            );
                            })}
                        </tbody>
                </table>) : isLoading ? <LoadedComponent /> : isData.length === 0 && (<h4>Hasil Tidak Ditemukan</h4>)  
                }
                {!isLoading && <Button onClick={(e) => history.goBack()}icon="" title="Back" style={{width:"11rem!important", marginTop:"30px"}} btnStyle={"primary-btn"} />}
            </div>
        </>
    )
}
const mapStateToProps = (state) => ({
    auth: state.auth,
    prosesData: state.prosesData
})
export default connect(mapStateToProps)(DetailInterior)