import { mainUrl } from "../../../../api/api"
import Axios from "axios"
import { config } from "../../../../api/api";
import { useQuery } from "react-query";

// searchState
export const useStocksList = ({idProduct}) => {


    return useQuery([`stockslist`, {idProduct}], () => {
        return Axios.get(`${mainUrl}/locations/product/${idProduct}`, config)
        .then((res) => {
            return res.data
            }).catch((error) => error)
    }, {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity})
    
   
}