import React from "react"
import { useStocksList } from "./apiProduct/useStocks"
import axios from "axios"
import { mainUrl, config } from "../../../api/api"
const Stocks = ({idProduct}) => {
    const {data, isLoading, error} = useStocksList({idProduct});
    
    const addCart = async (d) => {
    
        const data = {
            items: [
                {
                    id: idProduct,
                    quantity: d.total_stock,
                    sku: d.sku
                }
            ]
        }
        try {
          const res = await axios.put(`${mainUrl}/carts`, data, config);
        } catch (error) {
            console.log(error, "checking error yah")
        }
      };
    if(isLoading){
        return <h4>Sedang memuat...</h4>
    }
    return (
        <>
        <h3>Stocks</h3>
        <div style={{display:"grid", gridTemplateColumns:"1fr 1fr 1fr 1fr", gap:"10px"}}>
            {
                data?.data?.length === 0 ? <h5 >Stock tidak ada.</h5> :data?.data?.map((d,i ) => (
                    <div style={{background:"white", borderRadius:"10px"}} >
                        <div class="card-body">
                            <span class="card-subtitle mb-2 text-body-secondary" style={{color:"rgb(0,0,0,0.3)"}}>SKU: {d.sku ?? "-"}</span>
                            <h5 class="card-title">{d?.name ?? "-"}</h5>
                            
                            <p class="card-text">{d?.description ?? "-"}</p>
                            <div style={{borderTop:"1px solid black", borderBottom:"1px solid black", padding:"20px 10px"}}>
                                <h6 style={{color:"red"}}>QUANTITY ON SALES ORDER: {d.SO}</h6>
                                <h6 style={{color:"#17949d"}}>AVAILABLE STOCK: {d.total_stock - d.SO}</h6>
                            </div>
                            {
                                d.stocks?.map((stock, i) => (
                                  <div key={i} style={{display:"flex", flexDirection:"column", marginTop:"20px"}}>
                                    <span>Name: {stock?.name ?? "-"}</span>
                                    <span>Orlan Id: {stock?.orlan_id ?? "-"}</span>
                                    <span>Stock: {stock?.stock ?? "-"}</span>
                                  </div>
                                ))
                              }
                            <button style={{border:"0", outline:"0", padding:"10px 20px", borderRadius:"5px", background:"#17949d", color:"white", width:"100%", marginTop:"20px"}} onClick={() => addCart(d)}>+Cart</button>
                        </div>
                        
                    </div>
                ))
            }
        </div>
        </>
    )
}

export default Stocks