import axios from "axios";
import React, { useContext, useEffect, useState } from "react";
import { connect, useDispatch } from "react-redux";
import { mainUrl, config } from "../../api/api";
import { formatCurrency } from "../../api/format";
import { loadCarts } from "../../redux/action/product";
import NotificationContext from "../../store/notification-context";
import Button from "../Button/Button";
import "./SearchProductUnit.scss";
import Popup from "../Popup/Popup";
const SearchProductUnit = ({ product: { carts }, search }) => {
  const [productUnits, setProductUnits] = useState(null);
  const [comparationPopup, setComparationPopup] = useState(false);
  const [dataStock, setDataStock] = useState(null)
  const notificationCtx = useContext(NotificationContext);
  const dispatch = useDispatch();
 
  useEffect(() => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };

    const getProductUnits = async () => {
      try {
        const res = await axios.get(
          `${mainUrl}/product-units?filter[name]=${search}&perPage=12`,
          config
        );
        setProductUnits(res.data.data);
      } catch (error) {
        console.error(error);
      }
    };
    getProductUnits();
  }, [search]);

  const addCart = async (newCartId, sku) => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
    notificationCtx.showNotification({
      title: "Adding Cart...",
      message: "Add Cart.",
      status: "pending",
    });

    const dataCart = {
      id: newCartId,
      quantity: 1,
      sku: sku,
    };
    const items = [...carts.data.items, dataCart];
    const data = { items: items };

    try {
      await axios.put(`${mainUrl}/carts`, data, config);
      // console.log(res.data.data);
      dispatch(loadCarts());
      notificationCtx.showNotification({
        title: "Success!",
        message: "Successfully Add Product to Cart!",
        status: "success",
      });
    } catch (error) {
      console.error(error);
      notificationCtx.showNotification({
        title: "Error!",
        message: error.message || "Something went wrong!",
        status: "error",
      });
    }
  };
  const handleStockEvent = (idProduct) => {
    axios.get(`${mainUrl}/locations/product/${idProduct}`, config)
        .then((res) => {
          setDataStock(res.data)
          setComparationPopup(true)
            return res.data
        }).catch((error) => error)
  }
  return (
    <div className="row mt-4" id="search-product-unit">
      {dataStock && <Popup popup={comparationPopup} setPopup={setComparationPopup} noCard={true}>
      <div style={{display:"grid", gridTemplateColumns:"1fr 1fr 1fr 1fr", gap:"10px", width:"80%", margin:"auto"}}>
            {
                dataStock?.data?.length === 0 ? <h5 >Stock tidak ada.</h5> :dataStock?.data?.map((d,i ) => {
                  return (
                    <div style={{background:"white", borderRadius:"10px"}} >
                        <div class="card-body">
                            <span class="card-subtitle mb-2 text-body-secondary" style={{color:"rgb(0,0,0,0.3)"}}>SKU: {d.sku ?? "-"}</span>
                            <h5 class="card-title">{d?.name ?? "-"}</h5>
                            
                            <p class="card-text">{d?.description ?? "-"}</p>
                            <div style={{borderTop:"1px solid black", borderBottom:"1px solid black", padding:"20px 10px"}}>
                                <h6 style={{color:"red"}}>QUANTITY ON SALES ORDER: {d.SO}</h6>
                                <h6 style={{color:"#17949d"}}>AVAILABLE STOCK: {d.total_stock - d.SO}</h6>
                            </div>
                            <div>
                              {
                                d.stocks?.map((stock, i) => (
                                  <div key={i} style={{display:"flex", flexDirection:"column", marginTop:"20px"}}>
                                    <span>Name: {stock?.name ?? "-"}</span>
                                    <span>Orlan Id: {stock?.orlan_id ?? "-"}</span>
                                    <span>Stock: {stock?.stock ?? "-"}</span>
                                  </div>
                                ))
                              }
                            </div>
                            <button style={{border:"0", outline:"0", padding:"10px 20px", borderRadius:"5px", background:"#17949d", color:"white", width:"100%", marginTop:"20px"}} onClick={() => addCart(d.id, d.sku)}>+Cart</button>
                        </div>
                        
                    </div>
                )})
            }
        </div>
      </Popup>}
      <h3>Product by Product Unit</h3>
      {productUnits ? (
        productUnits.map((productUnit, idx) => {
          return (
            <div className="col-md-4 product-card" key={idx}>
              <div className="product-item d-flex justify-content-between p-3 mb-2 align-items-center">
                <div>
                  <h3>{productUnit.name}</h3>
                  <p>{formatCurrency(productUnit.price)}</p>
                </div>
                <div>
                <div onClick={() => addCart(productUnit.id, productUnit.sku)}>
                  <Button
                    title={`+ Cart`}
                    icon=""
                    btnStyle="primary-btn"
                  ></Button>
                  
                </div>
                <div style={{margin:"5px 0"}}/>
                <div onClick={() => handleStockEvent(productUnit.product_id ?? 0)}>
                  <Button
                    title={"Stock"}
                    icon=""
                    btnStyle="primary-btn"
                  ></Button>
                  
                </div>
                </div>
              </div>
            </div>
          );
        })
      ) : (
        <h3>Product is not found</h3>
      )}
    </div>
  );
};

const mapStateToProps = (state) => ({
  product: state.product,
});

export default connect(mapStateToProps)(SearchProductUnit);
