import React, { useState, useEffect } from "react";
import { connect, useDispatch } from "react-redux";
import Button from "../../../components/Button/Button";
import Header from "../../../components/Header/Header";
import Loaded from "../../../components/Loaded/Loaded";
import ComporationPopUp from "../../../components/Popup/Popup Component/ComporationPopUp";
import Popup from "../../../components/Popup/Popup";
import { loadActivities } from "../../../redux/action/target";
import "./Dashboard.scss";
import Report from "./Report";
import TopPerformance from "./TopPerformance";
import DownloadReport from "../../../components/Popup/Popup Components/DownloadReport/DownloadReport";
import LoadedComponent from "../../../components/Loaded/LoadedComponent";
import { useHistory } from "react-router-dom";
import DashboardReport from "./DashboardReport";
export const config = {
  headers: {
    "Content-Type": "application/json",
    Authorization: `Bearer ${localStorage.token}`,
  },
};
const Dashboard = ({
  auth: { user, loading },
  prosesData: { dataNewReports, dataFilterDate, idCompany },
}) => {
  const history = useHistory();
  const [comparationPopup, setComparationPopup] = useState(false);
  const [downloadReportPopup, setDownloadReportPopup] = useState(false);
  const [valueClick, setValueClick] = useState("");
  const [hideButton, setHideButton] = useState(true);
 
  useEffect(() => {
    localStorage.setItem("user_id_log", user?.data?.id);
    localStorage.setItem("user_type_log", user?.data?.as);
    localStorage.setItem("data_user_log_new", JSON.stringify(user?.data));
  }, [user])
  const buttonRole = {
    hs: ["Comparasion","See Detail" ,"Brand"],
    director: ["Comparasion", "See Detail", "Brand"],
    bum: ["Comparasion", "See Detail", "Brand"],
    sales: ["Comparasion"],
    store_leader:["Comparasion", "See Detail"],
    allButton: ["Comparasion", "See Detail", "Brand"],
  };
  const dispatch = useDispatch();
  useEffect(() => {
    dispatch(loadActivities());
  }, [dispatch]);
  
  const handleGoToSeeDetails = () => {
    history.push({
      pathname: `/dashboard/dashboard-see-detail/${user?.data?.id}/${user?.data?.as?.toLowerCase()}`,
      state: { filterDate: dataFilterDate, idCompany: idCompany },
    });
  };

  return !loading && user ? (
    <div>
      <Header
        title={"Dashboard"}
        back={false}
        notif={true}
        user={true}
        data={user.data}
      />

      {comparationPopup ? <Popup popup={comparationPopup} setPopup={setComparationPopup}>
        {valueClick.toUpperCase() === buttonRole.allButton[0].toUpperCase() ? (
          <ComporationPopUp
            isData={dataNewReports.data}
            isType={buttonRole.allButton[0]}
          />
        ) : valueClick.toUpperCase() ===
          buttonRole.allButton[1].toUpperCase() ? (
          handleGoToSeeDetails()
        ) : (
          valueClick.toLocaleUpperCase() ===
            buttonRole.allButton[2].toUpperCase() && (
            <ComporationPopUp
              isData={dataNewReports.data}
              isType={buttonRole.allButton[2]}
              isUser={user}
            />
          )
        )}
      </Popup> : null}
      <Popup popup={downloadReportPopup} setPopup={setDownloadReportPopup}>
        <DownloadReport />
      </Popup>
      <DashboardReport
        valueClick={valueClick}
        buttonRole={buttonRole.allButton}
        setHideButton={setHideButton}
        config={config}
      /> 
      <div onClick={() => setComparationPopup(!comparationPopup)}>
        <div
          style={{
            display: hideButton ? "none" : "flex",
            margin: "15px 0",
            justifyContent:
              buttonRole[user?.data?.as?.toLowerCase()?.split(" ")?.join("_")].length <= 1
                ? "start"
                : "space-around",
          }}
        >
          {buttonRole[user?.data?.as?.toLowerCase()?.split(" ")?.join("_")].map((data) => {
            return (
              <Button
                onClick={(e) => setValueClick(e.target.textContent)}
                icon=""
                title={data}
                style={{ width: "11rem!important" }}
                btnStyle={"primary-btn"}
              />
            );
          })}
        </div>
      </div>
      <TopPerformance userData={user} />
    </div>
  ) : (
    <Loaded />
  );
};
const mapStateToProps = (state) => ({
  auth: state.auth,
  prosesData: state.prosesData,
});

export default connect(mapStateToProps)(Dashboard);
