import axios from "axios";
import moment from "moment";
import { useQuery } from "react-query";
import React, { useEffect, useState, useMemo } from "react";
import { connect, useDispatch } from "react-redux";
// import { Link } from "react-router-dom";
import { mainUrl, mainUrlVTwo } from "../../../api/api";
import Bar from "../../../components/Chart/Bar";
import LoadedComponent from "../../../components/Loaded/LoadedComponent";
// import ReportCard from "../../../components/Report Card/ReportCard";
import NewReportCard from "../../../components/Report Card/newReportCard";
import { loadChannels, loadUsersList } from "../../../redux/action/target";
import Skill from "./Skill";
import IsBar from "./IsBar";
import { useHistory } from "react-router-dom";
import Filters from "../../../components/Report/Filters";
import {  dataNewReports, dataSeeDetails, isFilterDate,filterIdCrud, isChannelId  } from "../../../redux/action/idUser";
import CurrencyFormat from 'react-currency-format';
import { formatCurrency } from "../../../api/format";
import ComporationPopUp from "../../../components/Popup/Popup Component/ComporationPopUp";
import Popup from "../../../components/Popup/Popup";
import { useReportList } from "./APIReport/useReportList";
import { config } from "../../../api/api";
// import { getDataReport } from "../../../api/reportApi";
// import * as XLSX from 'xlsx';
// Uninstall

const Report = ({ auth: { user, loading }, target: { channels, usersList }, prosesData: {dataFilterDate, idChannels, idCompany}, buttonRole, valueClick, setHideButton }, props) => {
  
  
  const history = useHistory()
  const dispatch = useDispatch();
  const userData = props.userData;
  console.log(userData, "check dashboard")
  const followUpActivities = ["HOT", "WARM", "COLD"]
  let today = new Date()
  let currentMonth = ("0" + (today.getMonth() + 1)).slice(-2);
  const [newFilterDate, setNewFilterDate] = useState({
    start:"",
    end:""
  });
  const [comparationPopup, setComparationPopup] = useState(false);
  const [filterCompany, setFilterCompany] = useState(user.data.company_id);
  const [filterChannels, setFilterChannels] = useState("");
  const [filterUser, setFilterUser] = useState();
  // const [newReports, setNewReports] = useState(null);
  const [countError, setCountError] = useState(0)
  const [isLoading, setIsLoading] = useState(true);
  const [filterButton, setFilterButton] = useState(false);
  const [isParams, setParams] = useState({
      end:newFilterDate.end ?? "",
      start:newFilterDate?.start ?? "",
      userId:user?.data?.id,
      channelId: filterChannels ?? "",
      userType: "",
      companyId: filterCompany ?? ""
  })

  

  useEffect(() => {
    setParams((prev) => {
      return {
        ...prev,
        userId: user?.data?.id
      }
    })
  }, [user])
  useEffect(() => {
    
    if(filterButton){
      filterChannels !== "" && localStorage.setItem("channel_dashboard", filterChannels);
        setParams((prev) => {
        return {
          ...prev,
          end:newFilterDate.end ?? "",
        start:newFilterDate?.start ?? "",
        channelId: filterChannels ?? "",
        companyId: filterCompany ?? ""
        }
      })
      setFilterButton(false)
    }
    
  }, [
    newFilterDate,
    filterChannels,
    filterCompany,
    filterButton
  ])


    useEffect(() => {
      console.log(filterChannels, "checking filter channles")
      localStorage.removeItem("channel_dashboard");
      user && localStorage.setItem("company_id", user?.data?.company?.id);
    dispatch(isFilterDate(newFilterDate));
    dispatch(isChannelId(filterChannels))
    dispatch(filterIdCrud(filterCompany));
    dispatch(loadChannels(filterCompany));
      if (userData) {
        dispatch(
          loadUsersList(
            filterChannels,
            userData.data.supervisor_id,
            userData.data.company.id
          )
        );
      } else {
        dispatch(loadUsersList());
      }
    }, [dispatch, userData,newFilterDate,filterCompany, user, filterChannels])
    
    useEffect(() => {
      const getSeeDetails = async () => {
        try{
          const res = await axios.get(`${mainUrlVTwo}/new-reports/details?user_type=store_leader`);
          dispatch(dataSeeDetails(res))
        }catch(error){  
          console.log(error.response, "check error")
        }
      } 

      valueClick.toUpperCase() === buttonRole[1] && getSeeDetails()
    }, [buttonRole, valueClick, dispatch]);

  const pickColor = (value) => {
    if (value === "HOT") {
      return "#E53935";
    } else if (value === "WARM") {
      return "#FFD13D";
    } else if (value === "COLD") {
      return "#0553B7";
    } else if (value === "CLOSE") {
      return "#313132";
    }
  };
  // const reportDeals = await Axios.get(`${mainUrl}/new-reports/sub/deals?company_id=${params?.companyId ?? ""}&channel_id=${params?.channelId ?? ""}&user_id=${params?.userId}&start_date=${params?.start ?? ""}&end_date=${endDateQuotation}&user_type=${params?.userType ?? ""}`, config).then((res) => res.data).catch((error) => error)
    
    const reportDeals = async (params) => {
    
        return await axios.get(`${mainUrlVTwo}/new-reports/sub/deals?company_id=${params?.companyId ?? ""}&channel_id=${params?.channelId ?? ""}&user_id=${params?.userId}&start_date=${params?.start ?? ""}&end_date=${params.end ?? ""}&user_type=${params?.userType ?? ""}`, config).then((res) => res.data).catch((error) => error)
    }
    const reportActiveLeads = async (params) => {
      
        return await axios.get(`${mainUrlVTwo}/new-reports/sub/active-leads?company_id=${params?.companyId ?? ""}&channel_id=${params?.channelId ?? ""}&user_id=${params?.userId}&start_date=${params?.start ?? ""}&end_date=${params?.end ?? ""}&user_type=${params?.userType ?? ""}`, config).then((res) => res.data).catch((error) => error)
    }
    const reportEstimations = async (params) => {
      const endDateQuotation = params?.end === "" ? moment(new Date()).format("YYYY-MM-DD") : params.end
        return await axios.get(`${mainUrlVTwo}/new-reports/sub/estimations?company_id=${params?.companyId ?? ""}&channel_id=${params?.channelId ?? ""}&user_id=${params?.userId}&start_date=${params?.start ?? ""}&end_date=${endDateQuotation}&user_type=${params?.userType ?? ""}`, config).then((res) => res.data).catch((error) => error)
    }
    const reportNewLeads = async (params) => {
      
        return await axios.get(`${mainUrlVTwo}/new-reports/sub/new-leads?company_id=${params?.companyId ?? ""}&channel_id=${params?.channelId ?? ""}&user_id=${params?.userId}&start_date=${params?.start ?? ""}&end_date=${params?.end ?? ""}&user_type=${params?.userType ?? ""}`, config).then((res) => res.data).catch((error) => error)
    }
    const reportQuotations = async (params) => {
      const endDateQuotation = params?.end === "" ? moment(new Date()).format("YYYY-MM-DD") : params.end
        return await axios.get(`${mainUrlVTwo}/new-reports/sub/quotations?company_id=${params?.companyId ?? ""}&channel_id=${params?.channelId ?? ""}&user_id=${params?.userId}&start_date=${params?.start === "" ? "2020-01-01" : params?.start}&end_date=${endDateQuotation}&user_type=${params?.userType ?? ""}`, config).then((res) => res.data).catch((error) => error)
    }
    const reportTotalLeads = async (params) => {
      
        return await axios.get(`${mainUrlVTwo}/new-reports/sub/total-leads?company_id=${params?.companyId ?? ""}&channel_id=${params?.channelId ?? ""}&user_id=${params?.userId}&start_date=${params?.start ?? ""}&end_date=${params?.end ?? ""}&user_type=${params?.userType ?? ""}`, config).then((res) => res.data).catch((error) => error)
    }
    const reportLeadStatus = async (params) => {
    
        return await axios.get(`${mainUrlVTwo}/new-reports/sub/lead-status?company_id=${params?.companyId ?? ""}&channel_id=${params?.channelId ?? ""}&user_id=${params?.userId}&start_date=${params?.start ?? ""}&end_date=${params.end ?? ""}&user_type=${params?.userType ?? ""}`, config).then((res) => res.data).catch((error) => error)
    }
    const {data:dataDeals,isLoading:loadingDeals, error: errorDeals} = useQuery(['deals', isParams], () => reportDeals(isParams), {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity});
    const {data:dataActiveLeads, isLoading:loadingActiveLeads,error:errorActiveLeads} = useQuery(['activeLeads', isParams], () => reportActiveLeads(isParams), {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity});
    const {data:dataEstimations, isLoading:loadingEstimations,error:errorEstimations} = useQuery(['estimtions', isParams], () => reportEstimations(isParams), {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity});
    const {data:dataNewLeads, isLoading:loadingNewLeads,error:errorNewLeads} = useQuery(['newLeads', isParams], () => reportNewLeads(isParams), {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity});
    const {data:dataQuotations, isLoading:loadingQuotations,error:errorQuotations} = useQuery(['quotations', isParams], () => reportQuotations(isParams), {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity});
    const {data:dataTotalLeads, isLoading:loadingTotalLeads,error:errorTotalLeads} = useQuery(['totalLeads', isParams], () => reportTotalLeads(isParams), {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity});
    const {data:dataLeadStatus, isLoading:loadingLeadStatus,error:errorLeadStatus} = useQuery(['leadStatus', isParams], () => reportLeadStatus(isParams), {refetchOnWindowFocus: (query) => query.state.status !== "error", staleTime: Infinity});
    
    
   
    const dataReport = useMemo(() => {
      if(dataDeals !== undefined && dataActiveLeads !== undefined && dataEstimations !== undefined && dataNewLeads !== undefined && dataQuotations !== undefined && dataTotalLeads !== undefined && dataLeadStatus !== undefined){
        const newReports =  {
          data: {
              deals:dataDeals?.deals,
              active_leads:dataActiveLeads?.active_leads,
              estimation:dataEstimations?.estimation,
              new_leads:dataNewLeads?.new_leads,
              quotation:dataQuotations?.quotation,
              follow_up: {
                  total_activities:{
                      value: dataTotalLeads?.total_leads?.value,
                      compare: dataTotalLeads?.total_leads?.compare,
                      target_activities: dataTotalLeads?.total_leads?.target_leads
                  },
                  cold_activities:dataLeadStatus?.follow_up?.cold_activities,
                  hot_activities:dataLeadStatus?.follow_up?.hot_activities,
                  warm_activities:dataLeadStatus?.follow_up?.warm_activities
              },
              retail:dataDeals?.retail,
              exhibition: dataDeals?.exhibition,
              interior_design: dataDeals?.interior_design,
              original_date: dataDeals?.original_date,
              compare_date: dataDeals?.compare_date
          }
      }
          setHideButton(false);
          setFilterButton(false)
          dispatch(dataNewReports({data:newReports.data}))
          return newReports
      }
    },[dataDeals, dataActiveLeads, dataEstimations, dataNewLeads, dataQuotations, dataTotalLeads, dataLeadStatus, dispatch, setHideButton]);
    const messageDeals = dataDeals?.response?.data?.message
    if(messageDeals === "Unauthenticated." && countError === 0){
      window.location.reload()
      setCountError((prev) => prev + 1)
    }
    const newReports =  {
        data: {
            deals:dataDeals?.deals,
            active_leads:dataActiveLeads?.active_leads,
            estimation:dataEstimations?.estimation,
            new_leads:dataNewLeads?.new_leads,
            quotation:dataQuotations?.quotation,
            follow_up: {
                total_activities:{
                    value: dataTotalLeads?.total_leads?.value,
                    compare: dataTotalLeads?.total_leads?.compare,
                    target_activities: dataTotalLeads?.total_leads?.target_leads
                },
                cold_activities:dataLeadStatus?.follow_up?.cold_activities,
                hot_activities:dataLeadStatus?.follow_up?.hot_activities,
                warm_activities:dataLeadStatus?.follow_up?.warm_activities
            },
            retail:dataDeals?.retail,
            exhibition: dataDeals?.exhibition,
            interior_design: dataDeals?.interior_design,
            original_date: dataDeals?.original_date,
            compare_date: dataDeals?.compare_date
        }
    }

    const handleClickToSeeDetail = (event) => {
      
      const idTarget = event.currentTarget.id
      const seeDetailsData = [
        {
            name:"deals",
            epTyp: "invoice"
        },
        {
            name:"new-leads",
            epTyp: "leads"
        },
        {
            name:"active-leads",
            epTyp: "leads"
        },
        {
            name:"interior-design",
            epTyp: "interior-design"
        },
        {
            name:"retail",
            epTyp: "invoice"
        },
        {
            name:"quotation",
            epTyp: "invoice"
        },
        {
            name:"pipelines",
            epTyp: "brand-details"
        },
        {
            name:"HOT"
        },
        {
            name:"WARM"
        },
        {
            name:"COLD"
        }
      ]
      if(user?.data?.as.toUpperCase() === "SALES"){
        
        for(let i = 0; i <= seeDetailsData.length - 1; i++){
          const epType = seeDetailsData[i].epTyp;
          const slugType = seeDetailsData[i].name;
          if(slugType === idTarget){
            if(idTarget === "deals" || idTarget === "quotation" || idTarget === "retail"){
              history.push({
                pathname: `dashboard/see-details/invoice`,
                state: { 
                  dataUser: user?.data?.id,
                  data:user?.data,
                  typeUser: user?.data?.as?.toLowerCase(),
                  formatDate: newFilterDate,
                  invoiceType: idTarget,
                  idCompany:filterCompany, 
                  channels: filterChannels
                },
              }); 
              break;
            } 
            if(idTarget === "interior-design"){
              history.push({
                pathname: 'dashboard/see-details/interior-design',
                state:{
                  dataUser: user?.data?.id,
                  data:user?.data,
                  typeUser: user?.data?.as?.toLowerCase(),
                  formatDate: newFilterDate,
                  invoiceType: idTarget,
                  idCompany:filterCompany, 
                  channels: filterChannels
                }
              });
              break;
            } 
            if(idTarget === "new-leads" || idTarget === "active-leads"){
              history.push({
                pathname: 'dashboard/see-details/leads',
                state:{
                  dataUser: user?.data?.id,
                  data:user?.data,
                  typeUser: user?.data?.as?.toLowerCase(),
                  formatDate: newFilterDate,
                  invoiceType: idTarget,
                  statusActive: idTarget === seeDetailsData[2].name ? 1 : 0,
                  idCompany:filterCompany, 
                  channels: filterChannels
                }
              });
              break;
            }
            if(idTarget.toUpperCase() === "HOT" || idTarget.toUpperCase() === "WARM" || idTarget.toUpperCase() === "COLD"){
              history.push({
                pathname: `dashboard/see-details/follow-up/${idTarget}`,
                state:{
                  data: user?.data,
                  invoiceType: idTarget,
                  typeUser: user?.data?.as?.toLowerCase(),
                  formatDate: newFilterDate,
                  statusActv: idTarget,
                  idCompany:filterCompany, 
                  channels: filterChannels
                }
              });
              break;
            }
            if(idTarget.toUpperCase() === "PIPELINES"){
              setComparationPopup(true);
              break;
            }
          }
        } 
      }
    }
    if(loadingDeals || loadingActiveLeads || loadingEstimations || loadingNewLeads || loadingQuotations || loadingTotalLeads || loadingLeadStatus){
      return <LoadedComponent />
   }

   if(errorDeals || errorActiveLeads || errorEstimations || errorNewLeads || errorQuotations || errorTotalLeads || errorLeadStatus){
       return <h4>Terjadi Kesalahan</h4>
   }
  return !loading && localStorage.getItem("token") !== null && localStorage.getItem("token") !== undefined &&
  newReports !== undefined || newReports !== null&&
  channels &&
  usersList ? (
    <>
      <div className="report" id="report" style={{position:"relative"}}>
        <Filters
          setFilterCompany={setFilterCompany}
          setFilterChannels={setFilterChannels}
          setFilterUser={setFilterUser}
          setNewFilterDate={setNewFilterDate}
          filterCompany={filterCompany}
          channels={channels}
          usersList={usersList}
          user={user}
          isParams={isParams} 
          setIsLoading={setIsLoading}
          isTypeUser={user.data.as}
          setFilterButton={setFilterButton}
        />
        <Popup popup={comparationPopup} setPopup={setComparationPopup}>
          <ComporationPopUp isData={newReports?.data} isType="BRAND" isUser={user} isReport="pipelines"/>
        </Popup>
        

        {
          (loadingDeals || loadingActiveLeads || loadingEstimations || loadingNewLeads || loadingQuotations || loadingTotalLeads || loadingLeadStatus) && <LoadedComponent />
        }
        {
          (errorDeals || errorActiveLeads || errorEstimations || errorNewLeads || errorQuotations || errorTotalLeads || errorLeadStatus) && <h4>Terjadi Kesalahan</h4>
        }
        {(!loadingDeals || !loadingActiveLeads || !loadingEstimations || !loadingNewLeads || !loadingQuotations || !loadingTotalLeads || !loadingLeadStatus) && (<div className="report-cards row" style={{marginTop: "50px"}}>
        
          {newReports?.data !== undefined && (<NewReportCard 
          title="Deals"
          target={newReports?.data?.deals?.target_deals}
          value={newReports?.data?.deals?.value}
          targetTransaction={newReports?.data?.deals?.target_transaction}
          compare={newReports?.data?.deals?.compare}
          idCard="deals"
          handleClickToSeeDetail={handleClickToSeeDetail}
          datasSet="deals"
          isDataUser={user.data}
          />)}

          {newReports?.data !== undefined && (<NewReportCard 
          title="New Leads"
          target={newReports?.data?.new_leads?.target_leads}
          value={newReports?.data?.new_leads?.value}
          compare={newReports?.data?.new_leads?.compare}
          idCard="new-leads"
          handleClickToSeeDetail={handleClickToSeeDetail}
          datasSet="new-leads"
          isDataUser={user.data}
          />)}
          <div className="report-card col-md-3" style={{paddingLeft:"0"}}>
              <div className="report-card-wrapper p-3" style={{height: "8rem", cursor:user.data.as.toUpperCase() === "SALES" ? "pointer" : "auto"}} onClick={handleClickToSeeDetail} id="interior-design"data-status-type="interior-design">
                <p className='mb-2'>Interior Design</p>
                <h4 className='m-0' style={{color: "#F7AD97"}}>{newReports.data !== undefined && formatCurrency(newReports?.data?.interior_design?.value, true)}</h4>
                <p>Total Transaction: {newReports?.data?.interior_design?.total_transaction}</p>
              </div>
          </div> 
          <div className="report-card col-md-3" style={{paddingLeft:"0"}}>
              <div className="report-card-wrapper p-3" style={{height: "8rem", cursor:user?.data?.as.toUpperCase() === "SALES" ? "pointer" : "auto"}} onClick={handleClickToSeeDetail} id="retail"data-status-type="retail">
                <p className='mb-2'>Retails</p>
                <h4 className='m-0' style={{color: "#F5907B"}}>{newReports.data !== undefined && formatCurrency(newReports?.data?.retail?.value, true)}</h4>
                <p>Total Transaction: {newReports?.data?.retail?.total_transaction}</p>
              </div>
          </div>
          <div className="report-card col-md-3" style={{paddingLeft:"0"}}>
            
              <div className="report-card-wrapper p-3" style={{height: "8rem", cursor:user.data.as.toUpperCase() === "SALES" ? "pointer" : "auto"}} id="active-leads" onClick={handleClickToSeeDetail} data-status-type="active-leads">
                <p className='mb-2'>Active Leads</p>
                <h4 className='m-0' style={{color: "#4FD69B"}}>{newReports?.data?.active_leads?.value}</h4>
                <p></p>
              </div>
          </div>
          <div className="report-card col-md-3" style={{paddingLeft:"0"}}>
           
              <div className="report-card-wrapper p-3" style={{height: "8rem", cursor:user.data.as.toUpperCase() === "SALES" ? "pointer" : "auto"}} onClick={handleClickToSeeDetail} id="quotation" data-status-type="quotation">
                <p className='mb-2'>Quotation</p>
                <h4 className='m-0' style={{color: "#17519D", position: "relative"}}>{newReports.data !== undefined && formatCurrency(newReports?.data?.quotation?.value, true)} {parseInt(newReports?.data?.quotation?.value) < parseInt(newReports?.data?.quotation?.compare) ? (<span style={{width:"0", height:"0", borderLeft: "5px solid transparent", borderRight: "5px solid transparent", marginLeft: "10px", display: "inline-block", position: "absolute", top:"50%", transform: "translateY(-50%)", right:"0", borderTop:"10px solid red" }}></span>) : (<span style={{width:"0", height:"0", borderLeft: "5px solid transparent", borderRight: "5px solid transparent", marginLeft: "10px", display: "inline-block", position: "absolute", top:"50%", transform: "translateY(-50%)", right:"0", borderBottom:"10px solid green" }}></span>)}</h4>
                <p></p>
              </div>
          </div>
          <div className="report-card col-md-3" style={{paddingLeft:"0"}}>           
              <div className="report-card-wrapper p-3" style={{height: "8rem",  cursor:user.data.as.toUpperCase() === "SALES" ? "pointer" : "auto"}} onClick={handleClickToSeeDetail} id="pipelines" data-status-type="pipelines">
                <p className='mb-2'>Pipelines</p>
                <h4 className='m-0' style={{color: "#3F82D9", position: "relative"}}>{newReports.data && formatCurrency(newReports?.data?.estimation?.value, true)} {parseInt(newReports?.data?.estimation?.value) < parseInt(newReports?.data?.estimation?.compare) ? (<span style={{width:"0", height:"0", borderLeft: "5px solid transparent", borderRight: "5px solid transparent", marginLeft: "10px", display: "inline-block", position: "absolute", top:"50%", transform: "translateY(-50%)", right:"0", borderTop:"10px solid red" }}></span>) : (<span style={{width:"0", height:"0", borderLeft: "5px solid transparent", borderRight: "5px solid transparent", marginLeft: "10px", display: "inline-block", position: "absolute", top:"50%", transform: "translateY(-50%)", right:"0", borderBottom:"10px solid green" }}></span>)}</h4>
                <p></p>
              </div>
          </div>
          <div className="report-card col-md-3" style={{paddingLeft:"0"}}>
              <div className="report-card-wrapper p-3" style={{height: "8rem", cursor:user?.data?.as.toUpperCase() === "SALES" ? "pointer" : "auto"}} onClick={handleClickToSeeDetail} id="interior-design"data-status-type="interior-design">
                <p className='mb-2'>Exhibition</p>
                <h4 className='m-0' style={{color: "#F7AD97"}}>{newReports.data && formatCurrency(newReports?.data?.exhibition?.value, true)}</h4>
                <p>Total Transaction: {newReports?.data?.exhibition?.total_transaction}</p>
              </div>
          </div> 
        </div>
        )}

          {(<div>
            <div className="row-remove">
              <div className="col-md-6-remove">
                <div className="follow-up">
                  <div className="skills-content p-3 row" style={{cursor:"pointer"}}data-aos="fade-up"onClick={() => history.push(`/dashboard/follow-up-activities/status/${user?.data?.id}${newFilterDate.start !== "" ? "/" + newFilterDate.start : ""}${newFilterDate.end !== "" ? "/" + newFilterDate.end : ""}`)}>
                    <div className='total-follow-up col-lg-5' data-aos='fade-up' style={{cursor:"pointer"}}>
                      <h3 className="mb-3">Total Follow Ups</h3>
                      <h4 style={{color: "#17949D", position: "relative", width: "8rem"}}>{newReports?.data?.follow_up?.total_activities?.value} {parseInt(newReports?.data?.follow_up?.total_activities?.value) < parseInt(newReports?.data?.follow_up?.total_activities?.compare) ? (<span style={{width:"0", height:"0", borderLeft: "5px solid transparent", borderRight: "5px solid transparent", marginLeft: "10px", display: "inline-block", position: "absolute", top:"50%", transform: "translateY(-50%)", right:"0", borderTop:"10px solid red" }}></span>) : (<span style={{width:"0", height:"0", borderLeft: "5px solid transparent", borderRight: "5px solid transparent", marginLeft: "10px", display: "inline-block", position: "absolute", top:"50%", transform: "translateY(-50%)", right:"0", borderBottom:"10px solid green" }}></span>)}</h4>
                      <IsBar 
                        value={newReports?.data?.follow_up?.total_activities?.value}
                        target={newReports?.data?.follow_up?.total_activities?.target_activities}
                        colorPercent={"#17949D"}
                      />
                      <p>Target: {newReports?.data?.follow_up?.total_activities?.target_activities}</p>
                    </div>
                    <div className="follow-up-remove col-lg-7">
                    <div className="skills-content" data-aos="fade-up">
                      <h3 className='mb-3'>Lead Status</h3>
                      {newReports?.data?.follow_up === undefined || newReports?.data?.follow_up === null
                        ? ""
                        : followUpActivities.map((data,i) => {
                          const filterKeyObj = Object.keys(newReports?.data?.follow_up).filter(isData => {
                          
                            if(followUpActivities.includes(isData.split("_")[0].toUpperCase())){
                              return isData
                            }
                          })
                          const stringKey = filterKeyObj[i].split("_")[0];
                          const valueActivitiesFollowUp = newReports?.data?.follow_up[filterKeyObj[i]];
                          const totalValueActivities = newReports?.data?.follow_up?.total_activities?.value
                          return (
                            // :id?/:start?/:end?/:company_id?/:channels_id?
                              <div id={data} style={{ cursor:"pointer"}} onClick={() => history.push(`/dashboard/follow-up-activities/${stringKey}/${user?.data?.id}${newFilterDate.start !== "" ? "/" + newFilterDate.start : ""}${newFilterDate.end !== "" ? "/" + newFilterDate.end : ""}`)}key={i} >
                                <Skill
                                  title={stringKey}
                                  progress={
                                    (valueActivitiesFollowUp / totalValueActivities) * 100
                                  }
                                  color={pickColor(stringKey.toUpperCase())}
                                  value={valueActivitiesFollowUp}
                                />
                              </div>
                          )
                        })
                      }
                    </div>
                  </div>
                  </div>
                </div>
              </div>
            </div>
          </div>)}
      </div>
    </>
  ) : (<LoadedComponent />)
}

const mapStateToProps = (state) => ({
  auth: state.auth,
  target: state.target,
  prosesData: state.prosesData
});

export default connect(mapStateToProps)(Report);

