import axios from "axios";
import React, { useEffect, useState } from "react";
import { connect, useDispatch } from "react-redux";
import { mainUrl } from "../../api/api";
import { isValidate } from "../../lib/Validate";
import { loadCustomers } from "../../redux/action/customer";
import Button from "../Button/Button";
import SelectorKabkot from "../Selectors/SelectorKabkot";
import SelectorKecamatan from "../Selectors/SelectorKecamatan";
import SelectorKelurahan from "../Selectors/SelectorKelurahan";
import SelectorProvinsi from "../Selectors/SelectorProvinsi";
import kecamatanList from "../../api/data_kecamatan.json";
import kabkotList from "../../api/data_kabkot.json"
import countryList from "../../api/countries";
import provinsiList from "../../api/provinces";
const AddLeadForm = ({
  customer: { customers, categories },
  newCustomer,
  setPopup,
  setUpdate,
  update,
  setIsNewCustomer,
  isBillingAddress = true
}) => {
 
  const dispatch = useDispatch();
  const [isAdditionalAddress, setIsAdditionalAddress] = useState({
    address_line_1: "",
    address_line_2: "",
    address_line_3: "",
    province: "",
    city: "",
    kelurahan: "",
    kecamatan: "",
    country: "",
    addresType: ""
  })
  const [customersData, setCustomersData] = useState();
  const [type, setType] = useState("");
  const [label, setLabel] = useState("");
  const [interest, setInterest] = useState("");
  const [leadCategory, setLeadCategory] = useState("");
  const [isUnhandled, setIsUnhandled] = useState(false);
  const [customerId, setCustomerId] = useState();
  const [province, setProvince] = useState("");
  const [city, setCity] = useState("");
  const [country, setCountry] = useState("");
  const [kelurahan, setKelurahan] = useState("");
  const [kecamatan, setKecamatan] = useState("")
  const [search, setSearch] = useState("");

  //   validation
  const [customerIdValidation, setCustomerIdValidation] = useState();
  const [typeValidation, setTypeValidation] = useState();
  const [leadCategoryValidation, setLeadCategoryValidation] = useState();

  useEffect(() => {
    dispatch(loadCustomers());
  }, [dispatch]);

  useEffect(() => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
    newCustomer && setCustomerId(newCustomer.id);
    const getCustomer = async () => {
      try {
        const res = await axios.get(
          `${mainUrl}/customers?filter[search]=${
            search !== ""
              ? search
              : newCustomer
              ? newCustomer.phone || newCustomer.email || newCustomer.first_name
              : ""
          }`,
          config
        );
        setCustomersData(res.data.data);
        setCustomerId(res.data.data ? res.data.data[0].id : "");
      } catch (error) {}
    };

    getCustomer();
  }, [search, newCustomer]);

  const addLead = async () => {
    const body = {
      type: type,
      label: label,
      customer_id: parseInt(customerId),
      is_unhandles: isUnhandled,
      lead_category_id: parseInt(leadCategory),
      interest: interest,
    };
    setPopup(false);
    setUpdate(!update);
    setIsNewCustomer && setIsNewCustomer(false);
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
    try {
      const res = await axios.post(`${mainUrl}/leads`, body, config);
      if(res.status == 200 || res.status == 201){
        window.location.reload();
      }
    } catch (error) {
      console.error(error);
    }
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    isValidate(customerId)
      ? setCustomerIdValidation(true)
      : setCustomerIdValidation(false);
    isValidate(type) ? setTypeValidation(true) : setTypeValidation(false);
    isValidate(leadCategory)
      ? setLeadCategoryValidation(true)
      : setLeadCategoryValidation(false);

    if (
      !isValidate(customerId) &&
      !isValidate(type) &&
      !isValidate(leadCategory)
    ) {
      addLead();
      newCustomer && !isBillingAddress && updateAddressIsBillingAddressUnchecked()
    }
  };
  const updateAddressIsBillingAddressUnchecked = async () => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };
    const addressData = {
      address_line_1: isAdditionalAddress?.address_line_1 ?? "",
      address_line_2: isAdditionalAddress?.address_line_2 ?? "",
      address_line_3: isAdditionalAddress?.address_line_3 ?? "",
      city: isAdditionalAddress?.city ?? "",
      country: isAdditionalAddress?.country ?? "",
      province: province,
      type: isAdditionalAddress?.addresType,
      customer_id: customerId,
      phone:newCustomer?.phone
    };
    try {
      const res = await axios.put(
        `${mainUrl}/addresses/${
          newCustomer.default_address_id
            ? newCustomer.default_address_id
            : ""
        }`,
        addressData,
        config
      );
     
    } catch (error) {
      console.error(error);
    }
  }
  
  return (
    customers && (
      <form
        onSubmit={(e) => {
          handleSubmit(e);
        }}
      >
        <h3>Add Lead</h3>
        <hr />
        <div className=" mt-4 mb-4">
          <div className="mt-3">
            <label>
              Customer<span>*</span>
            </label>
            <div className="d-flex">
              <input
                type="text"
                className="form-control"
                name="customer"
                style={{ height: "41px", width: "40%", fontSize: "11px" }}
                placeholder="Search by name,email,phone"
                onChange={(e) => setSearch(e.target.value)}
                autoComplete="off"
              />

              <select
                className={`form-select ${
                  customerIdValidation && isValidate(customerId) && "is-invalid"
                }`}
                name="title"
                id="title"
                style={{ height: "41px" }}
                onChange={(e) => setCustomerId(e.target.value)}
              >
                {customersData &&
                  customersData.map((customer) => {
                    return (
                      <option value={customer.id} key={customer.id}>
                        {`${customer.first_name} ${customer.last_name}  (${customer.email})  (${customer.phone})`}
                      </option>
                    );
                  })}
              </select>
              {isValidate(customerId) && (
                <div className="invalid-feedback">
                  Please select a valid customer.
                </div>
              )}
            </div>
          </div>
          <div className="mt-3">
            <label>
              Type<span>*</span>
            </label>
            <select
              className={`form-select ${
                typeValidation && isValidate(type) && "is-invalid"
              }`}
              name="type"
              id="type"
              style={{ height: "41px" }}
              onChange={(e) => setType(e.target.value)}
            >
              <option value="">Please Select Type</option>
              <option value="PROSPECT">Prospect</option>
              <option value="DEAL">DEAL</option>
              <option value="LEADS">Leads</option>
            </select>
            {isValidate(type) && (
              <div className="invalid-feedback">
                Please select a valid type.
              </div>
            )}
          </div>
          <div className="mt-3">
            <label>
              Label<span>{"(optional)"}</span>
            </label>
            <input
              type="text"
              className="form-control"
              name="label"
              style={{ height: "41px" }}
              placeholder="Input your label here"
              onChange={(e) => setLabel(e.target.value)}
            />
          </div>
          <div className="mt-3">
            <label>
              Interest<span>{"(optional)"}</span>
            </label>
            <input
              type="text"
              className="form-control"
              name="interest"
              style={{ height: "41px" }}
              placeholder="Input your lead interest"
              onChange={(e) => setInterest(e.target.value)}
            />
          </div>
          <div className="mt-3">
            <label>
              Lead Category<span>*</span>
            </label>
            <select
              className={`form-select ${
                leadCategoryValidation &&
                isValidate(leadCategory) &&
                "is-invalid"
              }`}
              name="type"
              id="type"
              style={{ height: "41px" }}
              onChange={(e) => setLeadCategory(e.target.value)}
            >
              <option value="">Please Select Type</option>
              {categories.map((category) => {
                return (
                  <option value={category.id} key={category.id}>
                    {category.name}
                  </option>
                );
              })}
            </select>
            {isValidate(leadCategory) && (
              <div className="invalid-feedback">
                Please select a valid Lead Category.
              </div>
            )}
          </div>
          <div className="mt-3">
            <div className="form-check">
              <input
                className="form-check-input"
                type="checkbox"
                value="true"
                id="flexCheckDefault"
                onChange={(e) => setIsUnhandled(!isUnhandled)}
              />
              <label className="form-check-label" htmlFor="flexCheckDefault">
                Unhandled
              </label>
            </div>
          </div>
          {!isBillingAddress &&    <div className=" mt-4 mb-4">
            <div className="mt-3">
              <label>
                Address Line 1<span>*</span>
              </label>
              <input
                type="text"
                id="address-add"
                name="address-add"
                className={`form-control ${isAdditionalAddress.address_line_1 &&
                  isValidate(isAdditionalAddress.address_line_1) &&
                  "is-invalid"
                  }`}
                placeholder="Input address here"
                style={{ height: "41px" }}
                value={isAdditionalAddress.address_line_1}
                onChange={(e) => setIsAdditionalAddress((prev) => ({
                  ...prev,
                  address_line_1:e?.target?.value ?? ""
                }))}
              />
              {isValidate(isAdditionalAddress.address_line_1) && (
                <div className="invalid-feedback">Address is empty.</div>
              )}
            </div>
            <div className="mt-3">
              <label>Address Line 2</label>
              <input
                type="text"
                id="address-add"
                name="address-add"
                className="form-control"
                placeholder="Input address here"
                style={{ height: "41px" }}
                value={isAdditionalAddress.address_line_2}
                onChange={(e) => setIsAdditionalAddress((prev) => ({
                  ...prev,
                  address_line_2:e?.target?.value ?? ""
                }))}
              />
            </div>
            <div className="mt-3">
              <label>Address Line 3</label>
              <input
                type="text"
                id="address-add"
                name="address-add"
                className="form-control"
                placeholder="Input address here"
                style={{ height: "41px" }}
                value={isAdditionalAddress.address_line_3}
                onChange={(e) => setIsAdditionalAddress((prev) => ({
                  ...prev,
                  address_line_3:e?.target?.value ?? ""
                }))}
              />
            </div>
            <div className="mt-3">
              <label>Province</label>
              <SelectorProvinsi onChange={((e) => {
                setProvince(e.value)
              })} values={""} isMulti={false}/>
              <select
                className={`form-select`}
                id="province-add"
                name="province-add"
                style={{ height: "41px" }}
                onChange={(e) => {
                  setIsAdditionalAddress((prev) => {
                    return {
                      ...prev,
                      province: JSON.parse(e.target.value)
                    }
                  })
                  // setProvince(JSON.parse(e.target.value));
                }}
                defaultValue={""}
              // ref={province}
              >
                <option value="">Select Province</option>
                {provinsiList.map((province) => {
                  return (
                    <option
                      value={JSON.stringify({
                        id: province.id,
                        name: province.name,
                      })}
                      key={province.id}
                    >
                      {province.name}
                    </option>
                  );
                })}
              </select>
            </div>
            <div className="mt-3">
              <label>City</label>
              <SelectorKabkot onChange={((e) => {
                setCity(e.value)
              })} values={""} isMulti={false} filterCity={province == "" ? null : provinsiList?.filter((isProv) => isProv.provinsi?.toUpperCase() == province?.toUpperCase())[0]?.id}/>
              
            </div>
            <div className="mt-3">
              <label>Kecamatan</label>
              <SelectorKecamatan onChange={(e) => {
                setKecamatan(e?.value ?? "");
              }} values={""} isMulti={false} filterCity={city == "" ? null : kabkotList?.filter((isCty) => isCty.kabupaten_kota?.toUpperCase() == city?.toUpperCase())[0]?.id}/>
            </div>
            <div className="mt-3">
            <label>Kelurahan</label>
              <SelectorKelurahan  onChange={(e) => {
                setKelurahan(e?.value ?? "");
              }} values={""} isMulti={false} filterKec={kecamatan === "" ? null : kecamatanList?.filter((data) => data.kecamatan?.toUpperCase() == kecamatan?.toUpperCase())[0]?.id}/>
            </div>
              
            
            <div className="mt-3">
              <label>Country</label>
              <select
                className={`form-select`}
                id="country-add"
                name="country-add"
                style={{ height: "41px" }}
                onChange={(e) => {
                  setIsAdditionalAddress((prev) => {
                    return {
                      ...prev,
                      country:e.target.value
                    }
                  })
                }}
              >
                <option value="">Select Country</option>
                {countryList.map((country, i) => {
                  return (
                    <option value={country} key={i}>
                      {country}
                    </option>
                  );
                })}
              </select>
            </div>
            
            <div className="mt-3">
              <label>
                Address Type<span>*</span>
              </label>
              <select
                className={`form-select ${typeValidation && isValidate(isAdditionalAddress.addresType) && "is-invalid"
                  }`}
                id="addressType-add"
                name="addressType-add"
                style={{ height: "41px" }}
                onChange={(e) => setIsAdditionalAddress((prev) => ({
                  ...prev,
                  addresType:e.target.value
                }))}
              >
                <option value="">Select Address Type</option>
                <option value={"ADDRESS"}>Address</option>
                <option value={"DELIVERY"}>Delivery</option>
                <option value={"BILLING"}>Billing</option>
              </select>
              {isValidate(isAdditionalAddress.addresType) && (
                <div className="invalid-feedback">
                  Please select a valid address type.
                </div>
              )}
            </div>
           
          </div>}
        </div>

        <div>
          <Button
            title={"Submit"}
            icon={""}
            btnWidth={"100%"}
            btnStyle={"primary-btn"}
          />
        </div>
      </form>
    )
  );
};

const mapStateToProps = (state) => ({
  customer: state.customer,
});

export default connect(mapStateToProps)(AddLeadForm);
