import { formatCurrency } from "../../../../api/format";
export const loopDataExp = (dataDetails) => {
    let objExp = {};
    const arrExp = [];
    dataDetails.forEach((isData, indx) => {
     
      objExp["No"] = indx + 1;
      objExp["Name"] = isData?.name;
      objExp["Deals"] = formatCurrency(isData?.deals?.value, true).replace(
        /([A-Za-z])\w+/g,
        ""
      );
      objExp["NewLeads"] = isData?.new_leads?.value;
      objExp["InteriorDesign"] = formatCurrency(
        isData?.interior_design?.value,
        true
      ).replace(/([A-Za-z])\w+/g, "");
      objExp["Retails"] = formatCurrency(isData?.retail.value, true).replace(
        /([A-Za-z])\w+/g,
        ""
      );
      objExp["ActiveLeads"] = isData?.active_leads?.value;
      objExp["Quotation"] = formatCurrency(
        isData?.quotation.value,
        true
      ).replace(/([A-Za-z])\w+/g, "");
      objExp["Pipelines"] = formatCurrency(
        isData?.estimation.value,
        true
      ).replace(/([A-Za-z])\w+/g, "");
      objExp["FollowUp"] = isData?.follow_up?.total_activities?.value;
      objExp["Hot"] = isData?.follow_up?.hot_activities;
      objExp["Warm"] = isData?.follow_up?.warm_activities;
      objExp["Cold"] = isData?.follow_up?.cold_activities;

      arrExp.push(objExp);
      objExp = {};
    });
    return arrExp
}