import React from "react"
import { DataReportSeeDetails, loopDataExp } from "../funcSeeDetails";
import * as XLSX from "xlsx";
import ExportImage from "../../../../assets/icons/export.png";
import Button from "../../../../components/Button/Button";
const HeadFilter = ({setCountRender, dataDetails, setDataDetails, newFilterDate, stateHistory, config, setTextButton, setMountUser,setIsLoad, setSearchValue, setCountMore, setNewFilterDate, setFilBum, dataSearch, textButton, searchValue, filterBum, user, setFilterButton, showButton, isLoad, countMore}) => {
    const handleExportButton = async () => {
        const resArrDataExp = loopDataExp(dataDetails)
        const wb = XLSX.utils.book_new();
        const ws = XLSX.utils.json_to_sheet(resArrDataExp);
        XLSX.utils.book_append_sheet(wb, ws, "report");
        XLSX.writeFile(wb, "report.xlsx");
  };
  const handleSearchUser = async (e, user) => {
    const resFunc = await DataReportSeeDetails([user], 0, newFilterDate, stateHistory, config);
    setDataDetails([resFunc])
    setCountMore({
      min:  0,
      search:true,
      max: 5,
      isLoaded:false,
    })
  }
  const handleClickEvent = (e) => {
    const splitSpace = e.target.textContent.split(" ").join("_");
    setCountMore({
      min:  0,
      max: 5
    })
    setDataDetails([])
    setTextButton(splitSpace);
    setMountUser(true);
    setIsLoad(true);
    setSearchValue("")
  };
  const handleChangeDate = (e) => {
    setNewFilterDate((prev) => {
      return {
        ...prev,
        [e.target.name]: e.target.value,
      };
    });
  };
  const handleChangeBum = (e) => {
    setFilBum(e.target.value);
  };
  const handleChangeSearch = (e) => {
    setSearchValue(e.target.value);
  };
    return (
        <div className="filter-table" style={{ position: "relative" }}>
          <div class="col-auto d-flex" style={{ gap: "20px" }}>
            <div style={{position:"relative"}}>
            <input
              type="text"
              id="search-table"
              class="form-control"
           
              onChange={handleChangeSearch}
              placeholder="Search"
              value={searchValue}
            />
            <div style={{position:"absolute", bottom:"-2.8rem", zIndex:"5", height:"100%"}}>
              <ul  class="list-group list-group-flush" >
              {dataSearch.length !== 0 && dataSearch?.map((user,i) => {
                return (
                  <React.Fragment key={i}>
                    <li class="list-group-item" style={{cursor:"pointer"}} onClick={(e) => handleSearchUser(e, user)}>{user.name}</li>
                  </React.Fragment>
                )
              })}
              </ul>
            </div>
            </div>
            {textButton?.toUpperCase() === "SALES" && (
              <select
                style={{
                  display:
                    textButton?.toUpperCase() === "SALES" ? "block" : "none",
                  width: "10rem",
                }}
                className="form-select"
                name="channels"
                onChange={handleChangeBum}
              >
                <option value="">Select Bum</option>
                {filterBum &&
                  filterBum?.details?.map((isData) => {
                    return <option value={isData.id}>{isData.name}</option>;
                  })}
              </select>
            )}
            <div style={{ display: "flex", alignItems: "center" }}>
              <input
                type="date"
                id="start"
                name="start"
                className="form-control"
                placeholder="Start Month"
                onChange={handleChangeDate}
              />
              <div className="input-group-addon" style={{ margin: "0 10px" }}>
                to
              </div>
              <input
                type="date"
                id="end"
                name="end"
                className="form-control"
                placeholder="End Month"
                onChange={handleChangeDate}
                style={{ margin: "0" }}
              />
            </div>
            <Button
              onClick={(e) => {
                setCountRender(0)
                setIsLoad(true);
                setFilterButton(true);
              }}
              icon=""
              title="Filter"
              style={{ width: "11rem!important" }}
              btnStyle={"primary-btn"}
            />
          </div>

          <div
            className="btn-filter d-flex justify-content-around"
            style={{
              padding: "20px 0",
              display:
                user !== null && user?.data?.as.toUpperCase() === "DIRECTOR"
                  ? "block"
                  : "none",
              marginBottom: "30px",
            }}
          >
            {!isLoad && countMore.isLoaded !== true && Object.keys(showButton).map((d) => {
              if (d.toUpperCase() === user?.data?.as?.toUpperCase()?.split(" ")?.join("_")) {
                return showButton[d].map((tb, i) => {
                  
                  return (
                    <div
                      onClick={handleClickEvent}
                      style={{
                        position: "relative",
                        cursor: "pointer",
                      }}
                      key={i}
                    >
                      <span style={{ color: "black", fontWeight: "bold" }}>
                        {tb}
                      </span>
                      <div
                        style={{
                          position: "absolute",
                          bottom: "-10px",
                          width: "100%",
                          height: "4px",
                          backgroundColor: "#17949d",
                          display:
                            textButton?.toUpperCase()?.split(" ")?.join("-") ===
                            tb.split(" ").join("_").toUpperCase()
                              ? "block"
                              : "none",
                        }}
                      ></div>
                    </div>
                  );
                });
              }
            })}
          </div>
          
          {!isLoad && countMore.isLoaded !== true && (<button
            onClick={handleExportButton}
            style={{
              border: "0",
              background: "rgb(0,0,0,0)",
              position: "absolute",
              left: "0",
              top: "100px",
            }}
          >
            <img
              src={ExportImage}
              alt="icon export"
              style={{ width: "20px", height: "20px" }}
            />
            Export Report
          </button>)}
        </div>
    )
}

export default HeadFilter