import axios from "axios";
import moment from "moment";
import React, { useEffect, useState, useMemo } from "react";
import { mainUrl } from "../../api/api";
import { isValidate } from "../../lib/Validate";
import Activity from "../ActivityDetail/Activity";
import Button from "../Button/Button";
import LoadedComponent from "../Loaded/LoadedComponent";
import useCustomerActivitiesList from "../../api/useCustomerActivitiesList";
const CustomerActivities = (props) => {
  const { customer_id, leads_id, refresh, idCustomer } = props;
  const [activityDetail, setActivityDetail] = useState(false);
  const [customerActivities, setCustomerActivities] = useState(null);
  const [customerActivity, setCustomerActivity] = useState(null);
  const [orderId, setOrderId] = useState(null);
  const [leadId, setLeadId] = useState(null)
  const [searchState, setSearchState] = useState({
    customerId: idCustomer !== undefined ? idCustomer : customer_id,
    perPage: 5,

  });
  const {data:customerActivitesData, isLoading, error, hasNextPage, fetchNextPage, isFetchingNextPage} = useCustomerActivitiesList({searchState});
  const customerActivitie = useMemo(() => {
    if(!customerActivitesData){
      return null
    }
    const reduced = customerActivitesData?.pages?.reduce((curr,arr) => {
      return [...curr, arr?.data ?? null]
    }, []);

    const concated = [].concat(...reduced);
    return concated
    
  }, [customerActivitesData]);
  useEffect(() => {
    const config = {
      headers: {
        "Content-Type": "application/json",
        Authorization: `Bearer ${localStorage.token}`,
      },
    };

    const getCustomerActivities = async () => {
      
      try {
        const res = await axios.get(
          `${mainUrl}/customers/${idCustomer !== undefined ? idCustomer : customer_id}/activities`,
          config
        );
        setCustomerActivities(res.data.data);
      } catch (error) {
        console.error(error);
      }
    };
    getCustomerActivities();
  }, [leads_id, customer_id, refresh]);

  const handleClickDetail = (activity) => {
    setActivityDetail(!activityDetail);
    setCustomerActivity(activity);
    console.log(activity, "check activitiy")
    setLeadId(activity?.lead?.id ?? 0)
    setOrderId(activity.order ? activity.order.id : null);
  };
  if(isLoading){
    return (<LoadedComponent />)
  }
  if(error){
    return (<h4>Terjadi kesalahan pada server...</h4>)
  }
  return  (
    <div className="mt-4">
      <h3>ACTIVITY</h3>
      <table className="data" style={{ margin: "10px 0" }}>
        <thead>
          <tr>
            <th>Date</th>
            <th>Invoice Number</th>
            <th>Follow Up</th>
            <th>Store Location</th>
            <th>Payment</th>
            <th>Quotation</th>
            <th>Sales</th>
            <th>Status</th>
            <th>Action</th>
          </tr>
        </thead>
        <tbody>
          {customerActivitie && customerActivitie?.map((activity) => {
            return (
              <tr key={activity.id}>
                <td>
                  {!isValidate(activity.follow_up_datetime)
                    ? moment(activity.follow_up_datetime).format("MM/DD/YYYY")
                    : ""}
                </td>
                <td>
                  {!isValidate(activity.order)
                    ? activity.order.invoice_number
                    : ""}
                </td>
                <td>
                  {!isValidate(activity.follow_up_method)
                    ? activity.follow_up_method
                    : ""}
                </td>
                <td>
                  {!isValidate(activity.channel.name)
                    ? activity.channel.name
                    : ""}
                </td>
                <td>
                  {!isValidate(activity.order)
                    ? activity.order.payment_status
                    : ""}
                </td>
                <td>
                  {!isValidate(activity.order) ? activity.order.status : ""}
                </td>
                <td>
                  {!isValidate(activity.user.name) ? activity.user.name : ""}
                </td>
                <td>{!isValidate(activity.status) ? activity.status : ""}</td>
                <td>
                  <div
                    onClick={() => {
                      localStorage.setItem("lead_id", leads_id)
                      localStorage.setItem("act_id", activity?.id)
                      handleClickDetail(activity)
                    }}
                    className="activity-detail-btn"
                  >
                    <img
                      src="/Asset/Action Icon/eye.png"
                      style={{ marginRight: "5px" }}
                      alt="eye"
                    />
                    See Detail
                  </div>
                </td>
              </tr>
            );
          })}
        </tbody>
      </table>
      {isFetchingNextPage ? (<LoadedComponent />): hasNextPage ?<div
        
        style={{ width: "100%", display:"flex",justifyContent:"center" }}
      >
        <button style={{color:"#17949d",border:"0", background:"transparent" }} onClick={fetchNextPage}>See More</button>
      </div> : ""}
      {customerActivity ? (
        <Activity
          activityDetail={activityDetail}
          setActivityDetail={setActivityDetail}
          customerActivity={customerActivity}
          orderId={orderId}
          leads_id={leadId}
        />
      ) : (
        ""
      )}
    </div>
  );
};

export default CustomerActivities;
