import React, { useEffect, useState } from 'react';
import { useHistory } from 'react-router-dom';
import { getAllDataProducts, addCart } from './apiProduct';
import Axios from 'axios';
// import { DateRange } from 'react-date-range';
import ComporationPopUp from '../../../components/Popup/Popup Component/ComporationPopUp';
import Button from '../../../components/Button/Button';
import LoadedComponent from '../../../components/Loaded/LoadedComponent';
import { mainUrl } from '../../../api/api';
import { connect } from 'react-redux';
import Popup from '../../../components/Popup/Popup';
const DetailChannel = ({auth: { user, loading }}) => {
    const [data, setData] = useState([]);
    // const [locationsData, setLocationsData] = useState(null);
    // const [dataSearch, setDataSearch] = useState(null);
    const [isLoading, setIsLoading] = useState(true);
    const [messageError, setMessageError] = useState("");
    const [comparationPopup, setComparationPopup] = useState(false)
    // const [modals, setModals] = useState(false);
    const [skuProduct, setIsSkuProduct] = useState("")
    const history = useHistory();
    const stateHistory = history?.location?.state;
    useEffect(() => {
        const fetchingData = async () => {
            const res = await getAllDataProducts("",stateHistory?.data?.covering.product_id);
            if(res.success){
                setData(res?.data?.data);
            }
            if(!res.success){
                setMessageError(res.message);
            }
            setIsLoading(false)
        }
        
        fetchingData();
    },[stateHistory]);
    useEffect(() => {
        const fetchingLocations = async () => {
            
        }
        data !== null && fetchingLocations();
    }, [data]);
    const handleDataLocations = async (isData) => {
        setIsSkuProduct(isData.sku)
        setComparationPopup(!comparationPopup);
      
    }
    const handleAddToCart = async (dataCart) => {
        const config = {
            headers: {
              "Content-Type": "application/json",
              Authorization: `Bearer ${localStorage.token}`,
            },
        };
        const item = {
            items: [
                {
                    id: dataCart.id,
                    quantity:1,
                    sku: dataCart.sku
                }
            ]
        }
        const res = await Axios.put(`${mainUrl}/carts`, {
            headers:{
                "Content-Type": "application/json",
                Authorization: `Bearer ${localStorage.token}`
            },
            body: item
        })
        // const res = await addCart(JSON.stringify(item));
        // console.log(res, "check res")
        // if(res.status){
        //     history.push({
        //         pathname: "/dashboard/add/cart",
        //         state:{
        //             item: res.data
        //         }
        //     })
        // }

    }
    return(
        <>
            <div className='container'>
                <div className='container-card' style={{display:"flex", flexWrap:"wrap", justifyContent:"space-between", gap:"10px"}}>
                    {
                        !isLoading && data.length !==0 ? data?.map((isData, indx) => {
                            return (
                                <div className="card" key={indx} style={{width:"45%", marginBottom: "25px"}}>
                                    <div className="card-body">
                                        <h5 className="card-title">{isData.name}</h5>
                                        <p className="card-text" style={{color: "#c4c4c4"}}>SKU: {isData.sku}</p>
                                       <div style={{display:"flex", flexDirection:"column", gap:"10px"}}>
                                            <Button onClick={(e) => handleAddToCart(isData)}icon="" title="Cart+" btnWidth="100%" btnStyle={"primary-btn"} />
                                            <Button onClick={(e) => handleDataLocations(isData)}icon="" title="Stock" btnWidth="100%" btnStyle={"primary-btn"} />
                                       </div>
                                    </div>
                                </div>
                            )
                        }) : !isLoading && messageError !== "" ? (<h2 style={{textAlign:"center"}}>Terjadi Kesalahan Pada Server</h2>) : !isLoading && data.length === 0 ? (<h2 style={{textAlign:"center"}}>Tidak Memiliki Stock</h2>) : (<div style={{width:"100%"}}><LoadedComponent /></div>)
                    }
                </div>
                <Popup popup={comparationPopup} setPopup={setComparationPopup}>
                    {skuProduct !== "" && <ComporationPopUp isSku={skuProduct}isData={[]} isType="PRODUCT" isUser={user}/>}
                </Popup>
            </div>
        </>
    )
}
const mapStateToProps = (state) => ({
    auth: state.auth,
    prosesData: state.prosesData
  });
export default connect(mapStateToProps)(DetailChannel)