import react from 'react';

const IsBar = ({value, target, colorPercent}) => {
    const resPercent = value === 0 || target === 0 ? "0" : parseInt((value / target) * 100)
    return(
        <div className="progress" style={{backgroundColor: "#e9ecef !important"}} ref={element => {
            if(element){
                element.style.setProperty("background-color", "#e9ecef", "important");
            }
        }}>
            <div className="progress-bar" role="progressbar" style={{width: `${resPercent}%`, backgroundColor: colorPercent}} aria-valuenow={resPercent} aria-valuemin="0" aria-valuemax="100">{resPercent}%</div>
        </div>
    )
}

export default IsBar