import React, {useCallback, useMemo} from 'react';

import AsyncSelect from 'react-select/async';
import kelurahanList from "../../api/data_kelurahan.json";

const SelectorKelurahan = ({
    values,
    onChange,
    isMulti = false,
    filterKec = null
  }) => {
    const loadOptions = (search, callback) => {
         setTimeout(() => {
            const filterdData = kelurahanList.filter((i) =>
                i.kelurahan.toLowerCase().includes(search.toLowerCase()) && i.kecamatan_id == filterKec
              ).map((i) => ({value: i.kelurahan, label:i.kelurahan}))
              return callback(filterdData.slice(0, 10))
        }, 500)
      }
 
    const options = kelurahanList?.filter((data) => data?.kecamatan_id == filterKec).map((data) => ({
      value: data.kelurahan,
      label: data.kelurahan,
    })).slice(0,10);
 
    return (
      <>
        <AsyncSelect
        isDisabled={!filterKec ? true : false}
          isMulti={isMulti}
          onChange={onChange}
          defaultOptions={options}
          cacheOptions
          loadOptions={loadOptions}
          placeholder="Search Kelurahan..."
          defaultValue={
            (values === "" || values?.length === 0) ? ""
            : {
                  value: kelurahanList?.find(
                    (data) =>
                      data.kelurahan.toLowerCase() == values.toLowerCase()
                  )?.kelurahan ?? "",
                  label: kelurahanList?.find(
                    (data) =>
                      data.kelurahan.toLowerCase() == values.toLowerCase()
                  )?.kelurahan ?? "",
                }
             
          }
        />
      </>
    );
  };
  
  export default SelectorKelurahan;
  