export const getDataReport = async (
  typeReport,
  filterCompany,
  filterChannels,
  userId,
  startDate,
  endDate,
  config
) => {
  const isEndDate = typeReport === "quotations" && endDate === "" ? moment(new Date()).format("YYYY-MM-DD") : endDate
  return Axios.get(
    `${mainUrl}/new-reports/sub/${typeReport}?company_id=${filterCompany}&channel_id=${filterChannels}&user_id=${userId}&start_date=${typeReport === "quotations" && startDate === "" ? "2020-01-01":startDate}&end_date=${isEndDate}`,
    config
  )
    .then((resData) => resData?.data)
    .catch((error) => error.response);
};

